css:
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap");

/* ═══════════════════════════════════════════════════════════════════════════
   LIFE CALL CENTRE ERP — CC DASHBOARD
   VISUAL LAYER v10  ·  "COMMAND" PREMIUM THEME
   ───────────────────────────────────────────────────────────────────────────
   This file replaces the page Style field ONLY.
   No business logic, no data, no API, no field names are touched.
   Every class name, id and DOM hook used by the page JS is preserved.
   Built on the LIFE ERP Master UI/UX Design System (UI KIT v3 tokens).
   ═══════════════════════════════════════════════════════════════════════════ */

/* ──────────────────────────────────────────────────────────────────
   1 · DESIGN TOKENS
   ────────────────────────────────────────────────────────────────── */
.cc-erp-root{
  --green:#0B5D3B;   --green-d:#06331F;  --green-dd:#042418;
  --green-l:#12764C; --green-x:#2FA46F;  --green-soft:#EAF4EE;
  --teal:#0E7C6B;    --teal-l:#14A08B;
  --gold:#B8901F;    --gold-l:#D9B54A;   --gold-bg:#FBF3DC; --gold-br:#EAD9A6;
  --mint:#E9F5ED;    --mint-2:#D7ECE0;   --mint-3:#BFDFCE;

  --ink:#12211A;     --ink-2:#3C5347;    --ink-3:#6A7C72;   --ink-4:#95A39B;
  --cream:#FAF7EF;   --cream-2:#F4EFE2;  --cream-3:#EFE9DA; --card:#FFFFFF;
  --line:#E7E2D5;    --line-2:#D8D2C2;   --line-g:#DCE8E1;  --line-gg:#C9E0D2;

  --ok:#17794E;      --ok-bg:#E6F4EC;    --ok-br:#BEE1CD;
  --warn:#9A6B05;    --warn-bg:#FBF1DA;  --warn-br:#EBD8A6;
  --crit:#9E2C22;    --crit-bg:#FAE9E6;  --crit-br:#EEC5BE;
  --info:#1E4E86;    --info-bg:#E9F0F9;  --info-br:#C6D8EE;
  --sp:#5F3C93;      --sp-bg:#F0EAFA;    --sp-br:#D9CBF0;

  --r:12px; --r-s:9px; --r-xs:6px; --r-pill:999px;
  --sh:0 1px 2px rgba(18,33,26,.05),0 2px 6px rgba(18,33,26,.05);
  --sh-2:0 4px 16px rgba(18,33,26,.10);
  --sh-3:0 18px 48px rgba(6,35,22,.28);
  --sh-mast:0 1px 0 rgba(255,255,255,.09) inset,0 3px 16px rgba(6,35,22,.26);

  --sans:"Inter","Segoe UI",-apple-system,BlinkMacSystemFont,Roboto,"Helvetica Neue",Arial,sans-serif;
  --serif:"Iowan Old Style","Palatino Linotype",Palatino,Georgia,"Times New Roman",serif;
  --mono:"SF Mono",ui-monospace,"Cascadia Mono",Consolas,monospace;

  --hdr-h:58px;
  --side-w:236px;
  --ease:cubic-bezier(.22,.61,.36,1);
}

*{box-sizing:border-box;margin:0;padding:0}

/* ──────────────────────────────────────────────────────────────────
   2 · HOST PAGE CHROME (Frappe website navbar / footer)
   ────────────────────────────────────────────────────────────────── */
.navbar, header.navbar, .website-navbar, .navbar-expand, #navbar-collapse,
.web-footer, footer.web-footer, .footer, .page-footer, .navbar-brand,
.for-mobile-view .navbar{display:none !important}

body{padding-top:0 !important;background:#EDE7D9}
.main-section, .page_content, main.container{
  max-width:100% !important; width:100% !important;
  padding:0 !important; margin:0 !important;
}

/* ──────────────────────────────────────────────────────────────────
   3 · APP SHELL
   ────────────────────────────────────────────────────────────────── */
.cc-erp-root{
  font-family:var(--sans);
  font-size:13.8px;
  line-height:1.5;
  background:var(--cream);
  color:var(--ink);
  min-height:100vh;
  display:flex;
  flex-direction:column;
  border-radius:0;
  overflow-x:clip;
  -webkit-font-smoothing:antialiased;
  text-rendering:optimizeLegibility;
}
.cc-erp-root .num,.cc-erp-root .sv,.cc-erp-root .t-big,
.cc-erp-root .bbv,.cc-erp-root .bv{font-variant-numeric:tabular-nums}
.cc-erp-root :focus-visible{outline:2px solid var(--gold);outline-offset:2px;border-radius:4px}
@media (prefers-reduced-motion:reduce){
  .cc-erp-root *,.cc-erp-root *::before,.cc-erp-root *::after{
    animation-duration:.001ms !important;transition-duration:.001ms !important}
}

/* ──────────────────────────────────────────────────────────────────
   4 · MASTHEAD
   ────────────────────────────────────────────────────────────────── */
.hdr{
  background:linear-gradient(118deg,var(--green-dd) 0%,var(--green-d) 34%,var(--green) 72%,#0E6B44 100%);
  color:#EAF4EE;
  height:var(--hdr-h);
  display:flex;
  align-items:center;
  gap:12px;
  padding:0 16px 0 58px;   /* left room kept for the Portal fullscreen button */
  position:sticky; top:0; z-index:200;
  box-shadow:var(--sh-mast);
}
.hdr::after{
  content:"";position:absolute;left:0;right:0;bottom:0;height:2px;
  background:linear-gradient(90deg,transparent,var(--gold-l),transparent);opacity:.55;
}
.hdr-brand{display:flex;align-items:center;gap:10px;min-width:0;flex-shrink:0}
.hdr-brand .logo{
  width:34px;height:34px;border-radius:10px;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;
  font-family:var(--serif);font-size:15px;font-weight:700;color:#fff;
  background:linear-gradient(155deg,var(--green-x),var(--green));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.4),0 2px 6px rgba(0,0,0,.28);
}
.hdr-brand .bn{
  font-family:var(--serif);
  font-size:15px;font-weight:600;letter-spacing:.14em;color:#fff;
  line-height:1.15;white-space:nowrap;
}
.hdr-brand .bs{
  font-size:8.5px;letter-spacing:.3em;text-transform:uppercase;
  color:#9FCDB4;font-weight:600;margin-top:2px;
}
.hdr-center{flex:1;display:flex;align-items:center;justify-content:center;min-width:0}
.hdr-right{display:flex;align-items:center;gap:10px;flex-shrink:0}

/* global search */
.search-wrap{position:relative;width:min(420px,100%)}
.search-wrap input{
  width:100%;height:36px;padding:0 14px 0 40px;
  border:1px solid rgba(255,255,255,.2);border-radius:10px;
  background:rgba(255,255,255,.1);color:#fff;
  font-size:12.5px;font-weight:500;line-height:36px;outline:none;
  transition:background .16s var(--ease),border-color .16s var(--ease),box-shadow .16s var(--ease);
}
.search-wrap input::placeholder{color:rgba(217,236,226,.68);font-weight:400;opacity:1}
.search-wrap input:hover{background:rgba(255,255,255,.14)}
.search-wrap input:focus{
  border-color:var(--gold-l);background:rgba(255,255,255,.17);
  box-shadow:0 0 0 3px rgba(217,181,74,.18);
}
.search-wrap .si{
  position:absolute;left:13px;top:50%;transform:translateY(-50%);
  width:16px;display:flex;align-items:center;justify-content:center;
  font-size:13px;line-height:1;opacity:.75;pointer-events:none;z-index:2;
}
.search-results{
  position:absolute;top:calc(100% + 7px);left:0;right:0;
  background:var(--card);border:1px solid var(--line);border-radius:var(--r);
  box-shadow:var(--sh-3);z-index:300;max-height:340px;overflow-y:auto;display:none;
  padding:5px;
}
.search-results.show{display:block;animation:ccPop .16s var(--ease)}
.sr-item{
  padding:8px 11px;border-radius:var(--r-s);cursor:pointer;
  font-size:12.5px;color:var(--ink);border-bottom:0;transition:background .12s;
}
.sr-item + .sr-item{margin-top:1px}
.sr-item:hover{background:var(--mint)}
.sr-item .sr-cat{
  font-size:9px;color:var(--ink-3);display:block;margin-top:2px;
  letter-spacing:.1em;text-transform:uppercase;font-weight:700;
}

/* agent block */
.agent-info{text-align:right;line-height:1.25}
.agent-info .an{font-size:12.5px;font-weight:700;color:#fff}
.agent-info .ai{font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:#9FCDB4}
.agent-avatar{
  width:32px;height:32px;border-radius:50%;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;
  font-size:12px;font-weight:800;color:#fff;cursor:pointer;
  background:linear-gradient(150deg,var(--green-x),var(--green));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 2px 6px rgba(0,0,0,.3);
  transition:transform .16s var(--ease),box-shadow .16s var(--ease);
}
.agent-avatar:hover{transform:translateY(-1px);box-shadow:0 4px 12px rgba(0,0,0,.36)}
.hdr-clock{font-size:10.5px;color:#9FCDB4;text-align:right;line-height:1.4}
.hdr-btn{
  background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.17);
  color:#EAF4EE;padding:6px 12px;border-radius:var(--r-s);cursor:pointer;
  font-size:11.5px;font-weight:650;font-family:inherit;line-height:1;
  transition:background .14s var(--ease),transform .14s var(--ease);
}
.hdr-btn:hover{background:rgba(255,255,255,.2)}
.hdr-btn:active{transform:scale(.96)}
.hdr-burger{display:flex;align-items:center;justify-content:center}

/* attendance IN / OUT capsule */
.hdr-attend{
  display:flex;align-items:center;gap:6px;flex-shrink:0;
  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.14);
  border-radius:var(--r-pill);padding:4px 6px;
}
.att-io{
  display:inline-flex;align-items:center;gap:5px;
  padding:3px 9px;border-radius:var(--r-pill);
  font-size:8.5px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;
  line-height:1;white-space:nowrap;
}
.att-io b{font-size:11px;font-weight:800;letter-spacing:0}
.att-in{background:rgba(47,164,111,.2);color:#BFE8D2}
.att-in b{color:#fff}
.att-out{background:rgba(217,181,74,.18);color:#F0DCA4}
.att-out b{color:#fff}

/* ──────────────────────────────────────────────────────────────────
   5 · BODY + SIDEBAR
   ────────────────────────────────────────────────────────────────── */
.body-wrap{display:flex;flex:1;min-height:0;align-items:stretch}

.sidebar{
  width:var(--side-w);flex:0 0 var(--side-w);
  background:linear-gradient(180deg,#FBF9F3 0%,var(--cream-2) 100%);
  border-right:1px solid var(--line);
  display:flex;flex-direction:column;
  overflow-y:auto;overscroll-behavior:contain;
  padding:10px 10px 22px;
  position:sticky;top:var(--hdr-h);
  height:calc(100vh - var(--hdr-h));
  transition:width .22s var(--ease),flex-basis .22s var(--ease),padding .22s var(--ease);
  z-index:120;
}
.sidebar.collapsed{width:0;flex-basis:0;padding-left:0;padding-right:0;overflow:hidden;border-right-color:transparent}
.sidebar::-webkit-scrollbar{width:7px}
.sidebar::-webkit-scrollbar-thumb{background:var(--line-2);border-radius:7px}

.nav-section-label{
  font-size:9px;font-weight:800;color:var(--ink-4);
  text-transform:uppercase;letter-spacing:.2em;
  padding:16px 10px 6px;white-space:nowrap;
}
.nav-section-label:first-child{padding-top:6px}

.nav-item{
  display:flex;align-items:center;gap:10px;
  padding:8px 10px;margin-bottom:2px;
  color:var(--ink-2);cursor:pointer;
  font-size:12.8px;font-weight:600;line-height:1.3;
  border:1px solid transparent;border-radius:var(--r-s);
  text-decoration:none;white-space:nowrap;
  transition:background .14s var(--ease),color .14s var(--ease),
             border-color .14s var(--ease),transform .14s var(--ease);
}
.nav-item:hover{background:#fff;border-color:var(--line);color:var(--ink);box-shadow:var(--sh)}
.nav-item:active{transform:scale(.99)}
.nav-item.active{
  background:linear-gradient(120deg,var(--green-d),var(--green));
  border-color:var(--green-d);color:#fff;font-weight:700;
  box-shadow:0 3px 10px rgba(11,93,59,.28);
}
/* 3D icon chip */
.nav-item .ni{
  width:26px;height:26px;flex:0 0 26px;border-radius:8px;
  display:grid;place-items:center;font-size:12.5px;font-style:normal;line-height:1;
  color:#fff;background:linear-gradient(155deg,var(--green-x),var(--green));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.42),inset 0 -2px 4px rgba(0,0,0,.2),
             0 2px 5px rgba(6,35,22,.24);
  transition:transform .16s var(--ease);
}
.nav-item:hover .ni{transform:translateY(-1px) scale(1.04)}
.nav-item.active .ni{
  background:linear-gradient(155deg,var(--gold-l),var(--gold));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.5),0 2px 6px rgba(0,0,0,.3);
}
.nav-badge{
  background:var(--crit);color:#fff;border-radius:var(--r-pill);
  padding:1px 7px;font-size:9.5px;font-weight:800;margin-left:auto;
  line-height:16px;min-width:20px;text-align:center;
}
.nav-item.active .nav-badge{background:var(--gold-l);color:#3A2B03}

/* ──────────────────────────────────────────────────────────────────
   6 · MAIN CANVAS
   ────────────────────────────────────────────────────────────────── */
.main{
  flex:1;min-width:0;
  overflow-y:auto;
  padding:18px 20px 40px;
  background:
    radial-gradient(1200px 380px at 70% -120px,rgba(47,164,111,.07),transparent 70%),
    var(--cream);
}
.page-section{display:none}
.page-section.active{display:block;animation:ccFade .22s var(--ease)}

@keyframes ccFade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}
@keyframes ccPop{from{opacity:0;transform:translateY(-4px)}to{opacity:1;transform:none}}

/* breadcrumb */
.page-breadcrumb{
  font-size:10.5px;color:var(--ink-3);margin-bottom:14px;
  display:flex;align-items:center;gap:6px;flex-wrap:wrap;
  letter-spacing:.1em;text-transform:uppercase;font-weight:700;
}
.page-breadcrumb span{color:var(--ink-4)}
.page-breadcrumb .cur{color:var(--green);font-weight:800}

/* page toolbar (date range strip in the shell) */
.cc-toolbar{
  display:flex;gap:9px;align-items:center;flex-wrap:wrap;
  background:var(--card);border:1px solid var(--line);
  border-radius:var(--r);padding:10px 14px;margin-bottom:16px;
  box-shadow:var(--sh);
}
.cc-toolbar .tb-lb{
  display:inline-flex;align-items:center;gap:6px;
  font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;
  color:var(--ink-3);
}
.cc-toolbar .tb-sep{font-size:11px;color:var(--ink-4)}
.cc-toolbar .tb-hint{font-size:10px;color:var(--ink-4);margin-left:auto;text-align:right;line-height:1.4}
.cc-toolbar input[type=date]{width:152px;flex:0 0 auto;height:32px}
@media (max-width:760px){
  .cc-toolbar .tb-hint{margin-left:0;text-align:left;width:100%}
  .cc-toolbar input[type=date]{flex:1 1 130px;width:auto}
}

/* ──────────────────────────────────────────────────────────────────
   7 · CARDS · TILES · SECTIONS
   ────────────────────────────────────────────────────────────────── */
.card{
  background:var(--card);
  border:1px solid var(--line);
  border-radius:var(--r);
  margin-bottom:16px;
  overflow:hidden;
  box-shadow:var(--sh);
  transition:box-shadow .2s var(--ease);
}
.card:hover{box-shadow:var(--sh-2)}
.card-hdr{
  background:linear-gradient(120deg,var(--green-d) 0%,var(--green) 70%,#0E6B44 100%);
  color:#fff;padding:11px 16px;
  font-size:12.5px;font-weight:700;letter-spacing:.02em;
  display:flex;align-items:center;justify-content:space-between;
  flex-wrap:wrap;gap:9px;
  box-shadow:inset 0 -2px 0 rgba(217,181,74,.45);
}
.card-hdr .badge{
  background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.22);
  color:#fff;font-size:9.5px;font-weight:800;padding:2px 9px;
  border-radius:var(--r-pill);letter-spacing:.06em;
}
.card-body{padding:16px;background:var(--card)}
.card .card{box-shadow:none;border-color:var(--line-g)}

/* KPI tiles */
.stat-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit,minmax(168px,1fr));
  gap:13px;margin-bottom:18px;
}
.stat-card{
  position:relative;
  background:var(--card);
  border:1px solid var(--line);
  border-radius:var(--r);
  padding:14px 16px 15px;
  box-shadow:var(--sh);
  cursor:pointer;
  overflow:hidden;
  transition:transform .18s var(--ease),box-shadow .18s var(--ease),border-color .18s var(--ease);
}
.stat-card::before{
  content:"";position:absolute;left:0;top:0;bottom:0;width:4px;
  background:var(--green);border-radius:var(--r) 0 0 var(--r);
}
.stat-card:hover{transform:translateY(-3px);box-shadow:var(--sh-2);border-color:var(--line-gg)}
.stat-card:active{transform:translateY(-1px)}
.stat-card .sl{
  font-size:9.5px;color:var(--ink-3);text-transform:uppercase;
  letter-spacing:.16em;font-weight:800;margin-bottom:6px;line-height:1.3;
}
.stat-card .sv{
  font-size:27px;font-weight:800;line-height:1.05;letter-spacing:-.5px;color:var(--ink);
}
.stat-card .ss{font-size:10.5px;color:var(--ink-3);margin-top:4px;line-height:1.4}

.s-blue::before{background:linear-gradient(180deg,var(--info),#2E6FB5)}
.s-blue{background:linear-gradient(120deg,var(--info-bg) 0%,#fff 62%)}
.s-green::before{background:linear-gradient(180deg,var(--green),var(--green-x))}
.s-green{background:linear-gradient(120deg,var(--mint) 0%,#fff 62%)}
.s-gold::before{background:linear-gradient(180deg,var(--gold),var(--gold-l))}
.s-gold{background:linear-gradient(120deg,var(--gold-bg) 0%,#fff 62%)}
.s-red::before{background:linear-gradient(180deg,var(--crit),#C4554A)}
.s-red{background:linear-gradient(120deg,var(--crit-bg) 0%,#fff 62%)}
.s-teal::before{background:linear-gradient(180deg,var(--teal),var(--teal-l))}
.s-teal{background:linear-gradient(120deg,#E4F4F1 0%,#fff 62%)}

/* grouped drill-down tile */
.stat-card.grp-card{border-style:dashed;border-color:var(--line-gg);background:var(--mint)}
.stat-card.grp-card .sl{color:var(--green)}
.stat-card.grp-card::after{
  content:"▸";position:absolute;right:12px;top:12px;
  font-size:11px;color:var(--green-x);opacity:.75;
}

/* form sections */
.form-section{
  border:1px solid var(--line);border-radius:var(--r);
  padding:16px;margin-bottom:16px;background:var(--card);box-shadow:var(--sh);
}
.form-section-title{
  font-size:10.5px;font-weight:800;color:var(--green);
  text-transform:uppercase;letter-spacing:.16em;margin-bottom:14px;
  display:flex;align-items:center;gap:8px;
  border-bottom:1px solid var(--line);padding-bottom:9px;
}
.form-section-title::before{
  content:"";width:4px;height:14px;border-radius:2px;flex:0 0 4px;
  background:linear-gradient(180deg,var(--gold-l),var(--gold));
}
.form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}
.form-grid-2{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.form-grid-3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px}
@media(max-width:700px){.form-grid-2,.form-grid-3{grid-template-columns:1fr}}
.field{margin-bottom:11px}
label.lbl{
  font-size:9.5px;font-weight:800;color:var(--ink-2);display:block;
  margin-bottom:5px;text-transform:uppercase;letter-spacing:.14em;
}
.required-star{color:var(--crit)}
.agent-tip{
  font-size:10px;color:var(--ok);background:var(--ok-bg);
  border-left:3px solid var(--green-x);padding:5px 9px;
  border-radius:0 var(--r-xs) var(--r-xs) 0;margin-top:5px;line-height:1.45;
}

/* ──────────────────────────────────────────────────────────────────
   8 · FORM CONTROLS
   ────────────────────────────────────────────────────────────────── */
.cc-erp-root input[type=text],.cc-erp-root input[type=number],
.cc-erp-root input[type=date],.cc-erp-root input[type=time],
.cc-erp-root input[type=tel],.cc-erp-root input[type=email],
.cc-erp-root input[type=search],.cc-erp-root select,.cc-erp-root textarea{
  width:100%;padding:7px 11px;height:35px;
  border:1px solid var(--line-2);border-radius:var(--r-s);
  font-size:12.8px;font-family:inherit;color:var(--ink);background:#fff;
  transition:border-color .14s var(--ease),box-shadow .14s var(--ease),background .14s var(--ease);
}
.cc-erp-root select{
  cursor:pointer;appearance:none;-webkit-appearance:none;
  background-image:linear-gradient(45deg,transparent 50%,var(--ink-3) 50%),
                   linear-gradient(135deg,var(--ink-3) 50%,transparent 50%);
  background-position:calc(100% - 15px) 15px,calc(100% - 10px) 15px;
  background-size:5px 5px,5px 5px;background-repeat:no-repeat;
  padding-right:30px;
}
.cc-erp-root select[multiple]{background-image:none;padding-right:11px;height:auto}
.cc-erp-root textarea{height:auto;min-height:64px;resize:vertical;line-height:1.55}
.cc-erp-root input:hover:not(:disabled),.cc-erp-root select:hover:not(:disabled),
.cc-erp-root textarea:hover:not(:disabled){border-color:var(--line-gg)}
.cc-erp-root input:focus,.cc-erp-root select:focus,.cc-erp-root textarea:focus{
  border-color:var(--green-x);outline:none;
  box-shadow:0 0 0 3px rgba(47,164,111,.16);background:#fff;
}
.cc-erp-root input:disabled,.cc-erp-root select:disabled,.cc-erp-root textarea:disabled{
  background:var(--cream-2);color:var(--ink-3);border-color:var(--line);cursor:not-allowed;
}
.cc-erp-root input[type=checkbox],.cc-erp-root input[type=radio]{
  width:auto;height:auto;accent-color:var(--green);cursor:pointer;
}
.cc-erp-root input[type=file]{height:auto;padding:8px 11px}

/* ──────────────────────────────────────────────────────────────────
   9 · BUTTONS
   ────────────────────────────────────────────────────────────────── */
.btn{
  display:inline-flex;align-items:center;justify-content:center;gap:6px;
  padding:8px 15px;border-radius:var(--r-s);
  font-size:12px;font-weight:700;font-family:inherit;line-height:1.2;
  cursor:pointer;border:1px solid transparent;white-space:nowrap;
  transition:transform .13s var(--ease),box-shadow .13s var(--ease),
             background .13s var(--ease),border-color .13s var(--ease);
}
.btn:hover{transform:translateY(-1px)}
.btn:active{transform:translateY(0) scale(.985)}
.btn:disabled,.btn[disabled]{opacity:.5;cursor:not-allowed;transform:none}

.btn-n{background:linear-gradient(120deg,var(--green-d),var(--green));color:#fff;border-color:var(--green-d);box-shadow:0 2px 7px rgba(11,93,59,.26)}
.btn-n:hover{background:linear-gradient(120deg,var(--green),var(--green-l));box-shadow:0 5px 14px rgba(11,93,59,.3)}
.btn-g{background:linear-gradient(120deg,var(--green-l),var(--green-x));color:#fff;border-color:var(--green-l);box-shadow:0 2px 7px rgba(18,118,76,.24)}
.btn-g:hover{background:linear-gradient(120deg,var(--green-x),#37B87F);box-shadow:0 5px 14px rgba(18,118,76,.28)}
.btn-teal{background:linear-gradient(120deg,#0B6155,var(--teal-l));color:#fff;border-color:#0B6155;box-shadow:0 2px 7px rgba(14,124,107,.24)}
.btn-teal:hover{background:linear-gradient(120deg,var(--teal),#1FBCA4)}
.btn-r{background:linear-gradient(120deg,#8A2419,#B8453A);color:#fff;border-color:#8A2419;box-shadow:0 2px 7px rgba(158,44,34,.24)}
.btn-r:hover{background:linear-gradient(120deg,#9E2C22,#C4554A)}
.btn-gold{background:linear-gradient(120deg,var(--gold),var(--gold-l));color:#3A2B03;border-color:var(--gold);box-shadow:0 2px 7px rgba(184,144,31,.26)}
.btn-gold:hover{background:linear-gradient(120deg,var(--gold-l),#E8C868)}
.btn-gy{background:#fff;color:var(--ink-2);border-color:var(--line-2);box-shadow:var(--sh)}
.btn-gy:hover{background:var(--cream-2);border-color:var(--line-gg);color:var(--ink)}
.btn-primary{background:linear-gradient(120deg,var(--green-d),var(--green));color:#fff;border-color:var(--green-d)}
.btn-sm{padding:5px 11px;font-size:11px;border-radius:var(--r-xs)}
.btn-row{display:flex;gap:9px;flex-wrap:wrap;margin-top:13px}

/* ──────────────────────────────────────────────────────────────────
   10 · PILLS / STATUS CHIPS
   ────────────────────────────────────────────────────────────────── */
.pill{
  display:inline-flex;align-items:center;gap:4px;
  padding:2px 9px;border-radius:var(--r-pill);
  font-size:9.5px;font-weight:800;white-space:nowrap;
  text-transform:uppercase;letter-spacing:.1em;line-height:16px;
  border:1px solid transparent;
}
.p-green{background:var(--ok-bg);color:var(--ok);border-color:var(--ok-br)}
.p-blue,.p-teal{background:var(--info-bg);color:var(--info);border-color:var(--info-br)}
.p-red{background:var(--crit-bg);color:var(--crit);border-color:var(--crit-br)}
.p-gold,.p-or{background:var(--warn-bg);color:var(--warn);border-color:var(--warn-br)}
.p-gy{background:var(--cream-2);color:var(--ink-3);border-color:var(--line-2)}

/* ──────────────────────────────────────────────────────────────────
   11 · CHECK GRIDS
   ────────────────────────────────────────────────────────────────── */
.check-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(205px,1fr));gap:7px;margin-top:7px}
.check-item{
  display:flex;align-items:center;gap:8px;padding:8px 11px;
  border:1px solid var(--line);border-radius:var(--r-s);cursor:pointer;
  font-size:12.5px;background:#fff;user-select:none;
  transition:border-color .13s var(--ease),background .13s var(--ease),box-shadow .13s var(--ease);
}
.check-item:hover{border-color:var(--line-gg);background:var(--mint);box-shadow:var(--sh)}
.check-item.sel{border-color:var(--green);background:var(--mint);font-weight:700;color:var(--green)}
.check-item input[type=checkbox]{width:15px;height:15px;flex-shrink:0;accent-color:var(--green)}

/* ──────────────────────────────────────────────────────────────────
   12 · TABLES
   ────────────────────────────────────────────────────────────────── */
.tbl-wrap{
  overflow-x:auto;overflow-y:auto;max-height:500px;
  border:1px solid var(--line);border-radius:var(--r);background:#fff;
  -webkit-overflow-scrolling:touch;
}
.tbl-wrap::-webkit-scrollbar{width:9px;height:9px}
.tbl-wrap::-webkit-scrollbar-thumb{background:var(--line-2);border-radius:9px;border:2px solid #fff}
.tbl-wrap table{border:0;border-radius:0}
.cc-erp-root table{
  width:100%;border-collapse:separate;border-spacing:0;
  font-size:12px;white-space:nowrap;background:#fff;
  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;
}
.cc-erp-root th{
  background:linear-gradient(180deg,#F1F8F3,var(--mint));
  color:var(--green-d);font-weight:800;padding:10px 12px;
  border-bottom:1px solid var(--line-gg);
  position:sticky;top:0;z-index:2;text-align:left;
  font-size:9.5px;text-transform:uppercase;letter-spacing:.14em;
}
.cc-erp-root td{
  padding:9px 12px;border-top:1px solid var(--line-g);
  vertical-align:middle;font-size:12.3px;color:var(--ink-2);
}
.cc-erp-root tbody tr{transition:background .12s}
.cc-erp-root tbody tr:nth-child(even) td{background:#FCFDFC}
.cc-erp-root tr:hover td{background:var(--mint)}
.cc-erp-root tbody tr:first-child td{border-top:0}

/* ──────────────────────────────────────────────────────────────────
   13 · LEAD QUEUE CARDS
   ────────────────────────────────────────────────────────────────── */
.queue-item{
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding:11px 13px;border-radius:var(--r);border:1px solid var(--line);
  margin-bottom:8px;background:#fff;position:relative;overflow:hidden;
  transition:border-color .16s var(--ease),box-shadow .16s var(--ease),transform .16s var(--ease);
}
.queue-item::before{
  content:"";position:absolute;left:0;top:0;bottom:0;width:3px;
  background:var(--green-x);opacity:0;transition:opacity .16s;
}
.queue-item:hover{border-color:var(--line-gg);box-shadow:var(--sh-2);transform:translateX(2px)}
.queue-item:hover::before{opacity:1}
.qi-name{font-weight:750;font-size:13.2px;color:var(--green-d)}
.qi-sub{font-size:10.5px;color:var(--ink-3);margin-top:2px}
.qi-tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:6px}
.qi-right{display:flex;align-items:center;gap:8px;flex-shrink:0}
.qi-detail-row{display:flex;flex-wrap:wrap;gap:6px;margin-top:7px;font-size:11px;color:var(--ink-3)}
.qi-detail-row .qd{
  background:var(--mint);border:1px solid var(--mint-3);border-radius:var(--r-xs);
  padding:2px 8px;color:var(--ok);font-size:10.5px;font-weight:700;
}
.qi-progress-mini{height:4px;background:var(--mint-2);border-radius:var(--r-pill);margin-top:7px;overflow:hidden}
.qi-progress-fill{height:100%;border-radius:var(--r-pill);background:linear-gradient(90deg,var(--green-x),var(--green));transition:width .4s var(--ease)}

/* ──────────────────────────────────────────────────────────────────
   14 · ACCORDION / FAQ / SCRIPTS
   ────────────────────────────────────────────────────────────────── */
.acc-item{border:1px solid var(--line);border-radius:var(--r-s);margin-bottom:7px;overflow:hidden;background:#fff}
.acc-hdr{
  padding:11px 14px;font-size:12.5px;font-weight:700;cursor:pointer;
  display:flex;justify-content:space-between;align-items:center;gap:10px;
  background:var(--cream-2);color:var(--green-d);transition:background .13s;
}
.acc-hdr:hover{background:var(--mint)}
.acc-hdr.open{background:var(--mint);box-shadow:inset 0 -1px 0 var(--mint-3)}
.acc-hdr .acc-icon{font-size:12px;transition:transform .22s var(--ease);flex-shrink:0;color:var(--green-x)}
.acc-hdr.open .acc-icon{transform:rotate(180deg)}
.acc-body{display:none;padding:14px;font-size:12.5px;line-height:1.75;color:var(--ink-2);background:#fff}
.acc-body.open{display:block}

.script-card{
  background:var(--card);border:1px solid var(--line);
  border-radius:var(--r);padding:14px;margin-bottom:11px;box-shadow:var(--sh);
}
.script-card .sc-title{
  font-size:10px;font-weight:800;color:var(--green);text-transform:uppercase;
  letter-spacing:.18em;margin-bottom:9px;
}
.script-card .sc-text{
  font-size:12.8px;line-height:1.8;color:var(--ink);
  border-left:3px solid var(--gold-l);background:var(--cream);
  padding:11px 14px;border-radius:0 var(--r-s) var(--r-s) 0;font-style:normal;
}
.copy-btn{
  background:#fff;color:var(--green);border:1px solid var(--line-2);
  padding:4px 11px;border-radius:var(--r-xs);font-size:10.5px;font-weight:700;
  cursor:pointer;margin-top:8px;font-family:inherit;transition:all .13s var(--ease);
}
.copy-btn:hover{background:var(--mint);border-color:var(--line-gg)}

/* ──────────────────────────────────────────────────────────────────
   15 · LEAD STATUS BLOCKS · BMI · WHATSAPP
   ────────────────────────────────────────────────────────────────── */
.lead-status-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(225px,1fr));gap:9px}
.status-opt{
  border:1.5px solid var(--line);border-radius:var(--r-s);
  padding:11px 13px;cursor:pointer;background:#fff;
  transition:border-color .14s var(--ease),background .14s var(--ease),
             box-shadow .14s var(--ease),transform .14s var(--ease);
}
.status-opt:hover{border-color:var(--line-gg);box-shadow:var(--sh);transform:translateY(-1px)}
.status-opt.sel-success{border-color:var(--green);background:var(--ok-bg)}
.status-opt.sel-followup{border-color:var(--gold);background:var(--gold-bg)}
.status-opt.sel-lost{border-color:var(--crit);background:var(--crit-bg)}
.status-opt.sel-invalid{border-color:var(--line-2);background:var(--cream-2)}
.status-opt.sel-untouched{border-color:var(--info);background:var(--info-bg)}
.status-opt .s-hdr{font-size:11.5px;font-weight:800;margin-bottom:3px;color:var(--ink)}
.status-opt .s-sub{font-size:10.5px;color:var(--ink-3)}
.status-opt .s-tip{
  font-size:9.5px;color:var(--ok);margin-top:6px;
  border-top:1px dashed var(--line-2);padding-top:5px;line-height:1.5;
}

.bmi-display,.bmi-panel{
  background:linear-gradient(125deg,var(--green-dd) 0%,var(--green) 62%,#0E6B44 100%);
  color:#fff;border-radius:var(--r);padding:16px 18px;
  display:grid;gap:14px;margin-top:12px;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.12),0 6px 18px rgba(6,35,22,.2);
}
.bmi-display{grid-template-columns:repeat(3,1fr)}
.bmi-panel{grid-template-columns:repeat(4,1fr)}
@media(max-width:650px){.bmi-panel,.bmi-display{grid-template-columns:repeat(2,1fr)}}
.bmi-block .bl,.bmi-block .bbl{
  font-size:9px;color:#9FCDB4;text-transform:uppercase;letter-spacing:.18em;
  margin-bottom:3px;font-weight:700;
}
.bmi-block .bv,.bmi-block .bbv{font-size:23px;font-weight:800;line-height:1.1;letter-spacing:-.4px}
.bmi-block .bs,.bmi-block .bbs{font-size:10.5px;margin-top:3px;color:#D5EADF}

.followup-reminder{
  background:var(--gold-bg);border:1px solid var(--gold-br);
  border-left:4px solid var(--gold);border-radius:var(--r-s);padding:14px;margin-top:14px;
}
.whatsapp-preview{
  background:#F2FBF4;border:1px solid #BFE6C9;border-radius:var(--r);
  padding:14px;font-size:12.3px;line-height:1.75;white-space:pre-line;
  margin-top:10px;position:relative;color:var(--ink-2);
}
.whatsapp-preview .wa-hdr{
  background:linear-gradient(120deg,#128C4B,#25D366);color:#fff;
  font-size:9.5px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;
  padding:6px 14px;border-radius:var(--r) var(--r) 0 0;margin:-14px -14px 12px;
}
.gender-dependent{display:none}
.gender-f .gender-dependent.female-only{display:block}
.gender-m .gender-dependent.male-only{display:block}
.treatment-dep{display:none}
.treatment-dep.show{display:block}

.timer-badge{
  background:linear-gradient(120deg,var(--green-d),var(--green));color:#fff;
  border-radius:var(--r-pill);padding:5px 13px;font-size:11px;font-weight:800;
  letter-spacing:.06em;display:inline-flex;align-items:center;gap:5px;
  box-shadow:0 2px 7px rgba(11,93,59,.24);
}
.conversion-bar{height:6px;background:var(--mint-2);border-radius:var(--r-pill);margin-top:5px;overflow:hidden}
.conversion-fill{height:100%;background:linear-gradient(90deg,var(--green-x),var(--green));border-radius:var(--r-pill);transition:width .45s var(--ease)}

/* ──────────────────────────────────────────────────────────────────
   16 · UPLOAD ZONE
   ────────────────────────────────────────────────────────────────── */
.upload-zone{
  border:2px dashed var(--line-2);border-radius:var(--r);
  padding:32px 22px;text-align:center;color:var(--ink-3);cursor:pointer;
  background:var(--cream);transition:all .18s var(--ease);
}
.upload-zone:hover{border-color:var(--green-x);background:var(--mint);color:var(--green)}
.upload-zone .uz-ic{font-size:34px;margin-bottom:9px;opacity:.85}
.upload-zone .uz-txt{font-size:13.5px;font-weight:750;color:var(--ink)}
.upload-zone .uz-sub{font-size:11px;margin-top:5px;color:var(--ink-3)}
.upload-zone.uploaded{border-color:var(--green);background:var(--mint);border-style:solid}

/* ──────────────────────────────────────────────────────────────────
   17 · TOAST · MODAL
   ────────────────────────────────────────────────────────────────── */
.toast-wrap{position:fixed;bottom:22px;right:22px;z-index:9999;display:flex;flex-direction:column;gap:9px;max-width:min(380px,calc(100vw - 32px))}
.toast{
  background:linear-gradient(120deg,var(--green-dd),var(--green-d));color:#fff;
  padding:11px 17px;border-radius:var(--r-s);
  font-size:12.5px;font-weight:600;display:flex;align-items:center;gap:9px;
  box-shadow:var(--sh-3);border:1px solid rgba(255,255,255,.1);
  animation:toastIn .28s var(--ease);
}
.toast.toast-green{background:linear-gradient(120deg,#0B5D3B,#17794E)}
.toast.toast-red{background:linear-gradient(120deg,#7F1F16,#9E2C22)}
.toast.toast-gold{background:linear-gradient(120deg,#8A6A0C,var(--gold));color:#fff}
.toast.toast-teal{background:linear-gradient(120deg,#0B6155,var(--teal))}
@keyframes toastIn{from{transform:translateX(60px) scale(.96);opacity:0}to{transform:none;opacity:1}}
@media (prefers-reduced-motion:reduce){.toast{animation:none}}
.cc-toast-x{opacity:.7;cursor:pointer;transition:opacity .13s}
.cc-toast-x:hover{opacity:1}

.modal-overlay{
  display:none;position:fixed;inset:0;
  background:rgba(6,35,22,.52);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);
  z-index:500;align-items:center;justify-content:center;padding:22px;
}
.modal-overlay.show{display:flex;animation:ccFade .18s var(--ease)}
.modal-box{
  background:var(--cream);border:1px solid var(--line);border-radius:var(--r);
  padding:24px 26px 22px;max-width:580px;width:100%;max-height:88vh;overflow-y:auto;
  box-shadow:var(--sh-3);animation:ccModalIn .22s var(--ease);
}
@keyframes ccModalIn{from{transform:translateY(14px) scale(.985);opacity:0}to{transform:none;opacity:1}}
.modal-box.wide{max-width:960px}
.modal-title{
  font-size:16px;font-weight:800;color:var(--green-d);margin-bottom:15px;
  padding-bottom:11px;border-bottom:1px solid var(--line);
  display:flex;align-items:center;gap:9px;
}
.modal-title::before{
  content:"";width:4px;height:17px;border-radius:2px;flex:0 0 4px;
  background:linear-gradient(180deg,var(--gold-l),var(--gold));
}

/* ──────────────────────────────────────────────────────────────────
   18 · TABS
   ────────────────────────────────────────────────────────────────── */
.tab-nav{
  display:flex;gap:4px;margin-bottom:16px;overflow-x:auto;
  background:var(--cream-2);border:1px solid var(--line);
  border-radius:var(--r-s);padding:4px;
}
.tab-nav::-webkit-scrollbar{height:0}
.tab-btn{
  padding:8px 15px;font-size:12px;font-weight:700;cursor:pointer;
  color:var(--ink-3);background:transparent;border:0;border-radius:var(--r-xs);
  white-space:nowrap;font-family:inherit;
  transition:background .14s var(--ease),color .14s var(--ease),box-shadow .14s var(--ease);
}
.tab-btn:hover{color:var(--ink);background:rgba(255,255,255,.7)}
.tab-btn.on{
  color:var(--green-d);background:#fff;box-shadow:var(--sh);
  border-bottom:0;
}
.tab-pane{display:none}
.tab-pane.on{display:block;animation:ccFade .2s var(--ease)}

/* ──────────────────────────────────────────────────────────────────
   19 · FOLLOW-UP FORM (ff-*)
   ────────────────────────────────────────────────────────────────── */
.ff-form{font-size:13.8px}
.ff-progress-wrap{
  position:sticky;top:0;z-index:150;background:rgba(255,255,255,.96);
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
  border:1px solid var(--line);border-radius:var(--r);
  padding:12px 16px 10px;margin-bottom:14px;box-shadow:var(--sh-2);
}
.ff-prog-steps{display:flex;align-items:flex-start;gap:0;margin-bottom:10px;overflow-x:auto;padding-bottom:2px}
.ff-prog-steps::-webkit-scrollbar{height:0}
.ff-prog-step{display:flex;flex-direction:column;align-items:center;flex:1;min-width:72px;position:relative}
.ff-prog-step:not(:last-child)::after{
  content:'';position:absolute;top:12px;left:calc(50% + 14px);right:calc(-50% + 14px);
  height:2px;background:var(--line-2);z-index:0;transition:background .35s var(--ease);
}
.ff-prog-step.done:not(:last-child)::after{background:var(--green-x)}
.ff-prog-dot{
  width:26px;height:26px;border-radius:50%;border:2px solid var(--line-2);
  background:#fff;z-index:1;display:flex;align-items:center;justify-content:center;
  font-size:11px;font-weight:800;color:var(--ink-3);
  transition:all .3s var(--ease);cursor:default;
}
.ff-prog-step.done .ff-prog-dot{background:var(--green-x);border-color:var(--green-x);color:#fff}
.ff-prog-step.active .ff-prog-dot{
  background:var(--green);border-color:var(--green);color:#fff;
  box-shadow:0 0 0 4px rgba(11,93,59,.14);
}
.ff-prog-step.warn .ff-prog-dot{background:var(--warn);border-color:var(--warn);color:#fff}
.ff-prog-label{
  font-size:9px;color:var(--ink-3);margin-top:6px;text-align:center;
  font-weight:700;white-space:nowrap;letter-spacing:.06em;text-transform:uppercase;
}
.ff-prog-step.done .ff-prog-label{color:var(--ok)}
.ff-prog-step.active .ff-prog-label{color:var(--green-d);font-weight:800}
.ff-prog-bar-wrap{background:var(--mint-2);border-radius:var(--r-pill);height:5px;overflow:hidden}
.ff-prog-bar{height:5px;border-radius:var(--r-pill);background:linear-gradient(90deg,var(--green-x),var(--green));transition:width .45s var(--ease)}
.ff-prog-pct{font-size:10px;font-weight:800;color:var(--green-d);margin-top:4px;text-align:right;letter-spacing:.04em}
@media (prefers-reduced-motion:reduce){.ff-prog-bar,.ff-prog-step::after{transition:none}}

.ff-sec{
  border:1px solid var(--line);border-radius:var(--r);
  margin-bottom:14px;overflow:hidden;background:#fff;box-shadow:var(--sh);
}
.ff-sec:nth-child(even){background:#fff}
.ff-sec:nth-child(odd){background:#fff}
.ff-sec-hdr{
  background:linear-gradient(120deg,var(--green-d),var(--green) 72%,#0E6B44);
  color:#fff;padding:11px 16px;font-size:12px;font-weight:800;
  display:flex;align-items:center;gap:9px;letter-spacing:.03em;
  box-shadow:inset 0 -2px 0 rgba(217,181,74,.45);
}
.ff-sec-hdr .sec-num{
  background:linear-gradient(155deg,var(--gold-l),var(--gold));color:#3A2B03;
  width:22px;height:22px;border-radius:7px;display:flex;align-items:center;
  justify-content:center;font-size:10.5px;font-weight:900;flex-shrink:0;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.5);
}
.ff-sec-hdr .sec-done{
  background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.24);
  margin-left:auto;font-size:9px;padding:2px 9px;border-radius:var(--r-pill);
  letter-spacing:.1em;text-transform:uppercase;
}
.ff-sec-body{padding:16px;background:#fff}

.ff-row{display:grid;gap:12px;margin-bottom:12px}
.ff-row-2{grid-template-columns:1fr 1fr}
.ff-row-3{grid-template-columns:repeat(3,1fr)}
.ff-row-4{grid-template-columns:repeat(4,1fr)}
@media(max-width:800px){.ff-row-3,.ff-row-4{grid-template-columns:1fr 1fr}}
@media(max-width:550px){.ff-row-2,.ff-row-3,.ff-row-4{grid-template-columns:1fr}}

.ff-field{display:flex;flex-direction:column;gap:4px;min-width:0}
.ff-label{
  font-size:9.5px;font-weight:800;color:var(--ink-2);
  text-transform:uppercase;letter-spacing:.14em;
}
.ff-label .req{color:var(--crit)}
.ff-input,.ff-select,.ff-textarea{
  width:100%;padding:8px 11px;border:1px solid var(--line-2);border-radius:var(--r-s);
  font-size:13.2px;font-family:inherit;color:var(--ink);background:#fff;
  transition:border-color .14s var(--ease),box-shadow .14s var(--ease);
}
.ff-input,.ff-select{height:36px}
.ff-select{cursor:pointer}
.ff-textarea{min-height:60px;resize:vertical;line-height:1.6}
.ff-input:hover,.ff-select:hover,.ff-textarea:hover{border-color:var(--line-gg)}
.ff-input:focus,.ff-select:focus,.ff-textarea:focus{
  border-color:var(--green-x);outline:none;box-shadow:0 0 0 3px rgba(47,164,111,.16);
}
.ff-input:disabled{background:var(--cream-2);color:var(--ink-3);border-color:var(--line)}
.ff-input.input-err{border-color:var(--crit);background:var(--crit-bg)}
.ff-tip{
  font-size:10px;color:var(--ok);background:var(--ok-bg);
  border-left:3px solid var(--green-x);padding:5px 9px;
  border-radius:0 var(--r-xs) var(--r-xs) 0;line-height:1.5;
}
.ff-err-msg{font-size:10px;color:var(--crit);font-weight:700}
.ff-locked-badge{
  display:inline-block;background:var(--mint);color:var(--ok);border:1px solid var(--mint-3);
  font-size:9px;font-weight:800;padding:1px 7px;border-radius:var(--r-pill);
  margin-left:6px;vertical-align:middle;letter-spacing:.08em;
}

/* medical alert */
.med-alert{display:none;background:var(--warn-bg);border:1px solid var(--warn-br);border-left:4px solid var(--warn);border-radius:var(--r-s);padding:13px 16px;margin-top:11px}
.med-alert.show{display:flex;gap:11px;align-items:flex-start}
.med-alert .ma-icon{font-size:20px;flex-shrink:0;line-height:1.2}
.med-alert .ma-hdr{font-size:12px;font-weight:800;color:var(--warn);margin-bottom:4px}
.med-alert .ma-body{font-size:11.5px;color:var(--ink-2);line-height:1.65}

/* check grid v2 */
.check-grid-v2{display:grid;grid-template-columns:repeat(auto-fill,minmax(215px,1fr));gap:7px;margin-top:9px}
.ci-v2{
  display:flex;align-items:center;gap:9px;padding:8px 12px;
  border:1px solid var(--line);border-radius:var(--r-s);cursor:pointer;
  font-size:12.8px;background:#fff;user-select:none;
  transition:border-color .13s var(--ease),background .13s var(--ease),box-shadow .13s var(--ease);
}
.ci-v2:hover{border-color:var(--line-gg);background:var(--mint);box-shadow:var(--sh)}
.ci-v2.sel{border-color:var(--green);background:var(--mint);font-weight:700;color:var(--green)}
.ci-v2.alert-item.sel{border-color:var(--warn);background:var(--warn-bg);color:var(--warn)}
.ci-v2 input[type=checkbox]{width:15px;height:15px;flex-shrink:0;accent-color:var(--green)}

/* action tiles */
.action-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:14px}
@media(max-width:600px){.action-tiles{grid-template-columns:1fr}}
.act-tile{
  border:1.5px solid var(--line);border-radius:var(--r);padding:16px;
  cursor:pointer;text-align:center;background:#fff;
  transition:transform .18s var(--ease),box-shadow .18s var(--ease),border-color .18s var(--ease);
}
.act-tile:hover{transform:translateY(-3px);box-shadow:var(--sh-2);border-color:var(--line-gg)}
.act-tile.sel-fu{border-color:var(--gold);background:linear-gradient(140deg,var(--gold-bg),#fff)}
.act-tile.sel-book{border-color:var(--green);background:linear-gradient(140deg,var(--mint),#fff)}
.act-tile.sel-stop{border-color:var(--crit);background:linear-gradient(140deg,var(--crit-bg),#fff)}
.act-tile .at-icon{font-size:26px;margin-bottom:7px;line-height:1}
.act-tile .at-label{font-size:13px;font-weight:800;color:var(--green-d)}
.act-tile .at-sub{font-size:10.5px;color:var(--ink-3);margin-top:4px}
.act-content{background:var(--cream);border:1px solid var(--line);border-radius:var(--r-s);padding:15px}

/* status grid v2 */
.status-grid-v2{display:grid;grid-template-columns:repeat(6,1fr);gap:9px;margin-bottom:10px}
@media(max-width:900px){.status-grid-v2{grid-template-columns:repeat(3,1fr)}}
@media(max-width:550px){.status-grid-v2{grid-template-columns:repeat(2,1fr)}}
.sg-group{margin-bottom:14px}
.sg-group-label{
  font-size:10px;font-weight:800;color:#fff;background:linear-gradient(120deg,var(--green-d),var(--green));
  padding:5px 13px;border-radius:var(--r-pill);margin-bottom:9px;display:inline-block;
  letter-spacing:.14em;text-transform:uppercase;box-shadow:var(--sh);
}
.sg-group-label.sg-connected{background:linear-gradient(120deg,var(--green-d),var(--green-l))}
.sg-group-label.sg-notconnected{background:linear-gradient(120deg,#7F1F16,var(--crit))}
.sg-opt{
  border:1.5px solid var(--line);border-radius:var(--r-s);padding:9px 11px;
  cursor:pointer;background:#fff;text-align:center;
  transition:border-color .14s var(--ease),background .14s var(--ease),
             box-shadow .14s var(--ease),transform .14s var(--ease);
}
.sg-opt:hover{border-color:var(--line-gg);background:var(--mint);transform:translateY(-1px);box-shadow:var(--sh)}
.sg-opt .sg-sub{font-size:11.5px;font-weight:700;color:var(--ink-2);line-height:1.35}
.sg-opt .sg-tip{font-size:9.5px;color:var(--ink-3);margin-top:4px;line-height:1.45;display:none}
.sg-opt.expanded .sg-tip{display:block}
.sg-opt.sel-s,.sg-opt.sel-connected{border-color:var(--green);background:var(--ok-bg);box-shadow:0 0 0 3px rgba(47,164,111,.12)}
.sg-opt.sel-s .sg-sub,.sg-opt.sel-connected .sg-sub{color:var(--ok);font-weight:800}
.sg-opt.sel-f{border-color:var(--gold);background:var(--gold-bg);box-shadow:0 0 0 3px rgba(184,144,31,.12)}
.sg-opt.sel-f .sg-sub{color:var(--warn);font-weight:800}
.sg-opt.sel-l,.sg-opt.sel-notconnected{border-color:var(--crit);background:var(--crit-bg);box-shadow:0 0 0 3px rgba(158,44,34,.1)}
.sg-opt.sel-l .sg-sub,.sg-opt.sel-notconnected .sg-sub{color:var(--crit);font-weight:800}
.sg-opt.sel-i{border-color:var(--line-2);background:var(--cream-2)}
.sg-opt.sel-i .sg-sub{color:var(--ink-3);font-weight:800}
.sg-opt.sel-u{border-color:var(--info);background:var(--info-bg)}
.sg-opt.sel-u .sg-sub{color:var(--info);font-weight:800}

/* communication cards */
.comm-tool-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin-top:11px}
@media(max-width:550px){.comm-tool-grid{grid-template-columns:1fr}}
.comm-card{border:1px solid var(--line);border-radius:var(--r-s);padding:13px 15px;background:#fff;box-shadow:var(--sh)}
.comm-card .cc-hdr{font-size:10.5px;font-weight:800;color:var(--green);margin-bottom:9px;display:flex;align-items:center;gap:7px;letter-spacing:.12em;text-transform:uppercase}
.comm-card .cc-msg{
  font-size:11.8px;color:var(--ink-2);background:var(--cream);border:1px solid var(--line);
  padding:9px 11px;border-radius:var(--r-xs);line-height:1.65;white-space:pre-line;
  max-height:130px;overflow-y:auto;
}
.comm-card .cc-btns{display:flex;gap:7px;flex-wrap:wrap;margin-top:9px}

/* sticky bottom bar */
.ff-bottom-bar{
  position:sticky;bottom:0;z-index:100;
  background:linear-gradient(to top,var(--cream) 62%,rgba(250,247,239,0));
  padding:16px 4px 12px;display:flex;gap:10px;flex-wrap:wrap;justify-content:flex-end;
  border-top:1px solid var(--line);margin-top:18px;
}

/* booking confirm */
.booking-confirm-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px;font-size:13px}
@media(max-width:520px){.booking-confirm-grid{grid-template-columns:1fr}}
.bc-pair{background:#fff;border:1px solid var(--line);border-radius:var(--r-s);padding:9px 13px}
.bc-pair .bcp-l{font-size:9px;color:var(--ink-3);font-weight:800;text-transform:uppercase;letter-spacing:.14em}
.bc-pair .bcp-v{font-size:13.2px;font-weight:750;color:var(--green-d);margin-top:3px}
.send-toggle{
  display:flex;align-items:center;gap:9px;padding:9px 13px;
  border:1px solid var(--line);border-radius:var(--r-s);cursor:pointer;
  font-size:12.8px;margin-bottom:7px;background:#fff;transition:all .13s var(--ease);
}
.send-toggle:hover{border-color:var(--line-gg)}
.send-toggle input[type=checkbox]{width:16px;height:16px;accent-color:var(--green)}
.send-toggle.checked{border-color:var(--green);background:var(--mint);font-weight:650}

/* ──────────────────────────────────────────────────────────────────
   20 · MISC INJECTED ELEMENTS
   ────────────────────────────────────────────────────────────────── */
.notice-blue{
  background:var(--mint);border:1px solid var(--mint-3);border-left:4px solid var(--green);
  border-radius:var(--r-s);padding:11px 15px;font-size:12px;color:var(--ok);line-height:1.6;
}
.ws-masked{background:var(--cream-2);color:var(--ink-3)}
.cc-mask{color:var(--ink-3);letter-spacing:.04em}

.cc-back-bar{background:transparent;margin-bottom:12px}
.cc-back-btn{
  background:#fff !important;color:var(--green) !important;
  border:1px solid var(--line-2) !important;border-radius:var(--r-s) !important;
  font-weight:700;box-shadow:var(--sh);
}
.cc-back-btn:hover{background:var(--mint) !important;border-color:var(--line-gg) !important}

#cc-quick-range{display:flex;gap:7px;flex-wrap:wrap;align-items:center}
.cc-qr-btn{
  background:#fff !important;border:1px solid var(--line-2) !important;
  color:var(--ink-2) !important;border-radius:var(--r-pill) !important;
  font-size:11px !important;font-weight:700 !important;padding:5px 13px !important;
  cursor:pointer;transition:all .14s var(--ease);
}
.cc-qr-btn:hover{border-color:var(--green-x) !important;color:var(--green) !important;background:var(--mint) !important}
.cc-qr-btn.on{
  background:linear-gradient(120deg,var(--green-d),var(--green)) !important;
  color:#fff !important;border-color:var(--green-d) !important;
  box-shadow:0 2px 7px rgba(11,93,59,.24);
}
#cc-date-mode{min-width:140px}

.cc-spin{
  border-color:var(--mint-2) !important;border-top-color:var(--green-x) !important;
  border-radius:50%;
}

.med-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:7px}
.med-box{
  border:1px solid var(--line) !important;border-radius:var(--r-s) !important;
  background:#fff !important;box-shadow:var(--sh);
}
.med-chip,.sub-chip{
  background:var(--mint) !important;color:var(--ok) !important;
  border:1px solid var(--mint-3) !important;border-radius:var(--r-pill) !important;
  font-weight:700;cursor:pointer;transition:all .13s var(--ease);
}
.med-chip:hover,.sub-chip:hover{border-color:var(--green-x) !important}
.med-chip.sel,.sub-chip.sel{
  background:linear-gradient(120deg,var(--green-d),var(--green)) !important;
  color:#fff !important;border-color:var(--green-d) !important;
}
.ff-subcat-cb{accent-color:var(--green)}

.cc-appt-reason{
  font-size:10.5px;color:var(--crit);font-weight:650;margin-top:5px;
  background:var(--crit-bg);border:1px solid var(--crit-br);border-left:3px solid var(--crit);
  padding:4px 9px;border-radius:0 var(--r-xs) var(--r-xs) 0;max-width:200px;
  white-space:normal;line-height:1.45;
}

/* ──────────────────────────────────────────────────────────────────
   21 · LEAD ASSIGNMENT CONFIG (la-*)
   ────────────────────────────────────────────────────────────────── */
.la-config-area{display:block}
.la-card{
  background:var(--card);border:1px solid var(--line);border-radius:var(--r);
  box-shadow:var(--sh);overflow:hidden;margin-bottom:16px;
}
.la-card-header{
  background:linear-gradient(120deg,var(--green-d),var(--green) 72%,#0E6B44);
  color:#fff;padding:13px 17px;display:flex;align-items:center;
  justify-content:space-between;gap:11px;flex-wrap:wrap;
  box-shadow:inset 0 -2px 0 rgba(217,181,74,.45);
}
.la-title{font-size:14px;font-weight:800;letter-spacing:.02em;color:#fff}
.la-subtitle{font-size:10.5px;color:#9FCDB4;margin-top:3px;letter-spacing:.06em}
.la-summary-grid{
  display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));
  gap:11px;padding:15px 17px;background:var(--cream);border-bottom:1px solid var(--line);
}
.la-summary{
  background:#fff;border:1px solid var(--line);border-radius:var(--r-s);
  padding:11px 13px;box-shadow:var(--sh);position:relative;overflow:hidden;
}
.la-summary::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--green)}
.la-summary span{
  display:block;font-size:9px;color:var(--ink-3);text-transform:uppercase;
  letter-spacing:.16em;font-weight:800;margin-bottom:4px;
}
.la-summary strong{display:block;font-size:21px;font-weight:800;color:var(--ink);line-height:1.1;font-variant-numeric:tabular-nums}
.la-blue::before{background:var(--info)}   .la-blue strong{color:var(--info)}
.la-green::before{background:var(--green)} .la-green strong{color:var(--ok)}
.la-gold::before{background:var(--gold)}   .la-gold strong{color:var(--warn)}
.la-red::before{background:var(--crit)}    .la-red strong{color:var(--crit)}

.la-rule-strip{
  background:var(--gold-bg);border-bottom:1px solid var(--gold-br);
  padding:9px 17px;font-size:11px;color:var(--warn);font-weight:650;line-height:1.55;
}
.la-help{padding:10px 17px;font-size:10.5px;color:var(--ink-3);line-height:1.6;background:var(--cream)}
.la-table-wrap{padding:15px 17px;overflow-x:auto}
.la-table{width:100%;border-collapse:separate;border-spacing:0;border:0;background:transparent}
.la-table th{
  background:var(--mint);color:var(--green-d);font-size:9.5px;font-weight:800;
  text-transform:uppercase;letter-spacing:.14em;padding:11px 10px;text-align:left;
}
.la-table td{padding:10px;border-top:1px solid var(--line-g);font-size:12px;vertical-align:top}
.la-agent-name{font-size:14px;font-weight:800;color:var(--green-d);line-height:1.3}
.la-agent-id{margin-top:4px;color:var(--ink-3);font-size:10px;letter-spacing:.06em}
.la-status{
  display:inline-flex;align-items:center;gap:5px;padding:2px 9px;
  border-radius:var(--r-pill);font-size:9px;font-weight:800;
  letter-spacing:.12em;text-transform:uppercase;border:1px solid transparent;
}
.la-online{background:var(--ok-bg);color:var(--ok);border-color:var(--ok-br)}
.la-offline{background:var(--cream-2);color:var(--ink-3);border-color:var(--line-2)}
.la-field-note{font-size:9px;color:var(--ink-4);line-height:1.4;margin-top:4px}
.la-danger-text{color:var(--crit);font-weight:700}
.la-limit-hit{background:var(--crit-bg);color:var(--crit);border-radius:var(--r-xs);padding:1px 6px;font-weight:800;font-size:9.5px}
.la-limit-line{display:flex;align-items:center;gap:8px;font-size:10.5px;color:var(--ink-3)}
.la-limit-line strong{color:var(--green-d);font-size:19px;font-weight:800;font-variant-numeric:tabular-nums}
.la-performance-line{display:flex;flex-wrap:wrap;gap:5px 11px;font-size:10.5px;color:var(--ink-3)}
.la-performance-line strong{color:var(--ink);font-weight:800}
.la-check-label,.la-weight-wrap{display:flex;align-items:center;gap:6px;margin-top:8px;font-size:9.5px;color:var(--ink-3)}
.la-number,.la-weight{
  border:1px solid var(--line-2);border-radius:var(--r-xs);background:#fff;
  text-align:center;font-weight:700;font-variant-numeric:tabular-nums;
}
.la-recovered-row{box-shadow:inset 3px 0 0 var(--gold) !important}
.la-loading,.la-error{padding:26px;text-align:center;font-size:12.5px;color:var(--ink-3)}
.la-error{color:var(--crit);background:var(--crit-bg);border:1px solid var(--crit-br);border-radius:var(--r-s)}
.la-readonly{color:var(--ink-3);font-style:italic;font-size:11px}
.la-no-source{color:var(--crit);font-size:10px;font-weight:700}
.la-team-leader,.la-stop-reason,.la-source-select{
  border:1px solid var(--line-2);border-radius:var(--r-s);background:#fff;font-size:11.5px;
}

/* toggle switch */
.la-switch{position:relative;display:inline-block;width:46px;height:25px;flex-shrink:0}
.la-switch input{opacity:0;width:0;height:0;position:absolute}
.la-switch span{
  position:absolute;inset:0;cursor:pointer;border-radius:var(--r-pill);
  background:var(--line-2);transition:background .2s var(--ease);
  box-shadow:inset 0 1px 3px rgba(0,0,0,.14);
}
.la-switch span::before{
  content:"";position:absolute;height:19px;width:19px;left:3px;top:3px;
  background:#fff;border-radius:50%;transition:transform .2s var(--ease);
  box-shadow:0 1px 3px rgba(0,0,0,.28);
}
.la-switch input:checked + span{background:linear-gradient(120deg,var(--green),var(--green-x))}
.la-switch input:checked + span::before{transform:translateX(21px)}
.la-stop-switch input:checked + span{background:linear-gradient(120deg,#8A2419,var(--crit))}
.la-switch input:focus-visible + span{box-shadow:0 0 0 3px rgba(217,181,74,.35)}

.la-save-btn{
  background:linear-gradient(120deg,var(--green-d),var(--green));color:#fff;
  border:1px solid var(--green-d);border-radius:var(--r-s);
  font-weight:800;font-size:11.5px;cursor:pointer;font-family:inherit;
  box-shadow:0 2px 7px rgba(11,93,59,.24);transition:all .14s var(--ease);
}
.la-save-btn:hover{background:linear-gradient(120deg,var(--green),var(--green-l));transform:translateY(-1px)}

/* source picker (used outside the config area) */
.la-source-picker{position:relative;width:250px;max-width:100%}
.la-picker-button{
  display:flex;align-items:center;gap:7px;width:100%;
  padding:7px 11px;border:1px solid var(--line-2);border-radius:var(--r-s);
  background:#fff;cursor:pointer;font-size:11.5px;font-family:inherit;text-align:left;
}
.la-picker-button:hover{border-color:var(--line-gg);background:var(--mint)}
.la-picker-button.empty{color:var(--ink-4)}
.la-picker-icon{flex-shrink:0;opacity:.7}
.la-picker-text{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.la-picker-count{background:var(--mint);color:var(--ok);border-radius:var(--r-pill);padding:0 7px;font-size:9.5px;font-weight:800}
.la-picker-arrow{font-size:9px;color:var(--ink-3);flex-shrink:0}
.la-source-dropdown{
  display:none;position:absolute;top:calc(100% + 5px);left:0;right:0;z-index:260;
  background:#fff;border:1px solid var(--line);border-radius:var(--r-s);box-shadow:var(--sh-3);
  padding:8px;
}
.la-source-dropdown.open{display:block;animation:ccPop .16s var(--ease)}
.la-picker-search-wrap{position:relative;margin-bottom:7px}
.la-picker-search-wrap span{position:absolute;left:9px;top:50%;transform:translateY(-50%);font-size:11px;opacity:.6}
.la-picker-search{width:100%;padding:6px 10px 6px 28px !important;border:1px solid var(--line-2);border-radius:var(--r-xs);font-size:11.5px}
.la-picker-actions{display:flex;gap:6px;margin-bottom:7px}
.la-picker-actions button{
  flex:1;padding:4px 8px;border:1px solid var(--line-2);border-radius:var(--r-xs);
  background:#fff;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;
}
.la-picker-actions button:hover{background:var(--mint);border-color:var(--line-gg)}
.la-picker-clear{color:var(--crit)}
.la-picker-options{max-height:210px;overflow-y:auto;display:flex;flex-direction:column;gap:2px}
.la-picker-option{
  display:flex;align-items:center;gap:8px;padding:6px 9px;
  border-radius:var(--r-xs);cursor:pointer;font-size:11.5px;
}
.la-picker-option:hover{background:var(--mint)}
.la-picker-option input{position:absolute;opacity:0;pointer-events:none}
.la-custom-check{
  width:15px;height:15px;border:1px solid var(--line-2);border-radius:4px;
  flex-shrink:0;display:grid;place-items:center;background:#fff;
}
.la-picker-option input:checked + .la-custom-check{
  background:var(--green);border-color:var(--green);
}
.la-picker-option input:checked + .la-custom-check::after{content:"✓";color:#fff;font-size:10px;font-weight:900}
.la-picker-chips{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}
.la-source-chip,.la-source-more{
  background:var(--mint);color:var(--ok);border:1px solid var(--mint-3);
