}
.la-source-more{background:var(--cream-2);color:var(--ink-3);border-color:var(--line-2)}

/* ── one-agent-card-per-row layout inside the config area ── */
#lead-assignment-config-area .la-table-wrap{overflow-x:auto;padding:15px 17px}
#lead-assignment-config-area .la-table{width:100%;min-width:1320px}
#lead-assignment-config-area .la-table thead{display:none}
#lead-assignment-config-area .la-source-picker{display:none !important}
#lead-assignment-config-area .la-table tbody{
  display:grid;grid-template-columns:1fr;gap:13px;width:100%;
}
#lead-assignment-config-area .la-table tbody tr,
#lead-assignment-config-area .la-table tbody tr.la-recovered-row{
  display:grid;
  grid-template-columns:
    minmax(190px,1.7fr) minmax(240px,2.2fr) minmax(125px,1fr) minmax(170px,1.35fr)
    minmax(115px,.8fr)  minmax(145px,1fr)   minmax(170px,1.3fr) minmax(95px,.7fr);
  gap:14px;align-items:stretch;width:100%;
  padding:16px 18px;
  border:1px solid var(--line);border-radius:var(--r);background:#fff;
  box-shadow:var(--sh);transition:box-shadow .18s var(--ease),border-color .18s var(--ease);
}
#lead-assignment-config-area .la-table tbody tr:hover{box-shadow:var(--sh-2);border-color:var(--line-gg)}
#lead-assignment-config-area .la-table tbody td{
  display:block;position:relative;width:auto;min-width:0;height:auto;
  padding:2px 12px;border:0;border-left:1px solid var(--line-g);
  background:transparent;text-align:left;
}
#lead-assignment-config-area .la-table tbody td:first-child{padding-left:2px;border-left:0}
#lead-assignment-config-area .la-table tbody td::before{
  content:attr(data-field-label);display:block;margin-bottom:9px;
  color:var(--ink-4);font-size:8.5px;font-weight:800;letter-spacing:.16em;
  line-height:1.3;text-transform:uppercase;
}
#lead-assignment-config-area select.la-source-select{
  display:block;visibility:visible;opacity:1;width:100%;height:104px;
  padding:5px;overflow-y:auto;border:1px solid var(--line-2);border-radius:var(--r-s);
  background:#FCFDFC;color:var(--ink-2);font-size:10.5px;background-image:none;
}
#lead-assignment-config-area select.la-source-select option{
  min-height:22px;margin:1px 0;padding:4px 8px;border-radius:var(--r-xs);
}
#lead-assignment-config-area select.la-source-select option:checked{background:var(--green);color:#fff}
#lead-assignment-config-area .la-table td:nth-child(2) .la-field-note{margin-top:5px;font-size:8.5px;line-height:1.4}
#lead-assignment-config-area .la-number{width:60px;height:36px}
#lead-assignment-config-area .la-weight{width:56px;height:32px}
#lead-assignment-config-area .la-switch{display:block;margin:0}
#lead-assignment-config-area .la-stop-reason{display:none;width:100%;height:34px;margin-top:9px}
#lead-assignment-config-area .la-team-leader{display:block;width:100%;height:38px}
#lead-assignment-config-area .la-table td:nth-child(8){display:flex;flex-direction:column;justify-content:center}
#lead-assignment-config-area .la-save-btn{
  display:inline-flex;align-items:center;justify-content:center;
  width:100%;min-width:86px;min-height:40px;padding:9px 12px;
}
@media (max-width:1500px){
  #lead-assignment-config-area .la-table{min-width:1320px}
}
@media (max-width:760px){
  #lead-assignment-config-area .la-table{min-width:0}
  #lead-assignment-config-area .la-table-wrap{padding:12px}
  #lead-assignment-config-area .la-table tbody tr{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:14px}
  #lead-assignment-config-area .la-table tbody td{
    grid-column:span 1;border-left:0;border-top:1px solid var(--line-g);padding:10px 0 0;
  }
  #lead-assignment-config-area .la-table tbody td:nth-child(1),
  #lead-assignment-config-area .la-table tbody td:nth-child(2),
  #lead-assignment-config-area .la-table tbody td:nth-child(7),
  #lead-assignment-config-area .la-table tbody td:nth-child(8){grid-column:1 / 3}
  #lead-assignment-config-area .la-table tbody td:nth-child(1){border-top:0;padding-top:0}
