/* ──────────────────────────────────────────────────────────────────
   22 · STAFF ATTENDANCE DRAWER (#att4 · a-*)
   Rendered into document.body, so it is styled outside .cc-erp-root.
   ────────────────────────────────────────────────────────────────── */
#att4{
  --g:#0B5D3B; --gd:#06331F; --gx:#2FA46F; --gold:#B8901F; --goldl:#D9B54A;
  --ink:#12211A; --ink2:#3C5347; --ink3:#6A7C72; --ink4:#95A39B;
  --line:#E7E2D5; --lineg:#DCE8E1; --mint:#E9F5ED; --cream:#FAF7EF;
  position:fixed;inset:0;z-index:9000;
  font-family:"Inter","Segoe UI",-apple-system,Roboto,Arial,sans-serif;
  font-size:13px;color:var(--ink);
}
#att4 .a-scrim{position:absolute;inset:0;background:rgba(6,35,22,.5);backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px);animation:aFade .2s ease}
@keyframes aFade{from{opacity:0}to{opacity:1}}
@keyframes aSlide{from{transform:translateX(30px);opacity:0}to{transform:none;opacity:1}}
#att4 .a-drawer{
  position:absolute;top:0;right:0;bottom:0;
  width:min(760px,100vw);display:flex;flex-direction:column;
  background:var(--cream);box-shadow:-18px 0 48px rgba(6,35,22,.3);
  animation:aSlide .24s cubic-bezier(.22,.61,.36,1);
}
#att4.wide .a-drawer{width:min(1180px,100vw)}
#att4 .a-head{
  display:flex;align-items:center;gap:10px;padding:0 14px;height:56px;flex-shrink:0;
  background:linear-gradient(118deg,#042418,#06331F 36%,#0B5D3B 100%);color:#EAF4EE;
  box-shadow:inset 0 -2px 0 rgba(217,181,74,.45);
}
#att4 .a-mark{
  font-family:"Iowan Old Style",Georgia,serif;font-size:15px;letter-spacing:.16em;
  color:#fff;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.15);
  border-radius:8px;padding:5px 10px;
}
#att4 .a-title{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
#att4 .a-title b{font-size:13.5px;font-weight:750;color:#fff;letter-spacing:.02em}
#att4 .a-title small{font-size:10px;color:#9FCDB4;letter-spacing:.06em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#att4 .a-head button{
  width:32px;height:32px;flex-shrink:0;border-radius:8px;cursor:pointer;
  background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.16);
