  background:#fff;color:var(--ink);font-size:12.5px;font-family:inherit;
}
#att4 .a-bar #a-date{width:152px}
#att4 .a-bar #a-branch{min-width:170px}
#att4 .a-bar #a-q{flex:1;min-width:140px}
#att4 .a-bar input:focus,#att4 .a-bar select:focus{outline:none;border-color:var(--gx);box-shadow:0 0 0 3px rgba(47,164,111,.16)}
#att4 .a-lock{font-size:11px;font-weight:700;color:var(--ink3);background:var(--mint);border-radius:999px;padding:5px 12px}
#att4 .a-chips,#att4 .a-subs{
  display:flex;gap:7px;flex-wrap:wrap;padding:10px 14px;
