#att4 .a-body{flex:1;overflow-y:auto;padding:12px 14px 20px;display:flex;flex-direction:column;gap:8px}
#att4 .a-pr{display:none}
#att4 .a-note,#att4 .a-err{
  padding:26px;text-align:center;color:var(--ink3);font-size:12.5px;
