#att4 .a-sk{display:flex;flex-direction:column;gap:8px}
#att4 .a-sk i{display:block;height:62px;border-radius:12px;background:linear-gradient(90deg,#F1EEE4,#FAF7EF,#F1EEE4);background-size:200% 100%;animation:aSk 1.2s linear infinite}
@keyframes aSk{from{background-position:200% 0}to{background-position:-200% 0}}

/* employee row */
#att4 .a-row{
  display:grid;grid-template-columns:44px 1fr auto auto;align-items:center;gap:12px;
  width:100%;text-align:left;cursor:pointer;font-family:inherit;
