#att4 .a-sex{position:absolute;right:-1px;bottom:-1px;width:15px;height:15px;border-radius:50%;background:#fff;color:#3C5347;font-size:9px;display:grid;place-items:center;text-decoration:none;z-index:2}
#att4 .a-id{min-width:0;display:flex;flex-direction:column;gap:2px}
#att4 .a-id b{font-size:13px;font-weight:750;color:#0B5D3B;display:flex;align-items:center;gap:6px;flex-wrap:wrap}
#att4 .a-id small{font-size:10.5px;color:var(--ink3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#att4 .a-ph,#att4 .a-ph2{font-style:normal;color:var(--ink4);font-size:10.5px}
#att4 .a-bg{
  font-style:normal;font-size:8.5px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;
