}
#att4 .a-bg.b-r{background:#FAE9E6;color:#9E2C22;border-color:#EEC5BE}
#att4 .a-bg.b-a{background:#FBF1DA;color:#9A6B05;border-color:#EBD8A6}
#att4 .a-mtd{display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;align-items:center}
#att4 .a-mtd u{text-decoration:none;font-size:8.5px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink4);font-weight:800;margin-right:2px}
#att4 .a-mtd i,#att4 .a-tot i{
