#att4 .a-mtd i.p,#att4 .a-tot i.p{background:#E6F4EC;color:#17794E;border-color:#BEE1CD}
#att4 .a-mtd i.a,#att4 .a-tot i.a{background:#FAE9E6;color:#9E2C22;border-color:#EEC5BE}
#att4 .a-mtd i.w,#att4 .a-tot i.w{background:#F1EEE4;color:#6A7C72;border-color:#D8D2C2}
#att4 .a-mtd i.l,#att4 .a-tot i.l{background:#F0EAFA;color:#5F3C93;border-color:#D9CBF0}
#att4 .a-mtd i.e,#att4 .a-tot i.e{background:#FBF3DC;color:#9A6B05;border-color:#EAD9A6}
#att4 .a-tot i.v{background:#E9F0F9;color:#1E4E86;border-color:#C6D8EE}
#att4 .a-mtd i.sk{width:64px;height:12px;border-radius:999px;background:#F1EEE4;border:0}
#att4 .a-when{display:flex;flex-direction:column;align-items:flex-end;gap:3px;text-align:right}
#att4 .a-t{font-size:12.5px;font-weight:800;color:var(--ink);font-variant-numeric:tabular-nums;display:inline-flex;align-items:center;gap:5px}
