#att4 .a-row.s-on .a-st{color:#17794E}
#att4 .a-row.s-abs .a-st{color:#9E2C22}
#att4 .a-row.s-miss .a-st{color:#9A6B05}
#att4 .a-hr{font-size:9.5px;color:var(--ink4);letter-spacing:.06em}
#att4 .a-fl{font-size:9.5px;font-weight:700;color:#9E2C22;background:#FAE9E6;border-radius:999px;padding:1px 8px}
#att4 .a-tick{font-size:15px;color:#2FA46F;font-weight:900}

