#att4 .a-day u{text-decoration:none;font-size:8.5px;font-weight:800;letter-spacing:.06em;color:var(--ink4)}
#att4 .a-day.kP{background:#E6F4EC;border-color:#BEE1CD}
#att4 .a-day.kP u{color:#17794E}
#att4 .a-day.kHD{background:#FBF3DC;border-color:#EAD9A6}
#att4 .a-day.kHD u{color:#9A6B05}
#att4 .a-day.kA{background:#FAE9E6;border-color:#EEC5BE}
#att4 .a-day.kA u{color:#9E2C22}
#att4 .a-day.kWO{background:#F1EEE4;border-color:#D8D2C2}
#att4 .a-day.kL{background:#F0EAFA;border-color:#D9CBF0}
