body.a-printing > *:not(#att4){display:none !important}

/* ──────────────────────────────────────────────────────────────────
   23 · LEGACY INLINE-COLOUR NEUTRALISERS
   Some blocks are drawn by the page script with hard-coded inline
   colours from the old navy palette. The markup is not touched — these
   rules only repaint those inline values so nothing stays off-theme.
   ────────────────────────────────────────────────────────────────── */
.cc-erp-root [style*="color:#8C8C8C"]{color:var(--ink-3) !important}
.cc-erp-root [style*="color:#0D2B4E"]{color:var(--green-d) !important}
.cc-erp-root [style*="color:#1A2B45"]{color:var(--ink) !important}
.cc-erp-root [style*="color:#5B6B84"]{color:var(--ink-2) !important}
.cc-erp-root [style*="color:#A32D2D"]{color:var(--crit) !important}
.cc-erp-root [style*="color:#0F6E56"]{color:var(--ok) !important}
.cc-erp-root [style*="color:#C9D4E3"]{color:var(--ink-4) !important}
.cc-erp-root [style*="color:#595959"]{color:var(--ink-2) !important}
.cc-erp-root [style*="color:#B0B0B0"]{color:var(--ink-4) !important}

.cc-erp-root [style*="background:#0D2B4E"],
.cc-erp-root [style*="background-color:#0D2B4E"]{
  background:linear-gradient(120deg,var(--green-d),var(--green)) !important;color:#fff !important;
}
.cc-erp-root [style*="background:linear-gradient(135deg,#0D2B4E"]{
  background:linear-gradient(120deg,var(--green-d),var(--green)) !important;
}
.cc-erp-root [style*="background:#EEF3FA"],
.cc-erp-root [style*="background:#F1F3F7"],
.cc-erp-root [style*="background:#EEF1F6"]{background:var(--mint) !important}

.cc-erp-root [style*="#C9D4E3"],
.cc-erp-root [style*="#dde3f0"],
.cc-erp-root [style*="#eceff4"],
.cc-erp-root [style*="#E2E8F0"],
.cc-erp-root [style*="#D5DCE6"],
.cc-erp-root [style*="#EEF1F6"]{border-color:var(--line) !important}
.cc-erp-root [style*="border-top-color:#0D2B4E"]{border-top-color:var(--green-x) !important}
.cc-erp-root [style*="border-bottom:1px dotted #8C8C8C"]{border-bottom-color:var(--line-2) !important}

/* ──────────────────────────────────────────────────────────────────
   24 · SCROLLBARS
   ────────────────────────────────────────────────────────────────── */
.cc-erp-root ::-webkit-scrollbar{width:9px;height:9px}
.cc-erp-root ::-webkit-scrollbar-track{background:transparent}
.cc-erp-root ::-webkit-scrollbar-thumb{background:var(--line-2);border-radius:9px}
.cc-erp-root ::-webkit-scrollbar-thumb:hover{background:var(--ink-4)}
.cc-erp-root{scrollbar-width:thin;scrollbar-color:var(--line-2) transparent}

/* ──────────────────────────────────────────────────────────────────
   25 · DARK MODE (body.dark / .cc-erp-root.dark toggle)
   ────────────────────────────────────────────────────────────────── */
.cc-erp-root.dark{
  --cream:#0E1A13; --cream-2:#152219; --cream-3:#1B2A20; --card:#152219;
  --ink:#E6F0E9; --ink-2:#BCCFC3; --ink-3:#8FA598; --ink-4:#6D8478;
  --line:#26382C; --line-2:#314637; --line-g:#26382C; --line-gg:#3A5344;
  --mint:#182E21; --mint-2:#1F3A2A; --mint-3:#2C4D38;
  --ok-bg:#15301F; --warn-bg:#2C2410; --crit-bg:#2E1815; --info-bg:#15243A; --gold-bg:#2C2410;
  background:var(--cream);color:var(--ink);
}
.cc-erp-root.dark .main{background:var(--cream)}
.cc-erp-root.dark .sidebar{background:linear-gradient(180deg,#132019,#0E1A13);border-right-color:var(--line)}
.cc-erp-root.dark .nav-item{color:var(--ink-2)}
.cc-erp-root.dark .nav-item:hover{background:var(--cream-2);border-color:var(--line)}
.cc-erp-root.dark .card,.cc-erp-root.dark .stat-card,.cc-erp-root.dark .form-section,
.cc-erp-root.dark .ff-sec,.cc-erp-root.dark .la-card,.cc-erp-root.dark .comm-card,
.cc-erp-root.dark .script-card,.cc-erp-root.dark .queue-item,.cc-erp-root.dark .acc-item{
  background:var(--card);border-color:var(--line);
}
.cc-erp-root.dark .card-body,.cc-erp-root.dark .ff-sec-body{background:var(--card)}
.cc-erp-root.dark input,.cc-erp-root.dark select,.cc-erp-root.dark textarea,
.cc-erp-root.dark .ff-input,.cc-erp-root.dark .ff-select,.cc-erp-root.dark .ff-textarea{
  background:#0F1C14;border-color:var(--line-2);color:var(--ink);
}
.cc-erp-root.dark .cc-erp-root table,.cc-erp-root.dark table{background:var(--card);border-color:var(--line)}
.cc-erp-root.dark th{background:var(--mint);color:#CFE6D8;border-bottom-color:var(--line-2)}
.cc-erp-root.dark td{border-top-color:var(--line);color:var(--ink-2)}
.cc-erp-root.dark tbody tr:nth-child(even) td{background:#12211A}
.cc-erp-root.dark tr:hover td{background:var(--mint)}
.cc-erp-root.dark .acc-hdr{background:var(--cream-2);color:var(--ink)}
.cc-erp-root.dark .acc-body{background:var(--card);color:var(--ink-2)}
.cc-erp-root.dark .check-item,.cc-erp-root.dark .ci-v2,.cc-erp-root.dark .sg-opt,
.cc-erp-root.dark .act-tile,.cc-erp-root.dark .status-opt,.cc-erp-root.dark .bc-pair,
.cc-erp-root.dark .send-toggle{background:var(--card);border-color:var(--line);color:var(--ink)}
.cc-erp-root.dark .script-card .sc-text{background:#0F1C14;color:var(--ink)}
.cc-erp-root.dark .ff-progress-wrap{background:rgba(21,34,25,.96);border-color:var(--line)}
.cc-erp-root.dark .ff-bottom-bar{background:linear-gradient(to top,var(--cream) 62%,rgba(14,26,19,0));border-color:var(--line)}
.cc-erp-root.dark .modal-box{background:var(--cream-2);border-color:var(--line)}
.cc-erp-root.dark .tbl-wrap{background:var(--card);border-color:var(--line)}
.cc-erp-root.dark .cc-toolbar{background:var(--card);border-color:var(--line)}
.cc-erp-root.dark .tab-nav{background:var(--cream-2);border-color:var(--line)}
.cc-erp-root.dark .tab-btn.on{background:var(--card);color:#CFE6D8}

/* ──────────────────────────────────────────────────────────────────
   26 · RESPONSIVE
   ────────────────────────────────────────────────────────────────── */
@media (max-width:1280px){
  .cc-erp-root{--side-w:208px}
  .main{padding:16px 16px 36px}
  .stat-grid{grid-template-columns:repeat(auto-fit,minmax(152px,1fr));gap:11px}
  .search-wrap{width:min(320px,100%)}
}

@media (max-width:1024px){
  .hdr-brand .bs{display:none}
  .search-wrap{width:min(260px,100%)}
  .la-summary-grid{grid-template-columns:repeat(auto-fit,minmax(132px,1fr))}
}

/* tablet & below — sidebar becomes an off-canvas overlay */
@media (max-width:900px){
  .sidebar{
    position:fixed;top:var(--hdr-h);left:0;bottom:0;height:auto;
    width:262px;flex-basis:262px;z-index:180;
    box-shadow:14px 0 38px rgba(6,35,22,.2);
    transform:translateX(0);
    transition:transform .24s var(--ease);
  }
  .sidebar.collapsed{
    width:262px;flex-basis:262px;padding:10px;overflow:hidden;
    transform:translateX(-104%);box-shadow:none;
  }
  .sidebar:not(.collapsed)::before{
    content:"";position:fixed;inset:var(--hdr-h) 0 0 0;
    background:rgba(6,35,22,.34);z-index:-1;pointer-events:none;
  }
  .main{padding:15px 15px 34px}
  .stat-grid{grid-template-columns:repeat(auto-fit,minmax(142px,1fr))}
  .modal-box.wide{max-width:100%}
  .card-hdr{font-size:12px;padding:10px 13px}
  .hdr-attend .att-io{padding:3px 7px}
  .hdr-attend .att-io b{font-size:10.5px}
}

@media (max-width:760px){
  .hdr{gap:9px;padding:0 12px 0 54px}
  .hdr-center{display:none}
  .agent-info{display:none}
  .hdr-brand .bn{font-size:13px;letter-spacing:.1em}
  .la-summary-grid{grid-template-columns:repeat(2,1fr)}
  .la-table-wrap{padding:12px}
  .booking-confirm-grid{grid-template-columns:1fr}
}

@media (max-width:600px){
  .cc-erp-root{--hdr-h:54px;font-size:13.4px}
  .hdr{padding:0 10px 0 50px;gap:8px}
  .hdr-brand .logo{width:30px;height:30px;border-radius:9px;font-size:13px}
  .hdr-brand .bn{font-size:11.5px}
  .hdr-btn{padding:5px 9px;font-size:11px}
  .hdr-burger{padding:5px 9px !important;font-size:15px !important}
  .hdr-attend{padding:3px 4px;gap:4px}
  .hdr-attend .att-io{padding:3px 7px;font-size:8px;gap:4px}
  .hdr-attend .att-io b{font-size:10px}
  .agent-avatar{width:29px;height:29px;font-size:11px}

  .main{padding:13px 12px 30px}
  .stat-grid{grid-template-columns:repeat(2,1fr);gap:9px}
  .stat-card{padding:12px 13px}
  .stat-card .sv{font-size:21px}
  .stat-card .sl{font-size:8.5px;letter-spacing:.12em}
  .stat-card .ss{font-size:9.5px}
  #dash-group-panel .stat-grid{grid-template-columns:repeat(2,1fr)}

  .card{border-radius:var(--r)}
  .card-body{padding:13px}
  .card-hdr{font-size:11.5px;padding:10px 13px}
  .modal-box{padding:18px 16px 16px;border-radius:var(--r)}
  .modal-overlay{padding:12px}
  .nav-item{padding:9px 11px;font-size:13px}
  .btn{padding:8px 13px;font-size:11.5px}
  .btn-sm{padding:5px 10px;font-size:10.5px}
  .cc-erp-root table{font-size:11.5px}
  .cc-erp-root th{padding:8px 9px;font-size:9px}
  .cc-erp-root td{padding:8px 9px;font-size:11.8px}
  .ff-sec-body{padding:13px}
  .ff-progress-wrap{padding:10px 12px 9px}
  .queue-item{flex-wrap:wrap;align-items:flex-start}
  .qi-right{width:100%;justify-content:flex-end;border-top:1px dashed var(--line);padding-top:8px}
  .toast-wrap{left:12px;right:12px;bottom:12px;max-width:none}
  .toast{border-radius:var(--r-s)}
}

@media (max-width:380px){
  .stat-grid{grid-template-columns:1fr}
  .status-grid-v2{grid-template-columns:1fr}
  .action-tiles{grid-template-columns:1fr}
}

/* ──────────────────────────────────────────────────────────────────
   27 · PRINT
   ────────────────────────────────────────────────────────────────── */
@media print{
  .sidebar,.hdr,.btn-row,.ff-bottom-bar,.toast-wrap,.cc-back-bar,#cc-quick-range{display:none !important}
  .main{padding:0;overflow:visible;background:#fff}
  .cc-erp-root{background:#fff;border-radius:0;min-height:0}
  .card,.stat-card,.ff-sec,.la-card{box-shadow:none;break-inside:avoid;border-color:#CFCFCF}
  .card-hdr,.ff-sec-hdr,.la-card-header{
    background:#EDEDED !important;color:#111 !important;
    -webkit-print-color-adjust:exact;print-color-adjust:exact;box-shadow:none;
  }
  .tbl-wrap{max-height:none;overflow:visible}
}

/* ──────────────────────────────────────────────────────────────────
   28 · REMAINING SCRIPT-RENDERED BLOCKS
   ────────────────────────────────────────────────────────────────── */
/* treatment / assessment question blocks */
.tq-block{
  background:#fff;border:1px solid var(--line);border-radius:var(--r-s);
  padding:14px;margin-bottom:12px;box-shadow:var(--sh);
}
.tq-title{
  font-size:10px;font-weight:800;color:var(--green);text-transform:uppercase;
  letter-spacing:.16em;margin-bottom:11px;padding-bottom:8px;
  border-bottom:1px solid var(--line);display:flex;align-items:center;gap:8px;
}
.tq-title::before{
  content:"";width:4px;height:13px;border-radius:2px;flex:0 0 4px;
  background:linear-gradient(180deg,var(--gold-l),var(--gold));
}
/* worksheet mobile cell */
.ws-mobile{font-variant-numeric:tabular-nums;letter-spacing:.02em}
/* source picker extras */
.la-option-name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.la-picker-all{
  flex:1;padding:4px 8px;border:1px solid var(--line-2);border-radius:var(--r-xs);
  background:#fff;font-size:10px;font-weight:700;cursor:pointer;font-family:inherit;color:var(--green);
}
.la-picker-all:hover{background:var(--mint);border-color:var(--line-gg)}
/* attendance feed badge */
#att4 .a-ok{
  font-size:10px;font-weight:700;color:#17794E;background:#E6F4EC;
  border:1px solid #BEE1CD;border-radius:999px;padding:2px 10px;
}

/* ──────────────────────────────────────────────────────────────────
   29 · LAYOUT HELPERS USED BY THE PAGE SHELL
   ────────────────────────────────────────────────────────────────── */
.cc-grid-2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
@media (max-width:1024px){.cc-grid-2{grid-template-columns:1fr}}
.cc-grid-2 > .card{margin-bottom:0}

.cc-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:14px}
.cc-bar-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}

.cc-lead-banner{
  display:inline-flex;align-items:center;gap:9px;
  font-size:12.8px;font-weight:750;color:var(--green-d);
  background:#fff;border:1px solid var(--line);border-left:4px solid var(--green);
  border-radius:var(--r-s);padding:9px 14px;box-shadow:var(--sh);
}
.cc-inline-filters{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
.cc-inline-filters select{
  height:29px;font-size:11px;padding:0 26px 0 10px;width:auto;min-width:126px;
  background-position:calc(100% - 13px) 13px,calc(100% - 8px) 13px;
  border-color:rgba(255,255,255,.28);background-color:rgba(255,255,255,.12);color:#fff;
  background-image:linear-gradient(45deg,transparent 50%,#fff 50%),linear-gradient(135deg,#fff 50%,transparent 50%);
}
.cc-inline-filters select option{color:var(--ink);background:#fff}
.cc-inline-filters select:hover{background-color:rgba(255,255,255,.18)}
.cc-inline-filters select:focus{border-color:var(--gold-l);box-shadow:0 0 0 3px rgba(217,181,74,.2)}

.cc-modal-foot{margin-top:16px;display:flex;justify-content:flex-end;gap:9px;padding-top:13px;border-top:1px solid var(--line)}

/* ═══════════════════════════════════════════════════════════════════════════
   30 · v11 REFINEMENTS
   Single-row date bar · 2-row KPI tiles · report panel alignment ·
   typography normalisation. This block is last on purpose — it wins.
   ═══════════════════════════════════════════════════════════════════════════ */

/* ── 30.1 · DATE / RANGE BAR — one row, compact date fields ────────── */
.cc-erp-root .cc-toolbar,
.cc-erp-root #cc-quick-range.cc-rangebar{
  display:flex;align-items:center;flex-wrap:wrap;gap:7px;
  background:var(--card);border:1px solid var(--line);border-radius:var(--r);
  padding:9px 12px;margin:0 0 16px;box-shadow:var(--sh);width:100%;
}
/* date fields sized to hold exactly a date — beats the global width:100% */
.cc-erp-root .cc-toolbar input[type=date],
.cc-erp-root .cc-rangebar input[type=date]{
  width:132px;min-width:132px;flex:0 0 132px;
  height:32px;padding:0 8px;font-size:12px;font-weight:650;
  font-variant-numeric:tabular-nums;letter-spacing:.01em;
}
.cc-erp-root .cc-rangebar .rb-lb,
.cc-erp-root .cc-toolbar .tb-lb{
  display:inline-flex;align-items:center;gap:5px;flex:0 0 auto;
  font-size:9.5px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;
  color:var(--ink-3);margin-right:2px;
}
.cc-erp-root .cc-rangebar .rb-sep,
.cc-erp-root .cc-toolbar .tb-sep{font-size:10.5px;color:var(--ink-4);flex:0 0 auto;margin:0 1px}
/* a thin rule between the date fields and the quick chips */
.cc-erp-root .cc-rangebar .rb-div{
  width:1px;height:20px;background:var(--line-2);flex:0 0 1px;margin:0 4px;
}
/* noise removed */
.cc-erp-root .cc-rangebar .tb-hint,
.cc-erp-root .cc-toolbar .tb-hint{display:none}

.cc-erp-root .cc-rangebar .cc-qr-btn{height:30px !important;padding:0 13px !important;flex:0 0 auto}
.cc-erp-root .cc-rangebar #cc-date-mode{
  height:30px !important;min-width:172px !important;flex:0 0 auto;
  font-size:11px !important;font-weight:700 !important;
  border:1px solid var(--line-2) !important;border-radius:var(--r-pill) !important;
  background:#fff !important;color:var(--ink-2) !important;margin-left:2px;
}
.cc-erp-root .cc-rangebar #cc-date-mode:hover{border-color:var(--green-x) !important;background:var(--mint) !important}
/* Apply / Clear pushed to the end of the row on wide screens */
.cc-erp-root .cc-rangebar .cc-qr-btn[data-range="apply"]{margin-left:auto}
@media (max-width:1100px){
  .cc-erp-root .cc-rangebar .cc-qr-btn[data-range="apply"]{margin-left:0}
}
@media (max-width:600px){
  .cc-erp-root .cc-toolbar,.cc-erp-root #cc-quick-range.cc-rangebar{padding:9px 10px;gap:6px}
  .cc-erp-root .cc-toolbar input[type=date],
  .cc-erp-root .cc-rangebar input[type=date]{flex:1 1 120px;min-width:0;width:auto}
  .cc-erp-root .cc-rangebar .cc-qr-btn{flex:1 1 auto;min-width:88px}
  .cc-erp-root .cc-rangebar #cc-date-mode{flex:1 1 100%;min-width:0 !important}
  .cc-erp-root .cc-rangebar .rb-div{display:none}
}

/* ── 30.2 · KPI TILES — exactly two rows ───────────────────────────── */
.cc-erp-root .stat-grid{
  grid-template-columns:repeat(var(--cols,4),minmax(0,1fr));
  gap:12px;
}
@media (max-width:1500px){.cc-erp-root .stat-grid{--cols:4 !important}}
@media (max-width:1180px){.cc-erp-root .stat-grid{--cols:3 !important}}
@media (max-width:820px){ .cc-erp-root .stat-grid{--cols:2 !important;gap:10px}}
@media (max-width:400px){ .cc-erp-root .stat-grid{--cols:1 !important}}
/* tiles line up even when the sub-text runs to two lines */
.cc-erp-root .stat-card{display:flex;flex-direction:column;justify-content:flex-start;min-height:118px}
.cc-erp-root .stat-card .sv{margin-top:auto}
.cc-erp-root .stat-card .ss{min-height:2.7em}

/* ── 30.3 · REPORTS — equal-height, self-scrolling panels ──────────── */
.cc-erp-root #reports-area .form-grid,
.cc-erp-root #reports-area .form-grid-2{
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:14px;align-items:stretch;
}
.cc-erp-root #reports-area .form-grid > div{
  min-width:0;background:#fff;border:1px solid var(--line);
  border-radius:var(--r-s);padding:0 12px 10px;box-shadow:var(--sh);
  max-height:440px;overflow:auto;
}
.cc-erp-root #reports-area .form-grid > div > .form-section-title{
  position:sticky;top:0;z-index:4;background:#fff;
  margin:0 -12px 10px;padding:11px 12px 9px;
}
.cc-erp-root #reports-area .form-grid > div > table{border:0;border-radius:0;width:100%}
.cc-erp-root #reports-area .form-grid > div > table th{
  top:38px;background:linear-gradient(180deg,#F1F8F3,var(--mint));
}
@media (max-width:1100px){
  .cc-erp-root #reports-area .form-grid,
  .cc-erp-root #reports-area .form-grid-2{grid-template-columns:1fr}
  .cc-erp-root #reports-area .form-grid > div{max-height:none}
  .cc-erp-root #reports-area .form-grid > div > table th{top:38px}
}
/* every report card the same width, same rhythm */
.cc-erp-root #reports-area > .card,
.cc-erp-root #reports-area > div > .card{width:100%;margin-bottom:16px}
.cc-erp-root #reports-area .tbl-wrap{max-height:460px}

/* ── 30.4 · TYPOGRAPHY / COLOUR — identical on every page ──────────── */
.cc-erp-root .form-section-title,
.cc-erp-root .form-section-title[style]{
  font-size:10.5px !important;font-weight:800;color:var(--green) !important;
  text-transform:uppercase;letter-spacing:.16em;
}
.cc-erp-root #reports-area table[style],
.cc-erp-root #reports-area table{font-size:12px !important}
.cc-erp-root #reports-area td{font-size:12px;color:var(--ink-2)}
.cc-erp-root #reports-area th{font-size:9.5px}
.cc-erp-root .card-hdr span[style]{color:#BFE0CD !important;font-weight:650}
.cc-erp-root .stat-card .sl{font-size:9.5px;letter-spacing:.15em;color:var(--ink-3)}
.cc-erp-root .stat-card .sv{font-size:26px;color:var(--ink)}
.cc-erp-root .stat-card .ss{font-size:10.5px;color:var(--ink-3)}
.cc-erp-root h1,.cc-erp-root h2,.cc-erp-root h3,.cc-erp-root h4{
  color:var(--green-d);font-weight:800;letter-spacing:-.01em;line-height:1.3;
}
.cc-erp-root h2{font-size:17px}.cc-erp-root h3{font-size:15px}.cc-erp-root h4{font-size:13.5px}
.cc-erp-root b,.cc-erp-root strong{color:var(--ink);font-weight:750}
.cc-erp-root small{font-size:10.5px;color:var(--ink-3)}





/* ==========================================================================
   LIFE STAFF ATTENDANCE PANEL  v5  ·  CSS
   Standalone. Everything is scoped to #att4 / #life-att-rail, so it cannot
   disturb the host page. Paste at the end of the Style field of ANY page:
     branch-command-center · cc-new-dash · cc-dashboard · life-coo-dashboard
   ========================================================================== */

/* old branch-page attendance drawer this panel replaces (harmless elsewhere) */
#bcc3-att-drawer,#bcc3-att-backdrop{display:none!important}

/* ---- edge tab trigger ---------------------------------------------------- */
#life-att-rail{position:fixed;right:0;top:230px;z-index:1190;display:flex;flex-direction:column;gap:5px}
#life-att-rail button{writing-mode:vertical-rl;border:1px solid #b9964a;border-right:0;border-radius:6px 0 0 6px;
  background:linear-gradient(160deg,#0f3326,#215139);color:#fff3d6;padding:11px 5px;
  font:600 10px/1 Inter,system-ui,sans-serif;letter-spacing:.6px;cursor:pointer;box-shadow:-3px 0 12px #08231a2e}
#life-att-rail button:hover{background:#163f2e;border-color:#e0cb98}
@media(max-width:680px){#life-att-rail{top:auto;bottom:14px}#life-att-rail button{writing-mode:horizontal-tb;
  border-radius:16px 0 0 16px;padding:8px 12px;font-size:11px}}

/* ---- panel ---------------------------------------------------------------- */
#att4{--ink:#163326;--ink2:#3c5a49;--ink3:#5b7566;--cream:#fbf9f1;--card:#fffefa;
  --gold:#b9964a;--gold2:#e0cb98;--hair:#e2d7ba;--forest:#0f3326;--forest2:#215139;
  --on:#1f7042;--out:#4d7f63;--miss:#96670c;--abs:#9e3b2b;--leave:#39539a;--wo:#8a6410;
  --w:336px;
  position:fixed;inset:0;z-index:1200;display:none;font:12px/1.4 Inter,system-ui,sans-serif;color:var(--ink);
  -webkit-font-smoothing:antialiased}
#att4.open{display:block}
#att4.wide{--w:660px}
#att4 *{box-sizing:border-box}
#att4 button{font:inherit;cursor:pointer}
#att4 .a-scrim{position:absolute;inset:0;background:#0d2a1f4d}
#att4 .a-drawer{position:absolute;top:0;right:0;height:100%;width:min(var(--w),97vw);display:flex;flex-direction:column;
  background:var(--cream);border-left:1px solid var(--gold);box-shadow:-18px 0 60px #08231a4d;
  transition:width .18s ease;animation:aIn4 .2s ease-out}
@keyframes aIn4{from{transform:translateX(100%)}to{transform:translateX(0)}}

/* header ---------------------------------------------------------------------- */
#att4 .a-head{display:flex;align-items:center;gap:5px;padding:9px 10px;color:#fdf6e2;
  background:linear-gradient(112deg,var(--forest),var(--forest2));border-bottom:1px solid var(--gold)}
#att4 .a-mark{font-size:8px;font-weight:800;letter-spacing:2px;color:#f2e1ad;border:1px solid #c2a25988;border-radius:4px;padding:4px 5px;flex-shrink:0}
#att4 .a-title{margin-right:auto;min-width:0}
#att4 .a-title b{display:block;font-size:13px;font-weight:600;color:#fff8e6;white-space:nowrap}
#att4 .a-title small{display:block;font-size:10px;color:#d3e4d8;margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#att4 .a-head button{width:23px;height:23px;display:grid;place-content:center;border:1px solid #c2a25977;background:#ffffff1a;
  color:#f7ead0;border-radius:5px;font-size:11px;line-height:1;padding:0;flex-shrink:0}
#att4 .a-head button:hover{background:#ffffff2e;border-color:var(--gold2)}
#att4.wide [data-a-wide]{background:#c2a25945;border-color:var(--gold2)}

/* filters ---------------------------------------------------------------------- */
#att4 .a-bar{display:flex;align-items:center;gap:5px;padding:7px 9px;background:#fffdf6;border-bottom:1px solid var(--hair)}
#att4 .a-bar input,#att4 .a-bar select{font:inherit;font-size:11.5px;border:1px solid var(--hair);background:#fff;border-radius:5px;
  padding:4px 6px;color:var(--ink);min-width:0;height:27px}
#att4 .a-bar input[type=date]{width:120px;flex-shrink:0}
#att4 .a-bar select{max-width:120px}
#att4 #a-q{flex:1;min-width:60px}
#att4 .a-lock{font-size:11px;font-weight:700;color:#5c4d1f;background:#fdf6e4;border:1px solid var(--gold2);
  border-radius:5px;padding:5px 9px;white-space:nowrap;max-width:150px;overflow:hidden;text-overflow:ellipsis}
#att4 .a-bar input:focus,#att4 .a-bar select:focus{outline:none;border-color:var(--gold);box-shadow:0 0 0 2px #b9964a2e}
#att4 .a-chips,#att4 .a-subs{display:flex;flex-wrap:wrap;gap:3px;padding:6px 9px;background:#fffdf6;border-bottom:1px solid var(--hair)}
#att4 .a-subs{background:#fcf5e3}
#att4 .a-chip,#att4 .a-sub{font-size:10.5px;font-weight:600;border:1px solid var(--hair);background:#fff;color:var(--ink2);
  border-radius:14px;padding:3px 9px;white-space:nowrap}
#att4 .a-chip:hover,#att4 .a-sub:hover{border-color:var(--gold);color:var(--ink)}
#att4 .a-chip.on,#att4 .a-sub.on{background:var(--forest);border-color:var(--gold);color:#fff3d6}
#att4 .a-chip.c-ON_FLOOR{color:var(--on)}#att4 .a-chip.c-OUT_MISSING{color:var(--miss)}
#att4 .a-chip.c-ABSENT{color:var(--abs)}#att4 .a-chip.c-LEAVE{color:var(--leave)}
#att4 .a-chip.c-WEEK_OFF{color:var(--wo)}#att4 .a-chip.c-FLAG{color:var(--miss);border-color:var(--gold2)}
#att4 .a-chip.on[class*="c-"]{color:#fff3d6}
#att4 .a-sub{border-color:var(--gold2);color:#7a5a10}

/* rows -------------------------------------------------------------------------- */
#att4 .a-body{flex:1;overflow:auto;padding:7px 9px;display:flex;flex-direction:column;gap:4px;scrollbar-width:thin}
#att4 .a-pr{display:none}
#att4 .a-row{position:relative;display:flex;align-items:center;gap:8px;width:100%;text-align:left;padding:7px 9px 7px 11px;
  background:var(--card);border:1px solid var(--hair);border-radius:8px}
#att4 .a-row::before{content:"";position:absolute;left:0;top:7px;bottom:7px;width:2.5px;border-radius:0 3px 3px 0;background:var(--ink3)}
#att4 .a-row:hover{border-color:var(--gold);box-shadow:0 3px 12px #1633260f}

#att4 .a-av{position:relative;flex-shrink:0;width:32px;height:32px;border-radius:50%;background:linear-gradient(145deg,#f6f1e0,#e6dcc0);
  border:1.5px solid var(--gold);box-shadow:0 0 0 1px #fff inset;display:grid;place-content:center}
#att4 .a-av::after{content:attr(data-ini);font-size:11px;font-weight:700;color:#725c22}
#att4 .a-av img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:50%;background:#fff;z-index:1}
#att4 .a-av.g-m{border-color:#6f92bd}#att4 .a-av.g-m::after{color:#2f5f95}
#att4 .a-av.g-f{border-color:#cf95aa}#att4 .a-av.g-f::after{color:#a04568}
#att4 .a-sex{position:absolute;right:-3px;bottom:-3px;z-index:2;width:13px;height:13px;border-radius:50%;background:#fff;
  border:1px solid var(--hair);font-size:8px;line-height:11px;text-align:center;text-decoration:none;color:var(--ink2)}
#att4 .a-av.g-m .a-sex{color:#2f5f95;border-color:#b0c6de}
#att4 .a-av.g-f .a-sex{color:#a04568;border-color:#e0b8c6}

#att4 .a-id{flex:1;min-width:0;display:flex;flex-direction:column;gap:0}
#att4 .a-id b{display:flex;align-items:center;gap:4px;font-size:12px;font-weight:600;color:var(--ink);line-height:1.35;min-width:0}
#att4 .a-id b>:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#att4 .a-id small{font-size:10.5px;color:var(--ink2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;line-height:1.35}
#att4 .a-ja{color:var(--ink3)!important;font-weight:500}
#att4 .a-bg{font-style:normal;flex-shrink:0;font-size:8.5px;font-weight:800;letter-spacing:.4px;padding:1px 5px;border-radius:4px;border:1px solid}
#att4 .a-bg.b-x{color:#5d4407;background:#fbeec6;border-color:#d8bd6e}
#att4 .a-bg.b-a{color:#1f5c3c;background:#dff0e3;border-color:#a9cdb4}
#att4 .a-bg.b-b{color:#2f5f95;background:#e4edf9;border-color:#adc6e2}
#att4 .a-bg.b-h{color:#6a4088;background:#efe6f6;border-color:#cdb8dd}
#att4 .a-ph{font-style:normal;flex-shrink:0;font-size:10px;color:#2f5f95;cursor:help}
#att4 .a-ph2{color:var(--ink2)!important;font-weight:600;margin-top:3px}
#att4 .a-mtd{display:flex;flex-wrap:wrap;align-items:center;gap:2px;margin-top:2px}
#att4 .a-mtd u{text-decoration:none;font-size:9px;color:var(--ink3);font-weight:600;margin-right:1px}
#att4 .a-mtd i{font-style:normal;font-size:9.5px;font-weight:800;padding:1px 5px;border-radius:8px;border:1px solid}
#att4 .a-mtd i.p{color:var(--on);background:#e2f1e5;border-color:#b6d6bf}
#att4 .a-mtd i.a{color:var(--abs);background:#fae7e3;border-color:#e5bcb2}
#att4 .a-mtd i.w{color:var(--wo);background:#faefd9;border-color:#e0cb98}
#att4 .a-mtd i.l{color:var(--leave);background:#e8edfa;border-color:#bccae8}
#att4 .a-mtd i.e{color:#6b5a26;background:#fcf6e6;border-color:var(--gold2)}
#att4 .a-mtd i.sk{width:70px;height:11px;border:0;border-radius:6px;background:linear-gradient(90deg,#ece7d6,#f8f6ec,#ece7d6);
  background-size:200% 100%;animation:aSk4 1.1s linear infinite}

#att4 .a-when{flex-shrink:0;text-align:right;display:flex;flex-direction:column;gap:0;align-items:flex-end;max-width:46%}
#att4 .a-t{font-size:13px;font-weight:700;color:var(--ink);font-variant-numeric:tabular-nums;white-space:nowrap}
#att4 .a-t i{font-style:normal;color:var(--gold);margin:0 2px;font-size:10px}
#att4 .a-t em{font-style:normal;color:var(--ink3);letter-spacing:.5px}
#att4 .a-st{font-size:9px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:var(--ink2);white-space:nowrap}
#att4 .a-st u{text-decoration:none;font-weight:600;letter-spacing:0;text-transform:none;color:var(--ink3)}
#att4 .a-hr{font-size:9.5px;color:var(--ink2);font-variant-numeric:tabular-nums;white-space:nowrap}
#att4 .a-fl{font-size:9px;font-weight:800;color:var(--miss);white-space:nowrap}
#att4 .a-tick{position:absolute;top:4px;right:6px;font-size:10px;font-weight:700;color:var(--on)}

/* status colour codes ----------------------------------------------------------- */
#att4 .s-on{background:linear-gradient(100deg,#e9f5eb,#fffefa 62%)}
#att4 .s-on::before{background:var(--on)}#att4 .s-on .a-st{color:var(--on)}
#att4 .s-out{background:#fbfdfa}
#att4 .s-out::before{background:var(--out)}#att4 .s-out .a-st{color:var(--out)}
#att4 .s-miss{background:linear-gradient(100deg,#fcf3dd,#fffefa 62%)}
#att4 .s-miss::before{background:var(--miss)}#att4 .s-miss .a-st{color:var(--miss)}
#att4 .s-abs{background:linear-gradient(100deg,#fae9e5,#fffefa 62%)}
#att4 .s-abs::before{background:var(--abs)}
#att4 .s-abs .a-st,#att4 .s-abs .a-id b{color:var(--abs)}
#att4 .s-leave{background:linear-gradient(100deg,#eaeffa,#fffefa 62%)}
#att4 .s-leave::before{background:var(--leave)}#att4 .s-leave .a-st{color:var(--leave)}
#att4 .s-wo{background:linear-gradient(100deg,#faf1de,#fffefa 62%)}
#att4 .s-wo::before{background:var(--wo)}#att4 .s-wo .a-st{color:var(--wo)}

/* skeleton / notes -------------------------------------------------------------- */
#att4 .a-sk{display:flex;flex-direction:column;gap:4px}
#att4 .a-sk i{height:54px;border-radius:8px;border:1px solid var(--hair);
  background:linear-gradient(90deg,#f5f1e3,#fdfbf3,#f5f1e3);background-size:200% 100%;animation:aSk4 1.1s linear infinite}
@keyframes aSk4{from{background-position:200% 0}to{background-position:-200% 0}}
#att4 .a-note{padding:16px;border-radius:8px;background:#fdfcf5;color:var(--ink2);font-size:11.5px;text-align:center}
#att4 .a-err{padding:12px;border-radius:8px;background:#fdf0ed;border:1px solid #e5bcb2;color:#8a3325;font-size:11.5px}
#att4 .a-err button{margin-top:7px;border:1px solid #e5bcb2;background:#fff;border-radius:5px;padding:4px 9px}

/* month view --------------------------------------------------------------------- */
#att4 .a-mo{display:flex;flex-direction:column;gap:9px}
#att4 .a-moh{display:flex;flex-direction:column;align-items:center;gap:1px;text-align:center;padding-bottom:9px;border-bottom:1px solid var(--hair)}
#att4 .a-moh>button:first-child{align-self:flex-start;font-size:10.5px;border:1px solid var(--hair);background:#fff;border-radius:5px;padding:3px 9px;color:var(--ink2)}
#att4 .a-av.big{width:58px;height:58px;border-width:2px;margin:6px 0 4px}
#att4 .a-av.big::after{font-size:19px}
#att4 .a-moh b{display:flex;align-items:center;gap:5px;font-size:14.5px;color:var(--ink)}
#att4 .a-moh small{font-size:10.5px;color:var(--ink2)}
#att4 .a-leave{margin-top:9px;font-size:11px;font-weight:700;border:1px solid var(--gold2);background:linear-gradient(120deg,#fffdf4,#f4ead2);
  color:#6b5a26;border-radius:16px;padding:5px 14px}
#att4 .a-leave:hover{border-color:var(--gold);color:var(--ink)}
#att4 .a-mnav{display:flex;align-items:center;justify-content:center;gap:12px}
#att4 .a-mnav span{font-size:12.5px;font-weight:700;color:var(--ink);min-width:125px;text-align:center}
#att4 .a-mnav button{width:24px;height:24px;border:1px solid var(--hair);background:#fff;border-radius:5px;color:var(--ink2);padding:0}
#att4 .a-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:3px}
#att4 .a-dow{font-style:normal;font-size:9px;font-weight:700;text-align:center;color:var(--ink2);padding-bottom:2px}
#att4 .a-day{font-style:normal;display:flex;flex-direction:column;align-items:center;justify-content:center;
  min-height:38px;border:1px solid var(--hair);border-radius:6px;background:#fff}
#att4 .a-day b{font-size:12px;font-weight:700}
#att4 .a-day u{text-decoration:none;font-size:8.5px;font-weight:800}
#att4 .a-day.kP{background:#e2f1e5;border-color:#b6d6bf;color:var(--on)}
#att4 .a-day.kHD{background:#f0e8f7;border-color:#d3c0e2;color:#5e3679}
#att4 .a-day.kA{background:#fae7e3;border-color:#e5bcb2;color:var(--abs)}
#att4 .a-day.kWO{background:#faefd9;border-color:#e0cb98;color:var(--wo)}
#att4 .a-day.kL{background:#e8edfa;border-color:#bccae8;color:var(--leave)}
#att4 .a-day.kU{background:#faf9f2;color:#7c8c80}
#att4 .a-day.kF,#att4 .a-day.kN{background:#fdfdf9;border-style:dashed;color:#aab6ac}
#att4 .a-day.now{border-color:var(--gold);box-shadow:0 0 0 1.5px #b9964a66}
#att4 .a-tot{display:flex;flex-wrap:wrap;gap:4px}
#att4 .a-tot i{font-style:normal;font-size:11px;font-weight:800;padding:3px 9px;border-radius:12px;border:1px solid}
#att4 .a-tot i.p{color:var(--on);background:#e2f1e5;border-color:#b6d6bf}
#att4 .a-tot i.a{color:var(--abs);background:#fae7e3;border-color:#e5bcb2}
#att4 .a-tot i.w{color:var(--wo);background:#faefd9;border-color:#e0cb98}
#att4 .a-tot i.l{color:var(--leave);background:#e8edfa;border-color:#bccae8}
#att4 .a-tot i.e{color:#6b5a26;background:#fcf6e6;border-color:var(--gold2)}
#att4 .a-tot i.v{color:var(--ink);background:#fff;border-color:var(--gold)}
#att4 .a-leg{font-size:10px;color:var(--ink2);line-height:1.55}

/* footer -------------------------------------------------------------------------- */
#att4 .a-foot{border-top:1px solid var(--hair);background:#fffdf6;padding:6px 9px;display:flex;flex-direction:column;gap:2px;
  font-size:9.5px;color:var(--ink2);line-height:1.45}
#att4 .a-ok{color:var(--on);font-weight:800}
#att4 .a-warn{color:var(--miss);font-weight:800}

/* wide mode ----------------------------------------------------------------------- */
#att4.wide .a-row{padding:8px 11px 8px 13px;gap:10px}
#att4.wide .a-av{width:38px;height:38px}
#att4.wide .a-av::after{font-size:12.5px}
#att4.wide .a-id b{font-size:13px}
#att4.wide .a-id small,#att4.wide .a-mtd i{font-size:11px}
#att4.wide .a-t{font-size:14.5px}
#att4.wide .a-st,#att4.wide .a-hr,#att4.wide .a-fl{font-size:10px}
#att4.wide .a-day{min-height:44px}

@media(max-width:680px){#att4 .a-drawer{width:100vw;border-left:0}#att4 .a-bar{flex-wrap:wrap}}
@media(prefers-reduced-motion:reduce){#att4 .a-drawer,#att4 .a-sk i,#att4 .a-mtd i.sk{animation:none;transition:none}}

/* print: panel only, two columns on wide paper ------------------------------------ */
@media print{
  @page{size:auto;margin:8mm 7mm}
  #life-att-rail{display:none!important}
  body.a-printing>*:not(#att4){display:none!important}
  body.a-printing #att4{position:static;display:block;font-size:8.5pt}
  body.a-printing #att4 .a-scrim,body.a-printing #att4 .a-head,body.a-printing #att4 .a-bar,
  body.a-printing #att4 .a-chips,body.a-printing #att4 .a-subs,body.a-printing #att4 .a-foot{display:none!important}
  body.a-printing #att4 .a-drawer{position:static;width:100%;height:auto;box-shadow:none;border:0;background:#fff;animation:none}
  body.a-printing #att4 .a-body{display:block;overflow:visible;height:auto;padding:0;
    column-count:2;column-gap:6mm;column-fill:balance}
  body.a-printing #att4 .a-pr{display:block;column-span:all;font-size:10pt;font-weight:800;color:#163326;
    border-bottom:1.2pt solid #b9964a;padding-bottom:2mm;margin-bottom:3mm}
  body.a-printing #att4 .a-row{break-inside:avoid;page-break-inside:avoid;display:flex;width:100%;margin:0 0 1.2mm;
    padding:1.4mm 2mm;border:.4pt solid #ccc;border-radius:1.5mm;background:#fff!important;box-shadow:none}
  body.a-printing #att4 .a-row::before{width:1.2mm;top:1mm;bottom:1mm}
  body.a-printing #att4 .a-av{width:7mm;height:7mm;border-width:.4pt}
  body.a-printing #att4 .a-av::after{font-size:6pt}
  body.a-printing #att4 .a-sex,body.a-printing #att4 .a-tick{display:none}
  body.a-printing #att4 .a-id b{font-size:8.5pt}
  body.a-printing #att4 .a-id small,body.a-printing #att4 .a-mtd i,body.a-printing #att4 .a-mtd u{font-size:6.5pt}
  body.a-printing #att4 .a-t{font-size:9pt}
  body.a-printing #att4 .a-st,body.a-printing #att4 .a-hr,body.a-printing #att4 .a-fl{font-size:6.5pt}
  body.a-printing #att4 .a-mo{column-span:all}
  body.a-printing #att4 .a-leave,body.a-printing #att4 .a-mnav button,
  body.a-printing #att4 .a-moh>button:first-child{display:none}
  body.a-printing #att4 *{-webkit-print-color-adjust:exact;print-color-adjust:exact}
}
