/* Shared consultation booking form */
.cc-slot-form{color:#234a38}.cc-slot-form fieldset{border:0;padding:0;margin:0;min-width:0}.cc-slot-intro{color:#647568}.cc-slot-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.cc-slot-fields label{display:flex;flex-direction:column;gap:6px;font-size:12px;font-weight:600}.cc-slot-fields input,.cc-slot-fields select{width:100%;box-sizing:border-box;min-width:0;padding:10px;border:1px solid #cedcd2;border-radius:8px;background:white;color:#234a38}.cc-slot-times{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px;margin:20px 0;max-height:260px;overflow:auto}.cc-slot-times button{padding:10px;background:#f0fdf4;border:1px solid #aad4b5;border-radius:8px;color:#256440;cursor:pointer}.cc-slot-times button:disabled{background:#f3f4f6;color:#8d9691;border-color:#e4e7e5;cursor:not-allowed}.cc-slot-times button.chosen{background:#166534;color:white}.cc-slot-summary{background:#edf7f0;padding:12px;border-radius:8px}.cc-slot-actions{display:flex;gap:10px;flex-wrap:wrap}.cc-slot-error{color:#a12727;background:#fff0ef;padding:10px;border-radius:8px}@media(max-width:540px){.cc-slot-fields{grid-template-columns:1fr}.cc-slot-times{grid-template-columns:repeat(2,minmax(0,1fr))}}

