.cc-erp-root .cc-booking-next{margin:12px 0;padding:12px;border:1px solid #bed7c6;border-radius:9px;background:#edf6ef;color:#174b30;font-size:12px;line-height:1.5}
.cc-erp-root .cc-booking-next p{margin:5px 0 0}
