  function maskSpan(v) {return v?'<span class="cc-mask" data-real="'+escAttr(v)+'" title="Hover to reveal">'+maskPhone(v)+'</span>':'—';}
  R.addEventListener("mouseover", function (e) {
    const t = e.target && e.target.closest ? e.target.closest(".cc-mask") : null;
    if (t && t.dataset.real) t.textContent = t.dataset.real;
  });
  R.addEventListener("mouseout", function (e) {
    const t = e.target && e.target.closest ? e.target.closest(".cc-mask") : null;
    if (t && t.dataset.real && !t.dataset.pinned) t.textContent = maskPhone(t.dataset.real);
  });
  R.addEventListener("click", function (e) {
    const t = e.target && e.target.closest ? e.target.closest(".cc-mask") : null;
    if (!t || !t.dataset.real) return;
    if (t.dataset.pinned) { t.dataset.pinned = ""; t.textContent = maskPhone(t.dataset.real); }
    else { t.dataset.pinned = "1"; t.textContent = t.dataset.real; }
  });

