        ? ((d.modified || "").split(" ")[0] || "")
        : ((d.creation || "").split(" ")[0] || d.custom_posting_date || "");
    return {
      id: d.name, name: d.lead_name || d.first_name || "", phone: d.mobile_no || "", altPhone: d.phone || "",
      age: d.age || "", gender: d.gender || "", area: d.city || "", city: d.city || "",
