      pipelineDate: (d.custom_pipeline_date_and_time || "") ? (d.custom_pipeline_date_and_time || "").split(" ")[0] : "",
      pipelineTime: (d.custom_pipeline_date_and_time || "") ? ((d.custom_pipeline_date_and_time || "").split(" ")[1] || "").substring(0, 5) : "",
      apptBranch: d.lead_assign_to_branch || "", apptStatus: d.custom_appointment_status || "",
      callCount: d.custom_call_count || 0, weight: d.weight || "", height: d.height || "", heightCm: d.height || "",
      bmi: d.custom_bmi || "", bmr: "", treatments: [], concern: d.consultant || "", notes: "",
      categories: String(d.custom_treatment_interests || "").split(";").map(function (x) { return x.trim(); }).filter(Boolean),
