  function syncLeadToPortal(l, extraVals) {
    if(ccSamePhone(l.phone,l.altPhone)){toast('Primary and alternate phone must differ (last 10 digits match).','red');return Promise.reject(new Error('Duplicate alternate phone'));}
    const vals = {
      first_name: l.baseName||l.name, phone: wfManager ? (l.altPhone||"") : (l.originalAltPhone||""), age: parseInt(l.age) || 0, gender: l.gender || "",
      city: l.area || "", consultant: l.concern || "", weight: l.weight || "", height: l.heightCm || l.height || "",
      custom_bmi: l.bmi || "", custom_target_weight: l.targetWeight || "", medical_history: l.medicalHistory || "",
      custom_treatment_interests: (l.categories || []).join("; "),
      custom_specific_interests: (l.subInterests || []).join("; "),
      custom_current_medication: l.medication || "",
      custom_previous_attempts: l.prevAttempts || "",
      custom_hospitalized: (["Yes", "No"].indexOf(l.hospitalized) > -1) ? l.hospitalized : "",
      custom_marital_status: (["Single", "Married"].indexOf(l.maritalStatus) > -1) ? l.maritalStatus : "",
      custom_no_of_kids: parseInt(l.kids) || 0,
      custom_breastfeeding: (["Yes", "No"].indexOf(l.breastfeeding) > -1) ? l.breastfeeding : ""
    };
    if (l.email) vals.email_id = l.email;
    const pc = (l.categories && l.categories.length) ? portalCategoryFor(l.categories[0]) : "";
    if (pc) vals.category = pc;
    const pb = portalBranchFor(l.branchChosen || l.branchCode);
    if (pb) vals.lead_assign_to_branch = pb;
    if (canEditSource() && PORTAL.sources.indexOf(l.source) > -1) vals.source = l.source;
    if (l.enquiredFor !== undefined) vals.enquired_for = l.enquiredFor || "";
    if (l.__ownerChanged && l.assignedTo) { vals.lead_owner = l.assignedTo; l.__ownerChanged = false; }

    const coreStatus = SUBSTATUS_TO_PORTAL_STATUS[l.subStatus] || STAGE_TO_PORTAL_STATUS[l.status] || "";
    vals.custom_cc_stage = safeCcStage(l.status);
    const cleanSub = safeCcSubStatus(l.subStatus);
    if (cleanSub) vals.custom_cc_sub_status = cleanSub;
    else vals.custom_cc_sub_status = "";
    if (coreStatus) vals.status = coreStatus;
    if (l.conclusionRemark) vals.custom_conclusion_remark = l.conclusionRemark;
    vals.custom_remarks = octStoredNotes(l);
    if (l.chatScript !== undefined) vals.custom_chat_script = l.chatScript || "";
    if (extraVals) { for (var ek in extraVals) { vals[ek] = extraVals[ek]; } }
    if (l.nextFollowup) vals.custom_next_followup_date = l.nextFollowup + " " + (l.nextFollowupTime||"10:00") + ":00";
    // v-next: persist pipeline date/time when set.
    if (l.pipelineDate && l.pipelineTime) {
      vals.custom_pipeline_date_and_time = l.pipelineDate + " " + l.pipelineTime + ":00";
    }

    return frappe.call({method:'cc_update_lead',args:{lead:l.id,values:JSON.stringify(vals),expected_modified:l.serverModified,attempt:JSON.stringify(wfAttemptPayload(l)),validate_only:window.ccValidateOnly?1:0}}).then(function(r){
      const m=r.message||{};if(!m.ok)throw new Error(m.error||'Lead update was not saved');
      window.ccValidateOnly=false;if(m.validation_only){toast('Server validation passed. No record changed.','green');return r;}
      if(m.workflow){l.octProfile.workflow=m.workflow;l.savedFollowups=m.workflow.attempt_count;l.callCount=m.workflow.attempt_count;}
      l.serverModified=m.modified||l.serverModified;l.wfSavedStatus=l.subStatus;l.wfSavedStage=l.status;l.portalStatus=coreStatus||l.portalStatus;l.wfSavedPortal=l.portalStatus;
      wfState=null;renderFollowupForm();toast('Call attempt and lead update saved','green');return r;
    }).catch(function(e){window.ccValidateOnly=false;toast('Save failed. '+(e.message||'Please reload and try again.'),'red');throw e;});
  }

  function syncBookingToPortal(l, branchCode, date, time) {
    const pb = portalBranchFor(branchCode);
    if (!pb) {
      toast("⚠️ Branch '" + (branchCode || "—") + "' could not be matched to a portal Branch. Pick another branch.", "red");
      return Promise.resolve();
    }
    if (pb === "Head Office") { toast("⚠️ Pick a real branch — Head Office booking is blocked", "red"); return Promise.resolve(); }
    const t24 = to24h(time);
    if (!t24) {
      toast("⚠️ '" + (time || "") + "' isn't a valid time. Use the time picker (e.g. 16:30 for 4:30 PM).", "red");
      return Promise.resolve();
    }
    if (!isSaneApptTime(t24)) {
      toast("⚠️ " + t24 + " is outside clinic hours (" + CLINIC_OPEN_H + ":00–" + CLINIC_CLOSE_H + ":00). If you meant the afternoon, use 24-hour time — 4:30 PM is 16:30.", "red");
      return Promise.resolve();
    }
    const docSel = document.getElementById("ff-appt-doctor") || document.getElementById("apt-doctor");
    const bookVals = {
      lead_assign_to_branch: pb, branch: pb,
      custom_appointment_date_and_time: date + " " + t24 + ":00",
      custom_appointment_duration: "30 Minutes",
      status: "Appointment Booked",
      custom_appointment_status: "Booked",
      custom_cc_stage: safeCcStage(l.status || "SUCCESS"),
      custom_cc_sub_status: safeCcSubStatus(l.subStatus || "Walked In & Booked")
    };
    if (l.name) bookVals.first_name = l.name;
    if (l.age) bookVals.age = parseInt(l.age) || 0;
    if (l.gender) bookVals.gender = l.gender;
    if (l.area) bookVals.city = l.area;
    if (l.concern) bookVals.consultant = l.concern;
    if (docSel && docSel.value) bookVals.custom_consulting_doctor = docSel.value;
    return portalSetValue(l.id, bookVals)
      .then(function () {
        l.apptStatus = "Booked";
        l.apptDate = date;
        l.apptTime = t24;
        l.portalStatus = "Appointment Booked";
      })
      .catch(e => { console.error("syncBookingToPortal", e); toast("⚠️ Booking sync failed: " + (e.message || ""), "red"); });
  }

  // October 2: shared profile/queue metadata, based on posting date and saved counters.
  function ccPhoneTail(value) { const digits=String(value||'').replace(/\D/g,''); return digits.length>=10?digits.slice(-10):''; }
  function ccSamePhone(a,b) { const x=ccPhoneTail(a); return !!x&&x===ccPhoneTail(b); }
  function ccLeadAge(l, now) {
    const raw=String(l.createdOn||l.postingDate||'').slice(0,10);
    if(!/^\d{4}-\d{2}-\d{2}$/.test(raw))return 'Posting date missing';
    const start=new Date(raw+'T00:00:00+05:30'), end=new Date(now||Date.now());
    if(!Number.isFinite(+start))return 'Posting date missing';
    if(end<start)return 'Future posting date';
    const ist=new Date(+end+19800000), sy=+raw.slice(0,4), sm=+raw.slice(5,7)-1, sd=+raw.slice(8,10);
    let months=(ist.getUTCFullYear()-sy)*12+ist.getUTCMonth()-sm;
    function anchor(m){const y=sy+Math.floor((sm+m)/12),mo=(sm+m)%12,d=Math.min(sd,new Date(Date.UTC(y,mo+1,0)).getUTCDate());return Date.UTC(y,mo,d)-19800000;}
    if(anchor(months)>+end)months--;
    const hours=Math.floor((+end-anchor(months))/3600000);
    return months+'mo '+Math.floor(hours/24)+'d '+hours%24+'h';
  }
  function ccShortOwner(l){return String(l.assignedToName||friendlyAgentName(l.assignedTo)||'Unassigned').trim().split(/\s+/).slice(0,2).join(' ');}
  function ccLeadMeta(l){return '<div class="qi-sub cc-lead-meta">👤 '+escapeHtml(ccShortOwner(l))+' · Lead age: '+escapeHtml(ccLeadAge(l))+' · Follow-ups: '+Number(l.savedFollowups==null?l.callCount||0:l.savedFollowups)+'</div><div class="qi-sub">'+escapeHtml((l.categories||[]).join(', ')||l.enquiredFor||'Interest not recorded')+(l.concern?' · '+escapeHtml(l.concern):'')+'</div>';}
  function ccEnquiryLabel(cat){return cat==='Skin / Dermat'?'Skin':cat==='HT (Hair Transplant)'?'HT':cat;}
  function ccEnquirySelect(l){const choices=['Slimming','Skin','Hair','Laser','HT','Hair Patch','Life Rise'];const old=l.enquiredFor||'';return '<select class="ff-select" id="ff-enquired"><option value="">— Select enquiry —</option>'+choices.map(x=>'<option'+(old===x?' selected':'')+'>'+x+'</option>').join('')+(!choices.includes(old)&&old?'<option selected value="'+escAttr(old)+'">'+escapeHtml(old)+' (existing)</option>':'')+'</select>';}
  function ccCheckFollowupPhone(){if(document.getElementById("oct-contact-panel"))return true;const el=document.getElementById('ff-altphone');if(!el)return true;validateAltPhone(el);if(!el.checkValidity()){el.reportValidity();el.focus();toast(el.validationMessage,'red');return false;}return true;}
  function ccProfileFinance(l){
    const id=l.id;const badge=document.getElementById('cc-profile-booking');if(!badge)return;
    loadClientFinance(id).then(async fin=>{
      if(!fin||!fin.invoices.length)return;
      const invoices=[...new Map(fin.invoices.map(x=>[x.invoice,x])).values()];
      const groups=new Map();
      for(const inv of invoices){
        let branch=inv.branch||inv.branch_name||'';
        if(!branch&&inv.invoice){try{const res=await frappe.call({method:'frappe.client.get',args:{doctype:'Sales Invoice',name:inv.invoice}});branch=(res.message||{}).branch||'';}catch(e){}}
        const match=BRANCHES.find(b=>[b.code,b.name].some(x=>String(x).toLowerCase().replace(/\W/g,'')===String(branch).toLowerCase().replace(/\W/g,'')));
        const code=match?match.code:(branch||'Branch unverified');const date=String(inv.invoice_date||'').slice(0,10);const key=date+'|'+code;
        const g=groups.get(key)||{date,code,paid:0};g.paid+=Number(inv.paid_amount)||0;groups.set(key,g);
      }
      const node=document.getElementById('cc-profile-booking');if(!node||currentFollowUpLead?.id!==id)return;
      node.textContent=[...groups.values()].map(g=>'BKD On '+(g.date?new Date(g.date+'T00:00:00+05:30').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'2-digit',timeZone:'Asia/Kolkata'}).replace(/ /g,'-'):'date unverified')+', '+g.code+'-Paid-'+g.paid.toLocaleString('en-IN')+' ✓').join(' / ');
      node.title='Submitted invoice report, current financial year; paid amount recorded against linked invoices.';
    }).catch(()=>{const node=document.getElementById('cc-profile-booking');if(node&&currentFollowUpLead?.id===id)node.textContent='Booking verification unavailable';});
