  function fmtINR(n) { return "\u20b9 " + Number(n || 0).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }

  window.__ccInvoiceCache = window.__ccInvoiceCache || { key: "", rows: null, promise: null };

  function ccInvoiceRange() {
    const now = new Date();
    const fyStartYear = (now.getMonth() + 1) >= 4 ? now.getFullYear() : now.getFullYear() - 1;
    const from = fyStartYear + "-04-01";
    const to = now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, "0") + "-" + String(now.getDate()).padStart(2, "0");
    return { from: from, to: to };
  }
  function loadCcInvoiceRows() {
    const r = ccInvoiceRange();
    const from = r.from, to = r.to;
    const key = from + "|" + to;
    const cache = window.__ccInvoiceCache;
    if (cache.key === key && cache.rows) return Promise.resolve(cache.rows);
    if (cache.key === key && cache.promise) return cache.promise;
    cache.key = key; cache.rows = null;
    cache.promise = frappe.call({
      method: "frappe.desk.query_report.run",
      args: { report_name: "CC Invoice Report", filters: { from_date: from, to_date: to }, ignore_prepared_report: 1 }
    }).then(function (res) {
      const raw = ((res.message || res) || {}).result || [];
      const rows = raw.filter(function (r) { return r && typeof r === "object" && !Array.isArray(r); });
      cache.rows = rows; cache.promise = null;
      return rows;
    }).catch(function (e) { cache.promise = null; console.error("CC Invoice Report load failed", e); return []; });
    return cache.promise;
  }

  function loadClientFinance(leadId) {
    return loadCcInvoiceRows().then(function (rows) {
      const mine = rows.filter(function (r) { return r.lead_id === leadId; });
      if (!mine.length) return null;
      const billed = mine.reduce(function (s, r) { return s + (parseFloat(r.grand_total) || 0); }, 0);
      const paid = mine.reduce(function (s, r) { return s + (parseFloat(r.paid_amount) || 0); }, 0);
      const out = mine.reduce(function (s, r) { return s + (parseFloat(r.outstanding_amount) || 0); }, 0);
      const net = billed / 1.05;
      const gst = billed - net;
      const clientName = (mine[0].customer || mine[0].lead_name || leadId);
      return { name: clientName, invoices: mine, billed: billed, net: net, gst: gst, paid: paid, out: out };
    });
  }

