        '<span style="font-size:11px;font-weight:700;color:' + c + '">' + st + "</span></div>";
    }).join("") || '<div style="font-size:12px;color:#8C8C8C;padding:6px">No invoices in the selected date range.</div>';

    return '<div style="margin-top:14px">' +
