  async function seedLeads() {
    // Master lists and dated lead data are independent network reads.
    const mastersReady = (async function () {
    if (!PORTAL.loaded) {
      try {
        const results = await Promise.all([
          portalGetList("Branch", { fields: ["name"], filters: [["name", "!=", "Testing Branch"]], order_by: "name asc" }),
