          portalGetList("Concern", { fields: ["name"], order_by: "name asc" }),
          portalGetList("Healthcare Practitioner", { fields: ["name", "practitioner_name"], filters: { status: "Active", practitioner_name: ["like", "dr%"] }, order_by: "practitioner_name asc" })
        ]);
        const br = results[0], src = results[1], cat = results[2], con = results[3], docs = results[4];

        PORTAL.branches = br.map(b => b.name);
        PORTAL.sources = src.map(s => s.name);
        PORTAL.categories = cat.map(c => c.name);
        PORTAL.concerns = con.map(c => c.name);

        const seenDoc = {}; PORTAL.doctors = [];
        docs.forEach(d => { if (!seenDoc[d.practitioner_name]) { seenDoc[d.practitioner_name] = 1; PORTAL.doctors.push({ id: d.name, name: d.practitioner_name }); } });

        const [cms, empDocs, users] = await Promise.all([
          portalGetList("Employee", { fields: ["employee_name", "branch", "designation"], filters: { status: "Active", designation: ["in", CM_DESIGNATIONS] }, order_by: "branch asc" }).catch(() => []),
          portalGetList("Employee", { fields: ["name", "employee_name", "designation", "branch", "cell_number"], filters: { status: "Active", designation: ["in", DOCTOR_DESIGNATIONS] }, order_by: "branch asc" }).catch(() => []),
          portalGetList("User", { fields: ["name", "full_name"] }).catch(() => [])
        ]);

        PORTAL.centerManagers = {}; PORTAL.acmManagers = {};
        (cms || []).forEach(e => {
          if (!e.branch || e.branch === "Testing Branch") return;
          const nm = (e.employee_name || "").trim(); if (!nm) return;
          if (CM_PRIMARY.indexOf(e.designation) > -1) { if (!PORTAL.centerManagers[e.branch]) PORTAL.centerManagers[e.branch] = nm; }
          else if (CM_SECONDARY.indexOf(e.designation) > -1) { if (!PORTAL.acmManagers[e.branch]) PORTAL.acmManagers[e.branch] = nm; }
          else if (!PORTAL.centerManagers[e.branch]) { PORTAL.centerManagers[e.branch] = nm; }
        });

        PORTAL.empDoctors = (empDocs && empDocs.length)
          ? empDocs.filter(d => d.branch !== "Testing Branch" && !/test/i.test(d.employee_name || ""))
          : [];
        if (!PORTAL.empDoctors.length && docs && docs.length) {
          PORTAL.empDoctors = docs.map(d => ({ employee_name: d.practitioner_name, designation: "Doctor", branch: "All Branches", cell_number: "", name: d.name }));
        }

        PORTAL.userNames = {};
        (users || []).forEach(u => { if (u.name && u.full_name) PORTAL.userNames[u.name] = u.full_name; });
        PORTAL.leadOwners = (users || [])
          .filter(u => u.name && u.name.indexOf("@") > -1 && u.name !== "Administrator" && u.name !== "Guest")
          .map(u => ({ id: u.name, name: u.full_name || u.name }))
          .sort((a, b) => a.name.localeCompare(b.name));

