    try {
      var apptIds = [];
      APPOINTMENTS.forEach(function (a) { if (a.leadId && apptIds.indexOf(a.leadId) === -1) apptIds.push(a.leadId); });
      if (apptIds.length) {
        var vsResp = await frappe.call({
