  function openModal(title, bodyHtml, wide) {
    const tEl = document.getElementById("modal-title"); if (tEl) tEl.textContent = title;
    const bEl = document.getElementById("modal-body"); if (bEl) bEl.innerHTML = bodyHtml;
    const box = document.getElementById("modal-box"); if (box) box.className = "modal-box" + (wide ? " wide" : "");
    const m = document.getElementById("modal"); if (m) m.classList.add("show");
    // Bind click-outside-to-close + Esc-to-close once.
    if (m && !m.__ccOutsideBound) {
      m.__ccOutsideBound = true;
      m.addEventListener("mousedown", function (e) {
        // Only close when the press starts on the backdrop itself,
        // never when it starts inside the modal box.
        if (e.target === m) closeModal();
      });
      document.addEventListener("keydown", function (e) {
        if ((e.key === "Escape" || e.keyCode === 27) && m.classList.contains("show")) closeModal();
      });
    }
