  function copyText(text) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(() => toast("✅ Copied to clipboard", "green")).catch(() => fallbackCopy(text));
    } else fallbackCopy(text);
  }
  function fallbackCopy(text) {
    try {
      const ta = __realdoc.createElement("textarea");
      ta.value = text; ta.style.position = "fixed"; ta.style.left = "-9999px"; ta.style.top = "-9999px";
      (R.querySelector(".cc-erp-root") || __realdoc.body).appendChild(ta);
      ta.select(); __realdoc.execCommand("copy"); ta.remove();
      toast("✅ Copied to clipboard", "green");
    } catch (e) { toast("❌ Could not copy. Please copy manually.", "red"); console.error("Copy failed:", e); }
  }

  window.__ccCopyStore = window.__ccCopyStore || [];
  function copyBtn(text, label) {
