  const CC_PIE_COLORS = ["#0D2B4E", "#1E7A34", "#B8860B", "#0E7C86", "#A32D2D", "#5B3FB0", "#3B82F6", "#F59E0B", "#10B981", "#EC4899", "#64748B", "#DB2777"];
  function ccPolar(cx, cy, r, angleDeg) {
    const a = (angleDeg - 90) * Math.PI / 180;
    return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) };
  }
  function ccArcPath(cx, cy, r, startAngle, endAngle) {
    if (endAngle - startAngle >= 359.999) endAngle = startAngle + 359.999;
    const start = ccPolar(cx, cy, r, endAngle);
    const end = ccPolar(cx, cy, r, startAngle);
    const largeArc = (endAngle - startAngle) <= 180 ? 0 : 1;
    return ["M", cx, cy, "L", start.x, start.y, "A", r, r, 0, largeArc, 0, end.x, end.y, "Z"].join(" ");
  }
  function renderApptSourcePie() {
    const host = document.getElementById("apt-source-pie"); if (!host) return;
    const counts = {};
    APPOINTMENTS.forEach(function (a) { const s = a.source || "Unknown"; counts[s] = (counts[s] || 0) + 1; });
    const entries = Object.keys(counts).map(function (k) { return { label: k, count: counts[k] }; }).sort(function (a, b) { return b.count - a.count; });
    const total = entries.reduce(function (s, e) { return s + e.count; }, 0);
    if (!total) { host.innerHTML = '<div style="text-align:center;color:#8C8C8C;padding:20px">No appointments in this range yet.</div>'; return; }

    const cx = 100, cy = 100, r = 90;
    let angle = 0;
    const slices = entries.map(function (e, i) {
      const sweep = (e.count / total) * 360;
      const path = ccArcPath(cx, cy, r, angle, angle + sweep);
      angle += sweep;
      return '<path d="' + path + '" fill="' + CC_PIE_COLORS[i % CC_PIE_COLORS.length] + '" stroke="#fff" stroke-width="1.5"><title>' + escapeHtml(e.label) + ": " + e.count + "</title></path>";
    }).join("");
    const legend = entries.map(function (e, i) {
      const pct = Math.round((e.count / total) * 100);
      return '<div style="display:flex;align-items:center;gap:8px;padding:5px 0;font-size:12px">' +
        '<span style="width:12px;height:12px;border-radius:3px;background:' + CC_PIE_COLORS[i % CC_PIE_COLORS.length] + ';flex-shrink:0"></span>' +
        '<span style="flex:1;color:#1A2B45;font-weight:600">' + escapeHtml(e.label) + "</span>" +
        '<span style="color:#8C8C8C">' + e.count + " (" + pct + "%)</span></div>";
    }).join("");

    host.innerHTML =
      '<div style="display:flex;flex-wrap:wrap;gap:24px;align-items:center">' +
      '<svg viewBox="0 0 200 200" style="width:200px;height:200px;flex-shrink:0">' + slices + "</svg>" +
      '<div style="flex:1;min-width:200px"><div style="font-size:11px;color:#8C8C8C;margin-bottom:6px">' + total + " total appointment(s)</div>" + legend + "</div></div>";
  }

