  function renderTLMasterPage(page) {
    let rows = window.__ccTLRows || [];
    const wrap = document.getElementById("tl-master-wrap"); if (!wrap) return;
    const q = ((document.getElementById("cc-tl-search") || {}).value || "").trim().toLowerCase();
    const ownerF = (document.getElementById("cc-tl-owner") || {}).value || "";
    const statusF = (document.getElementById("cc-tl-status") || {}).value || "";
    if (ownerF) rows = rows.filter(function (l) { return l.assignedTo === ownerF; });
    if (statusF) rows = rows.filter(function (l) { return l.status === statusF; });
    if (q) rows = rows.filter(function (l) {
      return (l.name + " " + l.phone + " " + l.area + " " + l.id + " " + (l.assignedToName || "") + " " + (l.source || "")).toLowerCase().indexOf(q) > -1;
    });
    const per = 10;
    const totalPages = Math.max(1, Math.ceil(rows.length / per));
    page = Math.min(Math.max(1, page), totalPages);
    const start = (page - 1) * per;
    const slice = rows.slice(start, start + per);
