  // ═══════════════════════ SOURCE WISE APPOINTMENT & REVENUE REPORT ═════════
  // Revenue is scoped to the SAME date range as the dashboard's date picker
function renderSourceReport() {
  const host = document.getElementById("source-report-root");
  if (!host) return;

  // Check if user has Team Lead or Manager access
  const userRoles = currentRoles();
  const allowedRoles = ["System Manager", "Call Center Export", "Sales Manager", "Team Lead", "TL"];
  const hasAccess = hasAnyRole(allowedRoles) || isManagerEmail();

  if (!hasAccess) {
    host.innerHTML = 
      '<div class="card"><div class="card-body" style="text-align:center;color:#8C8C8C;padding:40px">' +
      '<div style="font-size:36px;margin-bottom:12px">🔒</div>' +
      '<div style="font-size:14px;font-weight:600;color:#0D2B4E">Access Restricted</div>' +
      '<div style="font-size:12px;margin-top:6px">This report is only available to Team Leads and Managers.</div>' +
      '</div></div>';
    return;
  }

  // Get ALL leads in the date range (not just appointments)
  const allLeads = LEADS.filter(function(l) {
    const dateMode = window.CC_DATE_MODE || "created";
    const leadDate = (dateMode === "posting") ? l.postingDate : l.date;
    const from = rangeFrom(), to = rangeTo();
    return leadDate && leadDate >= from && leadDate <= to;
  });

  // Appointment-side counts
  const apptSrc = [];
  LEADS.forEach(function (l) { if (l.apptDate) apptSrc.push(l); });
  Object.keys(window.__ccApptLeads || {}).forEach(function (k) {
    const l = window.__ccApptLeads[k];
    if (l && l.apptDate && !apptSrc.some(function (x) { return x.id === l.id; })) apptSrc.push(l);
  });

  // lead_id -> source lookup
  const leadSourceMap = {};
  LEADS.forEach(function (l) { leadSourceMap[l.id] = l.source || "Unknown"; });
  apptSrc.forEach(function (l) { if (!leadSourceMap[l.id]) leadSourceMap[l.id] = l.source || "Unknown"; });

  const sources = {};
  function bucket(name) {
    if (!sources[name]) {
      sources[name] = { 
        source: name,
        totalLeads: 0,
        booked: 0, 
        visited: 0,
        converted: 0, 
        billed: 0, 
        revenue: 0,
        paidWithoutGst: 0,
        group: getSourceGroup(name)
      };
    }
    return sources[name];
  }

  function getSourceGroup(source) {
    const normalized = String(source || "").trim().toLowerCase();

    // Wizcom sources
    if (normalized === "meta chat lead" || 
        normalized === "wiscom inbound" || 
        normalized === "fb form") {
        return "Wizcom";
    }

    // Sanbreians sources
    if (normalized === "kp meta chat" || 
        normalized === "kp inbound") {
        return "Sanbreians";
    }

    // Google sources
    if (normalized === "google inbound" || 
        normalized === "lsq" || 
        normalized === "form") {
        return "Google";
    }

    return "Other";
  }

  // Count total leads by source
  allLeads.forEach(function (l) {
    const s = bucket(l.source || "Unknown");
    s.totalLeads++;
  });

  // Count appointments and visited
  apptSrc.forEach(function (l) {
    const s = bucket(l.source || "Unknown");
    s.booked++;
    const st = l.apptStatus || "";
    if (st === "Visited Booked" || st === "Visited Not Booked") {
      s.visited++;
    }
    if (l.portalStatus === "Converted" || st === "Visited Booked") {
      s.converted++;
    }
  });

  host.innerHTML = 
    '<div class="card"><div class="card-hdr">📊 Source Wise Report <span style="font-size:11px;color:#8C8C8C;font-weight:600">(' + rangeFrom() + " → " + rangeTo() + ')</span></div>' +
    '<div class="card-body" id="source-report-body"><div style="text-align:center;color:#8C8C8C;padding:20px">Loading revenue…</div></div></div>' +

    '<div class="card" style="margin-top:16px"><div class="card-hdr">📊 Wizcom Source Report <span style="font-size:11px;color:#8C8C8C;font-weight:600">(' + rangeFrom() + " → " + rangeTo() + ')</span></div>' +
    '<div class="card-body" id="wizcom-report-body"><div style="text-align:center;color:#8C8C8C;padding:20px">Loading revenue…</div></div></div>' +

    '<div class="card" style="margin-top:16px"><div class="card-hdr">📊 Sanbreians Source Report <span style="font-size:11px;color:#8C8C8C;font-weight:600">(' + rangeFrom() + " → " + rangeTo() + ')</span></div>' +
    '<div class="card-body" id="sanbreians-report-body"><div style="text-align:center;color:#8C8C8C;padding:20px">Loading revenue…</div></div></div>' +

    '<div class="card" style="margin-top:16px"><div class="card-hdr">📊 Google Source Report <span style="font-size:11px;color:#8C8C8C;font-weight:600">(' + rangeFrom() + " → " + rangeTo() + ')</span></div>' +
    '<div class="card-body" id="google-report-body"><div style="text-align:center;color:#8C8C8C;padding:20px">Loading revenue…</div></div></div>';

  function renderTable(bodyId, groupFilter) {
    let filteredRows = Object.values(sources);
    if (groupFilter) {
      filteredRows = filteredRows.filter(function(s) { 
        return s.group === groupFilter;
      });
    }

    const rows = filteredRows.map(function (s) {
      s.visitedConvRate = s.totalLeads ? Math.round(s.visited * 100 / s.totalLeads) : 0;
      s.joinedConvRate = s.visited ? Math.round(s.converted * 100 / s.visited) : 0;
      s.paidWithoutGst = s.revenue / 1.05;
      return s;
    }).sort(function (a, b) { return b.totalLeads - a.totalLeads || b.revenue - a.revenue; });

    const tot = { 
      totalLeads: 0, booked: 0, visited: 0, converted: 0, 
      billed: 0, revenue: 0, paidWithoutGst: 0 
    };
    rows.forEach(function (r) {
      tot.totalLeads += r.totalLeads;
      tot.booked += r.booked;
      tot.visited += r.visited;
      tot.converted += r.converted;
      tot.billed += r.billed;
      tot.revenue += r.revenue;
      tot.paidWithoutGst += r.paidWithoutGst;
    });

    const body = document.getElementById(bodyId);
    if (!body) return;
    body.innerHTML =
      '<div class="tbl-wrap"><table><thead><tr>' +
      '<th>Source</th>' +
      '<th>Total Leads</th>' +
      '<th>Appointments</th>' +
      '<th>Visited</th>' +
      '<th>Visited Conv %</th>' +
      '<th>Joined/Converted</th>' +
      '<th>Joined Conv %</th>' +
      '<th>Billed</th>' +
      '<th>Paid</th>' +
      '<th>Paid Without GST</th>' +
      '</tr></thead><tbody>' +
      (rows.length ? rows.map(function (r) {
        return '<tr><td><strong>' + escapeHtml(r.source) + '</strong></td>' +
          '<td>' + r.totalLeads + '</td>' +
          '<td>' + r.booked + '</td>' +
          '<td style="color:#0D2B4E;font-weight:700">' + r.visited + '</td>' +
          '<td style="color:#B26A00;font-weight:700">' + r.visitedConvRate + '%</td>' +
          '<td><strong>' + r.converted + '</strong></td>' +
          '<td style="color:#0F6E56;font-weight:700">' + r.joinedConvRate + '%</td>' +
          '<td>' + fmtINR(r.billed) + '</td>' +
          '<td style="color:#0F6E56;font-weight:700">' + fmtINR(r.revenue) + '</td>' +
          '<td style="color:#334155;">' + fmtINR(r.paidWithoutGst) + '</td></tr>';
      }).join("") : '<tr><td colspan="10" style="text-align:center;color:#8C8C8C">No data</td></tr>') +
      (rows.length ? '<tr style="background:#E8F5E9;font-weight:800">' +
        '<td>TOTAL</td>' +
        '<td>' + tot.totalLeads + '</td>' +
        '<td>' + tot.booked + '</td>' +
        '<td>' + tot.visited + '</td>' +
        '<td>' + (tot.totalLeads ? Math.round(tot.visited * 100 / tot.totalLeads) : 0) + '%</td>' +
        '<td>' + tot.converted + '</td>' +
        '<td>' + (tot.visited ? Math.round(tot.converted * 100 / tot.visited) : 0) + '%</td>' +
        '<td>' + fmtINR(tot.billed) + '</td>' +
        '<td>' + fmtINR(tot.revenue) + '</td>' +
        '<td>' + fmtINR(tot.paidWithoutGst) + '</td></tr>' : '') +
      '</tbody></table></div>' +
      '<div style="font-size:11px;color:#8C8C8C;margin-top:8px">' +
      'Total Leads based on ' + (window.CC_DATE_MODE || "created") + ' date. ' +
      'Visited Conv = Visited / Total Leads. Joined Conv = Joined/Converted / Visited. ' +
      'Revenue from CC Invoice Report (' + rangeFrom() + ' → ' + rangeTo() + ').' +
      '</div>';
  }

  // First paint with appointment-only counts
  renderTable("source-report-body", null);
  renderTable("wizcom-report-body", "Wizcom");
  renderTable("sanbreians-report-body", "Sanbreians");
  renderTable("google-report-body", "Google");

  // Fetch invoices for the selected date range
  const srFrom = rangeFrom(), srTo = rangeTo();
  frappe.call({
    method: "frappe.desk.query_report.run",
    args: { report_name: "CC Invoice Report", filters: { from_date: srFrom, to_date: srTo }, ignore_prepared_report: 1 }
  }).then(function (res) {
    const raw = ((res.message || res) || {}).result || [];
    const invRows = raw.filter(function (r) { return r && typeof r === "object" && !Array.isArray(r); });

    invRows.forEach(function (r) {
      const src = leadSourceMap[r.lead_id] || "Unknown";
      const s = bucket(src);
      s.billed += parseFloat(r.grand_total) || 0;
      s.revenue += parseFloat(r.paid_amount) || 0;
    });
    renderTable("source-report-body", null);
    renderTable("wizcom-report-body", "Wizcom");
    renderTable("sanbreians-report-body", "Sanbreians");
    renderTable("google-report-body", "Google");

    // Resolve real sources for any lead_id we don't already have
    const missingIds = Object.keys(invRows.reduce(function (acc, r) {
      if (r.lead_id && !leadSourceMap[r.lead_id]) acc[r.lead_id] = true;
      return acc;
    }, {}));
    if (!missingIds.length) return;

    const CHUNK = 200;
    function resolveChunk(idx) {
      const slice = missingIds.slice(idx, idx + CHUNK);
      if (!slice.length) return Promise.resolve();
      return portalGetList("Lead", { fields: ["name", "source"], filters: [["name", "in", slice]] })
        .then(function (rows) {
          rows.forEach(function (r) { leadSourceMap[r.name] = r.source || "Unknown"; });
          return resolveChunk(idx + CHUNK);
        })
        .catch(function (e) { console.warn("source resolve chunk failed", e); return resolveChunk(idx + CHUNK); });
    }

    resolveChunk(0).then(function () {
      Object.keys(sources).forEach(function (k) { delete sources[k]; });

      // Re-count total leads
      allLeads.forEach(function (l) {
        const s = bucket(l.source || "Unknown");
        s.totalLeads++;
      });

      // Re-count appointments and visited
      apptSrc.forEach(function (l) {
        const s = bucket(l.source || "Unknown");
        s.booked++;
        const st = l.apptStatus || "";
        if (st === "Visited Booked" || st === "Visited Not Booked") {
          s.visited++;
        }
        if (l.portalStatus === "Converted" || st === "Visited Booked") {
          s.converted++;
        }
      });

      invRows.forEach(function (r) {
        const src = leadSourceMap[r.lead_id] || "Unknown";
        const s = bucket(src);
        s.billed += parseFloat(r.grand_total) || 0;
        s.revenue += parseFloat(r.paid_amount) || 0;
      });
      renderTable("source-report-body", null);
      renderTable("wizcom-report-body", "Wizcom");
      renderTable("sanbreians-report-body", "Sanbreians");
      renderTable("google-report-body", "Google");
    }).catch(function (e) { console.error("source enrichment pass failed", e); });
  }).catch(function (e) {
    console.error("renderSourceReport revenue load failed", e);
    const body = document.getElementById("source-report-body");
    if (body) body.innerHTML = '<div style="color:#A32D2D;padding:16px">Could not load revenue: ' + escapeHtml(e.message || "") + '</div>';
  });
}

  function renderReports() {
    const byStatus = {}; LEADS.forEach(l => { byStatus[l.status] = (byStatus[l.status] || 0) + 1; });
    const byCat = {}; LEADS.forEach(l => l.categories.forEach(c => { byCat[c] = (byCat[c] || 0) + 1; }));
    const bySource = {}; LEADS.forEach(l => { bySource[l.source] = (bySource[l.source] || 0) + 1; });
    const area = document.getElementById("reports-area"); if (!area) return;
    const denom = LEADS.length || 1;
    area.innerHTML =
      '<div class="card"><div class="card-hdr">📊 Lead Status Summary<button class="btn btn-gold btn-sm" onclick="window.print()">🖨️ Print Report</button></div><div class="card-body">' +
      '<div class="stat-grid">' + Object.entries(byStatus).map(([s, c]) => '<div class="stat-card s-blue"><div class="sl">' + stageLabel(s) + '</div><div class="sv">' + c + "</div></div>").join("") + "</div>" +
      '<div class="form-grid"><div><div class="form-section-title" style="font-size:11px">By Treatment Category</div><table style="font-size:11.5px"><thead><tr><th>Category</th><th>Leads</th><th>%</th></tr></thead><tbody>' +
      Object.entries(byCat).map(([c, n]) => "<tr><td>" + c + "</td><td>" + n + "</td><td>" + Math.round(n / denom * 100) + "%</td></tr>").join("") + "</tbody></table></div>" +
      '<div><div class="form-section-title" style="font-size:11px">By Lead Source (Top 10)</div><table style="font-size:11.5px"><thead><tr><th>Source</th><th>Leads</th></tr></thead><tbody>' +
      Object.entries(bySource).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([s, n]) => "<tr><td>" + s + "</td><td>" + n + "</td></tr>").join("") + "</tbody></table></div></div></div></div>" +
      '<div id="appt-report-root"></div>' +
      '<div id="source-report-root"></div>' +
      '<div id="source-status-report-root"></div>' +
      '<div id="agent-status-report-root"></div>' +
      '<div id="branch-status-report-root"></div>' +
      '<div id="substatus-report-root"></div>' +
      '<div id="pipeline-report-root"></div>' +
      '<div class="card"><div class="card-hdr">💰 Sales Overview <span style="font-size:11px;color:#8C8C8C;font-weight:600">(' + rangeFrom() + " → " + rangeTo() + ')</span></div>' +
      '<div class="card-body" id="reports-sales-body"><div style="text-align:center;color:#8C8C8C;padding:24px">Loading sales from CC Invoice Report…</div></div></div>';
    renderApptReport();
    renderSourceReport();
    renderSourceStatusReport();
    renderAgentStatusReport();
    renderBranchStatusReport();
    renderSubStatusReport();
    renderPipelineReport();
    renderReportsSales();
  }

  // ── v-next: Sub-Status count report. One row per CC sub-status with lead
  //    count + %. Each row is clickable → opens that sub-status's lead list. ──
  function renderSubStatusReport() {
    const host = document.getElementById("substatus-report-root"); if (!host) return;
    const bySub = {};
    LEADS.forEach(function (l) {
      const k = l.subStatus || "(none)";
      bySub[k] = (bySub[k] || 0) + 1;
    });
    const denom = LEADS.length || 1;
    const rows = Object.keys(bySub).sort(function (a, b) { return bySub[b] - bySub[a]; });
    const body = rows.map(function (k) {
      const n = bySub[k];
