      '<button class="btn btn-gold btn-sm" style="margin-left:auto" onclick="window.print()">🖨️ Print</button></div>' +
      '<div class="card-body" style="overflow-x:auto"><table style="font-size:11.5px;min-width:100%;text-align:center">' +
      '<thead><tr><th style="text-align:left">Sub-Status</th><th>Leads</th><th>%</th><th></th></tr></thead>' +
