      '<tr style="font-weight:800;background:#F4F8F5"><td style="text-align:left">Total</td><td>' + LEADS.length + '</td><td>100%</td><td></td></tr>' +
      '</tbody></table>' +
      '<div style="font-size:10.5px;color:#8C8C8C;margin-top:6px">' + rows.length + ' sub-statuses · ' + LEADS.length + ' leads in range</div>' +
      '</div></div>';
  }

