  // ── v-next: cross-tab (matrix) reports over live LEADS ──────────────────
  //   Rows = source (or agent), columns = distinct statuses, cells = counts.
  //   Status here = the display stage (CC pipeline). "status_field" toggles
  //   between the CC stage and the raw portal sub-status if ever needed.
  function ccMatrixReport(opts) {
    // opts: { dim: "source"|"agent", rowKey(l)->string, rowLabel(key)->string, title, rowHeader }
    // Columns = CC sub-status. Every non-empty cell + total is clickable.
    const statusOf = function (l) { return l.subStatus || "(none)"; };
    const colSet = {}, rowMap = {}, rowTotals = {}, colTotals = {};
    let grand = 0;
    LEADS.forEach(function (l) {
      const rk = opts.rowKey(l) || "(none)";
      const st = statusOf(l);
      colSet[st] = true;
      if (!rowMap[rk]) rowMap[rk] = {};
      rowMap[rk][st] = (rowMap[rk][st] || 0) + 1;
      rowTotals[rk] = (rowTotals[rk] || 0) + 1;
      colTotals[st] = (colTotals[st] || 0) + 1;
      grand++;
    });
    const cols = Object.keys(colSet).sort();
    const rowKeys = Object.keys(rowMap).sort(function (a, b) { return (rowTotals[b] || 0) - (rowTotals[a] || 0); });
    const dim = opts.dim;
    const cellClick = function (rk, sv) {
      const enc = "matrixcell:" + dim + "|" + String(rk).replace(/'/g, "\\'") + "|" + String(sv).replace(/'/g, "\\'");
      return "openTileList('" + escapeHtml(enc) + "')";
    };
    const rowClick = function (rk) {
      return "openMatrixRow('" + dim + "','" + String(rk).replace(/'/g, "\\'") + "')";
    };
    let head = '<tr><th style="text-align:left;position:sticky;left:0;background:#F4F8F5;z-index:2">' + escapeHtml(opts.rowHeader) + "</th>";
    cols.forEach(function (c) { head += '<th style="white-space:nowrap">' + escapeHtml(c) + "</th>"; });
    head += '<th style="white-space:nowrap;font-weight:800">Total</th></tr>';
    let bodyRows = rowKeys.map(function (rk) {
      let tds = '<td style="text-align:left;font-weight:600;position:sticky;left:0;background:#fff;z-index:1;cursor:pointer" onclick="' + rowClick(rk) + '">' + escapeHtml(opts.rowLabel ? opts.rowLabel(rk) : rk) + "</td>";
      cols.forEach(function (c) {
        const v = (rowMap[rk][c] || 0);
        if (v) tds += '<td style="cursor:pointer" onclick="' + cellClick(rk, c) + '" onmouseover="this.style.background=\'#EAF4EC\'" onmouseout="this.style.background=\'\'"><span style="text-decoration:underline;text-decoration-style:dotted">' + v + "</span></td>";
        else tds += '<td><span style="color:#C9D4E3">·</span></td>';
      });
      tds += '<td style="font-weight:800;cursor:pointer" onclick="' + rowClick(rk) + '">' + (rowTotals[rk] || 0) + "</td>";
      return "<tr>" + tds + "</tr>";
    }).join("");
    let footer = '<tr style="font-weight:800;background:#F4F8F5"><td style="text-align:left;position:sticky;left:0;background:#F4F8F5">Total</td>';
    cols.forEach(function (c) { footer += "<td>" + (colTotals[c] || 0) + "</td>"; });
    footer += "<td>" + grand + "</td></tr>";
    const csvName = opts.title.replace(/[^A-Za-z0-9]+/g, "_");
    return '<div class="card"><div class="card-hdr">' + escapeHtml(opts.title) +
      '<button class="btn btn-gy btn-sm" style="margin-left:auto" onclick="ccExportMatrixCsv(\'' + opts.rowHeader.replace(/'/g, "") + '\',\'' + csvName + '\')">⬇️ CSV</button>' +
      '<button class="btn btn-gold btn-sm" onclick="window.print()">🖨️ Print</button></div>' +
      '<div class="card-body" style="overflow-x:auto"><div style="font-size:10.5px;color:#8C8C8C;margin-bottom:6px">Columns = sub-status · click any count to view those leads</div><table style="font-size:11.5px;min-width:100%;text-align:center">' +
      "<thead>" + head + "</thead><tbody>" + bodyRows + footer + "</tbody></table>" +
      '<div style="font-size:10.5px;color:#8C8C8C;margin-top:6px">' + rowKeys.length + " rows × " + cols.length + " sub-statuses · " + grand + " leads in range</div></div></div>";
  }

  // Whole-row drill: all leads for a source/agent regardless of sub-status.
  function openMatrixRow(dim, rowval) {
    const list = LEADS.filter(function (l) {
      const rk = (dim === "agent") ? (l.assignedTo || "(unassigned)")
        : (dim === "branch") ? (l.branchSuggested || l.branchChosen || l.branchCode || "(no branch)")
        : (l.source || "(no source)");
      return rk === rowval;
    });
    const rowLabel = (dim === "agent") ? (friendlyAgentName(rowval) || rowval) : rowval;
    const rows = list.length ? list.map(function (l) {
      const apptLine = apptStatusPill(l.apptStatus || "Pending") + followUpPill(l) + pipelinePill(l) +
        (l.apptDate ? '<span style="font-size:10.5px;color:#5F6F63;margin-left:6px">📅 ' + escapeHtml(l.apptDate) + (l.apptTime ? " " + escapeHtml(l.apptTime) : "") + "</span>" : "");
      return '<div class="queue-item"><div><div class="qi-name">' + l.name + '</div><div class="qi-sub">' + maskSpan(l.phone) + " | " + l.area + " | " + stageLabel(l.status) + ' · ' + escapeHtml(l.subStatus || "—") + '</div><div class="qi-sub" style="color:#0D2B4E;font-weight:600">👤 ' + (l.assignedToName || "Unassigned") + '</div><div class="qi-tags" style="margin-top:4px">' + apptLine + "</div></div>" +
        '<button class="btn btn-n btn-sm" onclick="closeModal();openLeadFollowup(\'' + l.id + '\')">Open</button></div>';
    }).join("") : '<div style="padding:16px;color:#8C8C8C;text-align:center">No leads.</div>';
    openModal((dim === "agent" ? "Agent" : dim === "branch" ? "Branch" : "Source") + ": " + rowLabel + " (" + list.length + ")", rows, true);
  }

