  // CSV export walks the rendered matrix table for the given row-header label.
  function ccExportMatrixCsv(rowHeaderLabel, fname) {
    const tables = (R || document).querySelectorAll("#page-reports table");
    let target = null;
    tables.forEach(function (t) {
      const th = t.querySelector("thead th");
      if (th && th.textContent.trim() === rowHeaderLabel) target = t;
    });
    if (!target) { toast && toast("Table not found"); return; }
    let csv = [];
    target.querySelectorAll("tr").forEach(function (tr) {
      const cells = [].map.call(tr.querySelectorAll("th,td"), function (c) {
        let v = c.textContent.replace(/·/g, "0").replace(/\s+/g, " ").trim();
        if (v.indexOf(",") > -1 || v.indexOf('"') > -1) v = '"' + v.replace(/"/g, '""') + '"';
        return v;
      });
      csv.push(cells.join(","));
    });
    const blob = new Blob([csv.join("\n")], { type: "text/csv" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = (fname || "matrix_report") + ".csv";
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 1500);
  }

  function renderReportsSales() {
    const from = rangeFrom(), to = rangeTo();
    const meEmail = (currentAgent && currentAgent.id) || (frappe.session && frappe.session.user) || "";

    const roles = currentRoles();
    const ALL_ACCESS_ROLES = ["System Manager", "Call Center Export", "Sales Manager"];
    const seeAll = hasAnyRole(ALL_ACCESS_ROLES);

    const norm = function (s) { return String(s || "").replace(/\s+/g, " ").trim().toLowerCase(); };

    function resolveFullName() {
      return new Promise(function (resolve) {
        if (!meEmail) { resolve(""); return; }
        try {
          frappe.call({
            method: "frappe.client.get_value",
            args: { doctype: "User", filters: { name: meEmail }, fieldname: "full_name" }
          }).then(function (uRes) { resolve(((uRes && uRes.message) || {}).full_name || ""); },
            function () { resolve(""); });
        } catch (e) { resolve(""); }
      });
    }

    resolveFullName().then(function (dbFullName) {
      return frappe.call({
        method: "frappe.desk.query_report.run",
        args: { report_name: "CC Invoice Report", filters: { from_date: from, to_date: to }, ignore_prepared_report: 1 }
      }).then(function (res) {
        const raw = ((res.message || res) || {}).result || [];
        let rows = raw.filter(function (r) { return r && typeof r === "object" && !Array.isArray(r); });
        const body = document.getElementById("reports-sales-body"); if (!body) return;

        if (seeAll) {
          if (!rows.length) { body.innerHTML = '<div style="text-align:center;color:#8C8C8C;padding:24px">No sales in this range.</div>'; return; }
          renderReportsSalesTables(rows, body, "All Agents", true);
          return;
        }

        const aliasList = [];
        const pushAlias = function (v) { const n = norm(v); if (n && aliasList.indexOf(n) === -1) aliasList.push(n); };
        pushAlias(dbFullName);
        pushAlias(currentAgent && currentAgent.name);
        pushAlias(frappe.session && frappe.session.user_fullname);
        if (PORTAL.userNames && PORTAL.userNames[meEmail]) pushAlias(PORTAL.userNames[meEmail]);
        LEADS.forEach(function (l) { if (norm(l.assignedTo) === norm(meEmail)) pushAlias(l.assignedToName); });

        const matchesMe = function (ownerName) { const o = norm(ownerName); return !!o && aliasList.indexOf(o) > -1; };
        rows = rows.filter(function (r) { return matchesMe(r.lead_owner_name); });

        const meLabel = dbFullName || (currentAgent && currentAgent.name) || "you";
        if (!rows.length) {
          body.innerHTML = '<div style="text-align:center;color:#8C8C8C;padding:24px">No sales for <strong>' + escapeHtml(meLabel) + "</strong> in this range." +
            '<br><span style="font-size:11px">Matched on: ' + escapeHtml(aliasList.join(" · ") || "—") + "</span>" +
            '<br><span style="font-size:11px;color:#B26A00">Your roles: ' + escapeHtml(roles.join(", ") || "none") + "</span>" +
            '<br><span style="font-size:11px;color:#8C8C8C">(Managers with System Manager, Call Center Export, or Sales Manager see all.)</span></div>';
          return;
        }
        renderReportsSalesTables(rows, body, meLabel, false);
      });
    }).catch(function (e) {
      const body = document.getElementById("reports-sales-body");
      if (body) body.innerHTML = '<div style="color:#A32D2D;padding:16px">Failed to load sales: ' + escapeHtml(e.message || "") + "</div>";
    });
  }

  function renderReportsSalesTables(rows, body, meLabel, seeAll) {
      const f = function (n) { return "₹" + Math.round(n || 0).toLocaleString("en-IN"); };
      const totBilled = rows.reduce(function (s, r) { return s + (parseFloat(r.grand_total) || 0); }, 0);
      const totRev = rows.reduce(function (s, r) { return s + (parseFloat(r.paid_amount) || 0); }, 0);
      const totOut = rows.reduce(function (s, r) { return s + (parseFloat(r.outstanding_amount) || 0); }, 0);

      function group(keyFn, labelFn) {
        const m = {};
        rows.forEach(function (r) {
          const k = keyFn(r) || "Unknown";
          if (!m[k]) m[k] = { key: k, label: labelFn(r, k), inv: 0, billed: 0, rev: 0, out: 0, lastInvDate: "" };
          const g = m[k];
          g.inv++; g.billed += parseFloat(r.grand_total) || 0; g.rev += parseFloat(r.paid_amount) || 0; g.out += parseFloat(r.outstanding_amount) || 0;
          const idt = r.invoice_date || "";
          if (idt && (!g.lastInvDate || idt > g.lastInvDate)) g.lastInvDate = idt;
        });
        return Object.keys(m).map(function (k) { return m[k]; }).sort(function (a, b) { return b.rev - a.rev; });
      }

      const byAgent = group(function (r) { return r.lead_owner_name; }, function (r, k) { return k; });
      const byLead = group(function (r) { return r.lead_id || r.invoice; }, function (r, k) {
        const nm = (r.lead_name || r.customer || k);
        return seeAll && r.lead_owner_name ? (nm + " — " + r.lead_owner_name) : nm;
      });

      const kpis =
        '<div class="stat-grid" style="margin-bottom:14px">' +
        '<div class="stat-card s-green"><div class="sl">Total Billed</div><div class="sv" style="font-size:18px">' + f(totBilled) + "</div></div>" +
        '<div class="stat-card s-teal"><div class="sl">Revenue (Paid)</div><div class="sv" style="font-size:18px">' + f(totRev) + "</div></div>" +
        '<div class="stat-card s-red"><div class="sl">Outstanding</div><div class="sv" style="font-size:18px">' + f(totOut) + "</div></div>" +
        '<div class="stat-card s-blue"><div class="sl">Invoices</div><div class="sv">' + rows.length + "</div></div></div>";

      const agentRows = byAgent.map(function (g, i) {
        return "<tr><td>" + (i + 1) + "</td><td><strong>" + escapeHtml(g.label) + "</strong></td><td>" + g.inv + "</td>" +
          "<td>" + f(g.billed) + "</td><td style='color:#0F6E56;font-weight:700'>" + f(g.rev) + "</td>" +
          "<td style='color:" + (g.out > 0 ? "#A32D2D" : "#8C8C8C") + "'>" + f(g.out) + "</td>" +
          "<td>" + (totRev > 0 ? Math.round(g.rev / totRev * 100) : 0) + "%</td></tr>";
      }).join("");
      const agentTable =
        '<div class="form-section-title" style="font-size:11px;margin-top:6px">👤 ' + (seeAll ? "Agent-wise Sales (Lead Owner)" : ("My Sales Summary (" + escapeHtml(meLabel || "") + ")")) + "</div>" +
        '<div class="tbl-wrap" style="max-height:340px;overflow:auto"><table style="font-size:11.5px"><thead><tr>' +
        "<th>#</th><th>Lead Owner</th><th>Inv</th><th>Total Billed</th><th>Revenue</th><th>Outstanding</th><th>Rev%</th></tr></thead>" +
        "<tbody>" + agentRows + "</tbody><tfoot><tr style='font-weight:800'><td colspan='2'>TOTAL</td><td>" + rows.length + "</td><td>" + f(totBilled) + "</td><td>" + f(totRev) + "</td><td>" + f(totOut) + "</td><td>100%</td></tr></tfoot></table></div>";

      const leadTable =
        '<div class="form-section-title" style="font-size:11px;margin-top:16px">🧾 ' + (seeAll ? "Lead-wise Sales (per client)" : "My Lead-wise Sales (per client)") + "</div>" +
        '<input id="cc-rep-search" placeholder="🔍 Search client / owner…" style="width:100%;height:32px;padding:0 10px;border:1px solid #C9D4E3;border-radius:8px;font-size:12.5px;margin-bottom:8px">' +
        '<div id="reports-lead-table"></div>';

      body.innerHTML = kpis + agentTable + leadTable;

      window.__ccReportLeadRows = byLead;
      renderReportLeadPage(1);
      const rs = document.getElementById("cc-rep-search");
      if (rs) rs.addEventListener("input", function () { renderReportLeadPage(1); });
  }

  function renderReportLeadPage(page) {
