  function buildPager(page, totalPages, fnName) {
    if (totalPages <= 1) return '<div style="font-size:11px;color:#8C8C8C;padding:8px 2px">' + "Showing all results" + "</div>";
    const btn = function (label, target, disabled, active) {
      return '<button ' + (disabled ? "disabled" : "") + ' onclick="' + fnName + "(" + target + ')" style="min-width:30px;height:28px;padding:0 8px;margin:0 2px;border:1px solid ' + (active ? "#0D2B4E" : "#C9D4E3") + ";border-radius:6px;background:" + (active ? "#0D2B4E" : "#fff") + ";color:" + (active ? "#fff" : "#1A2B45") + ";font-size:11.5px;font-weight:700;cursor:" + (disabled ? "default" : "pointer") + ';opacity:' + (disabled ? "0.5" : "1") + '">' + label + "</button>";
    };
    let nums = "";
    const win = 2;
    for (let p = 1; p <= totalPages; p++) {
      if (p === 1 || p === totalPages || (p >= page - win && p <= page + win)) nums += btn(String(p), p, false, p === page);
      else if (p === page - win - 1 || p === page + win + 1) nums += '<span style="padding:0 4px;color:#8C8C8C">…</span>';
    }
    return '<div style="display:flex;align-items:center;flex-wrap:wrap;gap:2px;padding:10px 2px">' +
      btn("‹ Prev", page - 1, page <= 1, false) + nums + btn("Next ›", page + 1, page >= totalPages, false) +
      '<span style="margin-left:auto;font-size:11px;color:#8C8C8C">Page ' + page + " of " + totalPages + "</span></div>";
  }

