  function bulkSetLeadOwner(leadIds, ownerId) {
    const CHUNK = 10;
    let ok = 0, failed = 0;
    function runChunk(idx) {
      const slice = leadIds.slice(idx, idx + CHUNK);
      if (!slice.length) return Promise.resolve();
      return Promise.all(slice.map(function (id) {
        return portalSetValue(id, { lead_owner: ownerId }).then(function () { ok++; }, function () { failed++; });
      })).then(function () { return runChunk(idx + CHUNK); });
    }
    return runChunk(0).then(function () { return { ok: ok, failed: failed }; });
  }

  function applyManualAssignment() {
    const ids = Object.keys(window.__ccAssignSelected);
    const ownerId = (document.getElementById("cc-la-assign-to") || {}).value || "";
    if (!ids.length) { toast("⚠️ Select at least one lead first", "gold"); return; }
