  function updateAutoTransferPreview() {
    const countEl = document.getElementById("cc-auto-count");
    const ownersEl = document.getElementById("cc-auto-owners");
    const statusF = (document.getElementById("cc-auto-status") || {}).value || "";
    const owners = loadedLeadOwners();
    if (!statusF) { if (countEl) countEl.textContent = "Select a status to preview"; if (ownersEl) ownersEl.innerHTML = ""; return; }
    const matches = autoTransferMatches();
    if (countEl) countEl.textContent = matches.length + " lead(s) with status \"" + stageLabel(statusF) + "\" will be redistributed";
    if (ownersEl) {
      if (!owners.length) ownersEl.innerHTML = '<span style="color:#A32D2D">No lead owners found in the current range — cannot auto-transfer.</span>';
      else ownersEl.innerHTML = "Across " + owners.length + " owner(s): " + owners.map(function (o) { return escAttr(o.name); }).join(", ") +
        " — roughly " + Math.ceil(matches.length / Math.max(1, owners.length)) + " lead(s) each.";
    }
