  function runAutoTransfer() {
    const statusF = (document.getElementById("cc-auto-status") || {}).value || "";
    if (!statusF) { toast("⚠️ Choose a status first", "gold"); return; }
    const matches = autoTransferMatches();
    const owners = loadedLeadOwners();
    if (!matches.length) { toast("⚠️ No leads match that status", "gold"); return; }
    if (!owners.length) { toast("⚠️ No lead owners available to distribute to", "red"); return; }
    const sorted = matches.slice().sort(function (a, b) { return a.id < b.id ? -1 : 1; });
    const plan = sorted.map(function (l, i) { return { id: l.id, owner: owners[i % owners.length].id }; });
    showLoader("Auto-transferring " + plan.length + " lead(s) across " + owners.length + " owner(s)…");
    const CHUNK = 10;
    let ok = 0, failed = 0;
    function runChunk(idx) {
      const slice = plan.slice(idx, idx + CHUNK);
      if (!slice.length) return Promise.resolve();
      return Promise.all(slice.map(function (p) {
        return portalSetValue(p.id, { lead_owner: p.owner }).then(function () { ok++; }, function () { failed++; });
      })).then(function () { return runChunk(idx + CHUNK); });
    }
    runChunk(0).then(function () {
      hideLoader();
      toast("✅ Auto-transferred " + ok + " lead(s)" + (failed ? (", " + failed + " failed") : "") + " across " + owners.length + " owners", failed ? "gold" : "green");
      reloadLeads().then(function () { renderLeadAssignPage(); });
    });
  }

