  function renderDuplicateLeadsFiltered(page) {
    const wrap = document.getElementById("dup-leads-list"); if (!wrap) return;
    const q = ((document.getElementById("cc-dup-search") || {}).value || "").trim().toLowerCase();
    let rows = window.__ccDupRows || [];
    if (q) rows = rows.filter(function (r) {
      return ((r.name1 || "") + " " + (r.phone || "") + " " + (r.enquired_for || "")).toLowerCase().indexOf(q) > -1;
    });

    if (!rows.length) {
      wrap.innerHTML = '<div style="text-align:center;color:#8C8C8C;padding:24px">✅ No duplicate submission attempts in this range.</div>';
      return;
    }

    const summary = '<div style="font-size:12px;color:#0D2B4E;font-weight:700;margin-bottom:12px;padding:8px 12px;background:#FDECEA;border-radius:8px">⚠️ ' + rows.length + " duplicate submission attempt(s) in this range.</div>";

    const per = 10;
    const totalPages = Math.max(1, Math.ceil(rows.length / per));
    page = Math.min(Math.max(1, page || 1), totalPages);
    const slice = rows.slice((page - 1) * per, (page - 1) * per + per);

    const cards = slice.map(function (r) {
      const timeStr = fmtDate((r.creation || "").split(" ")[0]) + " " + ((r.creation || "").split(" ")[1] || "").slice(0, 5);
      return '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;border:1px solid #eceff4;border-radius:9px;margin-bottom:8px;background:#fff">' +
        '<div style="flex:1;min-width:0"><div style="font-size:12.5px;font-weight:700;color:#1A2B45">' + escapeHtml(r.name1 || "—") + "</div>" +
        '<div style="font-size:11px;color:#8C8C8C;margin-top:2px">📱 ' + escapeHtml(r.phone || "—") + " · 💬 " + escapeHtml(r.enquired_for || "—") + " · 🕐 " + timeStr + "</div></div>" +
        '<button class="btn btn-n btn-sm" onclick="findAndOpenLeadByPhone(\'' + escAttr(r.phone || "") + '\')">🔍 Find Original Lead</button></div>';
    }).join("");

    wrap.innerHTML = summary + cards + buildPager(page, totalPages, "renderDuplicateLeadsFiltered");
  }

  function findAndOpenLeadByPhone(phone) {
