    let callRequestPending = false;
  let timedCallReference = '';
  async function startCallTimer() {
    const lead = currentFollowUpLead;
    if (!lead) { toast("Select a lead before calling", "red"); return; }
    if (callRequestPending) return;
    if (!window.lifeConvoxStartCall) { toast("The phone connection did not load. Refresh this page and try Start Call again. If it still fails, contact your administrator.", "red"); return; }
    callRequestPending = true;
    const buttons = document.querySelectorAll('[onclick="startCallTimer()"]');
    buttons.forEach(button => { button.disabled = true; });
    try {
      const result = await window.lifeConvoxStartCall(lead.id);
      if (!result.success) { toast(result.message || "Call request failed. Check the ConVox phone.", "red"); return; }
      toast(result.message || "Call request accepted. Answer through the ConVox phone.", "teal");
      if (currentFollowUpLead?.id !== lead.id) return;
      // Acceptance is not a live call state. Only vendor callbacks report outcomes.
      timedCallReference = result.refno || '';
      if (callTimerInterval) clearInterval(callTimerInterval);
      callTimerInterval = null;
      document.querySelectorAll('[data-convox-timer]').forEach(el => {
        el.textContent = "Request accepted · check phone";
      });
    } catch (error) {
      toast((window.lifeMessageText?.(error) || error?.message) || 'Call request failed. Check the ConVox phone before retrying.', 'red');
    } finally {
      callRequestPending = false;
      buttons.forEach(button => { button.disabled = false; });
    }
  }
  window.addEventListener('message', function (event) {
    if (event.origin !== window.location.origin || event.source !== window.parent) return;
    const data = event.data;
    if (data?.type !== 'life-convox-status' || !timedCallReference || data.call_reference !== timedCallReference) return;
    if (data.event_type !== 'Call Status') return;
    const status = typeof data.call_status === 'string' ? data.call_status.slice(0, 80) : '';
    document.querySelectorAll('[data-convox-timer]').forEach(el => {
      el.textContent = status ? 'Call result: ' + status : 'Call result received';
    });
  });
  function stopCallTimer() {
