  const HISTORY_FIELD_LABELS = {
    status: "Status", custom_cc_stage: "CC Stage", custom_cc_sub_status: "Sub-status",
    lead_owner: "Lead Owner", custom_appointment_status: "Appointment", branch: "Branch",
    lead_assign_to_branch: "Assigned Branch", custom_next_followup_date: "Next Follow-up",
