  function historyFormatVal(field, v) {
    if (v === null || v === undefined || v === "") return "—";
    if (field === "lead_owner") return friendlyAgentName(v);
    if (field === "status" || field === "custom_cc_stage") return stageLabel ? stageLabel(v) : v;
    return String(v);
  }

  function renderLeadHistoryBody(leadId, versionRows) {
    const body = document.getElementById("cc-lead-history-body"); if (!body) return;
    const l = LEADS.find(function (x) { return x.id === leadId; });

    const events = [];
    versionRows.forEach(function (v) {
      let parsed = null;
      try { parsed = JSON.parse(v.data || "{}"); } catch (e) { parsed = null; }
      if (!parsed) return;
      const changed = parsed.changed || [];
      const relevant = changed.filter(function (c) { return HISTORY_FIELD_LABELS[c[0]]; });
      if (!relevant.length) return;
      events.push({ time: v.creation, by: friendlyAgentName(v.owner) || v.owner, changes: relevant });
    });

    if (!events.length) {
      body.innerHTML =
        '<div style="text-align:center;color:#8C8C8C;padding:20px">' +
        (l ? ('<div style="margin-bottom:8px">No tracked changes yet for <strong>' + escapeHtml(l.name) + "</strong>.</div>") : "") +
        '<div style="font-size:11.5px">Current status: <strong>' + (l ? stageLabel(l.status) : "—") + "</strong> · Owner: <strong>" + (l ? escapeHtml(l.assignedToName || "Unassigned") : "—") + "</strong></div></div>";
      return;
    }

    let stepNum = 0;
    const rows = events.map(function (ev) {
      stepNum++;
      const lines = ev.changes.map(function (c) {
        const field = c[0], from = c[1], to = c[2];
        const label = HISTORY_FIELD_LABELS[field] || field;
        return '<div style="margin-top:2px"><strong>' + label + ":</strong> " + escapeHtml(historyFormatVal(field, from)) + ' <span style="color:#8C8C8C">→</span> <strong style="color:#0F6E56">' + escapeHtml(historyFormatVal(field, to)) + "</strong></div>";
      }).join("");
      return '<div style="display:flex;gap:12px;padding:10px 0;border-bottom:1px solid #eceff4">' +
        '<div style="flex-shrink:0;width:28px;height:28px;border-radius:50%;background:#0D2B4E;color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800">' + stepNum + "</div>" +
        '<div style="flex:1"><div style="font-size:11px;color:#8C8C8C;margin-bottom:2px">' + fmtDate(ev.time.split(" ")[0]) + " " + (ev.time.split(" ")[1] || "").slice(0, 5) + " · by <strong>" + escapeHtml(ev.by) + "</strong></div>" +
        lines + "</div></div>";
    }).join("");

    body.innerHTML =
      (l ? ('<div style="font-size:12px;color:#0D2B4E;font-weight:700;margin-bottom:10px;padding:8px 12px;background:#EEF3FA;border-radius:8px">Current: ' + stageLabel(l.status) + " · " + escapeHtml(l.assignedToName || "Unassigned") + "</div>") : "") +
      '<div style="max-height:440px;overflow:auto">' + rows + "</div>";
  }
