  function renderMyLeads() {
    ensureMyLeadsFilterBar();
    const agentEl = document.getElementById("my-leads-agent");
    if (agentEl) agentEl.textContent = (currentAgent && currentAgent.name) || "";
    const q = ((document.getElementById("cc-ml-search") || {}).value || "").trim().toLowerCase();
    const ownerF = (document.getElementById("cc-ml-owner") || {}).value || "";
    const statusF = (document.getElementById("cc-ml-status") || {}).value || (document.getElementById("lead-filter-status") || {}).value || "";
    const catF = (document.getElementById("lead-filter-cat") || {}).value || "";
    const myLeads = LEADS.filter(l => {
      if (statusF && l.status !== statusF) return false;
      if (catF && !l.categories.some(c => c.includes(catF))) return false;
      if (ownerF && l.assignedTo !== ownerF) return false;
      if (q) {
        const hay = (l.name + " " + l.phone + " " + l.area + " " + l.id + " " + (l.assignedToName || "") + " " + (l.source || "")).toLowerCase();
        if (hay.indexOf(q) === -1) return false;
      }
      return true;
    });
    window.__ccMyLeadsFiltered = myLeads;
    renderMyLeadsPage(1);
  }

