  function leadProgress(l) {
    let pts = 0; const max = 7;
    if (l.source) pts++;
    if (l.name && l.phone) pts++;
    if (l.area || l.branchCode) pts++;
    if (l.categories && l.categories.length) pts++;
    if (l.concern || l.weight || l.height) pts++;
    if (l.status && l.status !== "UNTOUCHED") pts++;
    if (l.nextFollowup || l.apptDate || l.subStatus === "Call & Confirm") pts++;
    return Math.round(pts / max * 100);
  }

