  function renderStatusGrid() {
    const container = document.getElementById("ff-status-area"); if (!container) return;
    const GROUPS = {
      "CONNECTED": { label: "✅ CONNECTED — what did they say?", css: "connected" },
      "NOT_CONNECTED": { label: "📵 NOT CONNECTED — why?", css: "notconnected" }
    };
    container.innerHTML = Object.keys(LEAD_RESPONSES).map(function (key) {
      const grp = GROUPS[key] || { label: key, css: "connected" };
      const subs = LEAD_RESPONSES[key];
      return '<div class="sg-group"><span class="sg-group-label sg-' + grp.css + '">' + grp.label + "</span>" +
        '<div class="status-grid-v2">' +
        subs.map(function (s2) {
          return '<div class="sg-opt" data-status="' + key + '" data-sub="' + escAttr(s2.sub) + '"' +
            ' onclick="selectStatus2(\'' + key + "','" + s2.sub.replace(/'/g, "\\'") + "',this)\"" +
            ' onmouseenter="this.querySelector(\'.sg-tip\').style.display=\'block\'"' +
            ' onmouseleave="this.querySelector(\'.sg-tip\').style.display=\'none\'">' +
            '<div class="sg-sub">' + escapeHtml(s2.sub) + '</div>' +
            '<div class="sg-tip">' + escapeHtml(s2.tip) + "</div></div>";
        }).join("") + "</div></div>";
    }).join("");
  }

  function restoreStatusSelection() {
    const sub = ffSubStatusSelected;
    if (!sub) return;
    const cell = document.querySelector('.sg-opt[data-sub="' + (window.CSS && CSS.escape ? CSS.escape(sub) : sub) + '"]');
    if (cell) selectStatus2(cell.getAttribute("data-status"), sub, cell);
  }

  function selectStatus2(branch, sub, el) {
    document.querySelectorAll(".sg-opt").forEach(o => o.classList.remove("sel-s", "sel-f", "sel-l", "sel-i", "sel-u", "sel-connected", "sel-notconnected"));
    el.classList.add(branch === "NOT_CONNECTED" ? "sel-notconnected" : "sel-connected");

    const stage = SUBSTATUS_TO_STAGE[sub] || "FOLLOW-UP";
    ffStatusSelected = stage;
    ffSubStatusSelected = sub;

    const d = document.getElementById("ff-status-display");
    if (d) d.value = sub + "  ·  " + stageLabel(stage);

    if (sub === "Appointment Booked") {
      const bookTile = document.getElementById("atile-book");
      if (bookTile && typeof selectFollowupAction === "function") {
        selectFollowupAction("book", bookTile);
      }
    } else if (stage === "FOLLOW-UP" && branch !== "NOT_CONNECTED") {
      // v-next: connected callback / follow-up outcomes auto-open the Next
      // Follow-up Date field. Not-connected retries (No Response, Not Reachable,
      // Switch OFF, Call Disconnected, etc.) do NOT prompt for a date.
      const fuTile = document.getElementById("atile-fu");
      if (fuTile && typeof selectFollowupAction === "function") {
        selectFollowupAction("followup", fuTile);
        setTimeout(function () {
          const nd = document.getElementById("ff-next-date");
          if (nd) { try { nd.focus(); } catch (e) {} }
        }, 60);
      }
    }

    updateProgress();
    updateCommunicationTools();
  }

  function toggleFollowupCat2(cat, el) {
    if (followupSelectedCats.has(cat)) { followupSelectedCats.delete(cat); el.classList.remove("sel"); }
    else { followupSelectedCats.add(cat); el.classList.add("sel"); }
    const cb = el.querySelector("input[type=checkbox]"); if (cb) cb.checked = followupSelectedCats.has(cat);
    renderFollowupSubcats();
    renderTreatmentQuestions();
    updateProgress();
  }

  function renderFollowupSubcats() {
    const area = document.getElementById("ff-subcat-area"); if (!area) return;
    if (!followupSelectedCats.size) { area.innerHTML = ""; return; }
    area.innerHTML = Array.from(followupSelectedCats).map(function (cat) {
      const subs = TREATMENT_CATEGORIES[cat] || [];
      if (!subs.length) return "";
      return '<div style="margin-bottom:10px"><div style="font-size:10.5px;font-weight:800;color:#0D2B4E;margin-bottom:6px">' + cat + " - specific interest</div>" +
        '<div style="display:flex;flex-wrap:wrap;gap:6px">' + subs.map(function (s) {
          const sel = (currentFollowUpLead && currentFollowUpLead.subInterests && currentFollowUpLead.subInterests.indexOf(s) > -1);
          return '<label class="sub-chip' + (sel ? " sel" : "") + '"><input type="checkbox" class="ff-subcat-cb"' + (sel ? " checked" : "") + ' value="' + s.replace(/"/g, "&quot;") + '" data-cat="' + cat + '"> ' + s + "</label>";
        }).join("") + "</div></div>";
    }).join("");
  }

  function renderTreatmentQuestions() {
    const area = document.getElementById("ff-treatment-questions"); if (!area) return;
    const cats = Array.from(followupSelectedCats);
    if (!cats.length) { area.innerHTML = ""; return; }
    let html = '<div class="ff-sec" id="ffsec-4"><div class="ff-sec-hdr"><span class="sec-num">4</span> Treatment Assessment</div><div class="ff-sec-body">';
    cats.forEach(function (cat) {
      if (cat === "Slimming" || cat === "Life Rise") html += buildSlimmingSection();
      else if (cat === "Hair") html += buildHairSection();
      else if (cat === "HT (Hair Transplant)") html += buildHTSection();
      else if (cat === "Skin / Dermat" || cat === "Laser" || cat === "Aesthetics") html += buildSkinSection(cat);
    });
    html += renderMedicalSection(cats);
    html += "</div></div>";
    area.innerHTML = html;
    const l = currentFollowUpLead;
    if (l) {
      const wt = document.getElementById("ff-weight"); if (wt && l.weight) wt.value = l.weight;
      const ht = document.getElementById("ff-height-cm"); if (ht && l.heightCm) ht.value = l.heightCm;
      const tw = document.getElementById("ff-target-wt"); if (tw && l.targetWeight) tw.value = l.targetWeight;
      const md = document.getElementById("ff-medication"); if (md && l.medication) md.value = l.medication;
      const pa = document.getElementById("ff-prev-attempts"); if (pa && l.prevAttempts) pa.value = l.prevAttempts;
      if (l.weight && l.heightCm) calcBMI2();
    }
  }

