  function onHeightCmChange() {
    const cm = parseFloat((document.getElementById("ff-height-cm") || {}).value); const ftEl = document.getElementById("ff-height-ft");
    if (cm && ftEl) { const totalIn = cm / 2.54; const ft = Math.floor(totalIn / 12); const inch = Math.round(totalIn % 12); ftEl.value = ft + "." + inch; }
  }
  function onHeightFtChange() {
    const raw = (document.getElementById("ff-height-ft") || {}).value || ""; const cmEl = document.getElementById("ff-height-cm");
    const parts = String(raw).split("."); const ft = parseInt(parts[0]) || 0; const inch = parseInt(parts[1]) || 0;
    if (ft && cmEl) { cmEl.value = Math.round((ft * 12 + inch) * 2.54); calcBMI2(); }
  }
  function calcBMI2() {
    const w = parseFloat((document.getElementById("ff-weight") || {}).value); const h = parseFloat((document.getElementById("ff-height-cm") || {}).value);
    const out = document.getElementById("ff-bmi"); const ind = document.getElementById("ff-bmi-indicator");
    if (!w || !h || !out) { if (out) out.value = ""; if (ind) ind.innerHTML = ""; return; }
    const bmi = w / Math.pow(h / 100, 2); const val = bmi.toFixed(1); out.value = val;
    let cat = "", col = "";
    if (bmi < 18.5) { cat = "Underweight"; col = "#B26A00"; }
    else if (bmi < 25) { cat = "Normal"; col = "#0F6E56"; }
    else if (bmi < 30) { cat = "Overweight"; col = "#B26A00"; }
    else { cat = "Obese"; col = "#A32D2D"; }
    if (ind) ind.innerHTML = '<span style="font-size:11.5px;font-weight:700;color:' + col + '">BMI ' + val + " - " + cat + "</span>";
  }
  function displayBMI2() { calcBMI2(); }

