    if(!ccCheckFollowupPhone())return;
    if(!octValidate()||!wfValidate())return;
    collectFollowupData(l);
    wfCollect(l);
    if (!l.conclusionRemark) { toast("Please select a Conclusion Remark", "red"); return; }
    // FSM: Treatment Interest mandatory except when closing as LOST / INVALID.
    if (!followupSelectedCats.size && ["LOST","INVALID"].indexOf(l.status) < 0) {
      toast("Select at least one Treatment Interest (Section 3)", "red");
      const sec = document.getElementById("ffsec-3");
      if (sec && sec.scrollIntoView) { try { sec.scrollIntoView({ behavior: "smooth", block: "center" }); } catch (e) { sec.scrollIntoView(); } }
      return;
    }
    // v-next: pipeline action requires a date + time.
    if (ffActionSelected === "pipeline") {
      const pd = (document.getElementById("ff-pipeline-date") || {}).value || "";
      const pt = (document.getElementById("ff-pipeline-time") || {}).value || "";
      if (!pd || !pt) { toast("Pick the pipeline date and time", "red"); return; }
    }
    if (ffActionSelected === "followup" && !l.nextFollowup) { toast("FOLLOW-UP needs a next date", "red"); return; }
    if (ffActionSelected === "stop") { const e = document.getElementById("ff-stop-reason"); if (e && !e.value) { toast("Select a reason for stopping", "red"); return; } }
    showLoader("Saving to portal…");
    syncLeadToPortal(l).then(function () {
      const idx = LEADS.findIndex(function (x) { return x.id === l.id; });
      if (idx > -1) LEADS[idx] = l;
      renderMyLeads();
      updateNavBadges();
      hideLoader();
      toast("✅ Lead update saved successfully", "green");
    }, function (error) {
      hideLoader();
      toast("❌ Could not save lead update: " + ((error && (error.message || error._server_messages)) || "Please try again"), "red");
    });
  }

  function saveAndOpenBooking() {
    const l = currentFollowUpLead; if (!l) { toast("No lead open", "red"); return; }
    if(!ccCheckFollowupPhone()||!octValidate()||!wfValidate())return;
    collectFollowupData(l);
    wfCollect(l);
    if (!l.conclusionRemark) l.conclusionRemark = "Consultation appointment requested";
    // v-next: a booked lead is a genuine engaged lead → treatment interest required.
    if (!followupSelectedCats.size) {
      toast("Select at least one Treatment Interest (Section 3) before booking", "red");
      const sec = document.getElementById("ffsec-3");
      if (sec && sec.scrollIntoView) { try { sec.scrollIntoView({ behavior: "smooth", block: "center" }); } catch (e) { sec.scrollIntoView(); } }
      return;
    }

    if (window.__ccBooking) return;
    window.__ccBooking = true;
    showLoader("Saving follow-up…");
    syncLeadToPortal(l).then(function () {
      hideLoader(); window.__ccBooking = false;
      toast("✅ Follow-up saved. Opening appointment booking…", "green");
      openAppointmentFromLead(l.id);
    }, function (error) {
      hideLoader(); window.__ccBooking = false;
      toast("❌ Could not save follow-up: " + ((error && (error.message || error._server_messages)) || "Please try again"), "red");
    });
  }

  function openAppointmentFromLead(id) {
    const path = '/life_portal/cc-appointments' + (id ? '?lead=' + encodeURIComponent(id) : '');
    if (window.parent !== window) {
      window.parent.postMessage({type:'life-portal:navigate',path}, window.location.origin);
