  function openTileList(kind) {
    let list = [], title = "";
    // v-next: drill-down for a matrix cell → row dimension + sub-status.
    // Encoded as "matrixcell:<dim>|<rowval>|<substatus>" where dim = source|agent.
    if (typeof kind === "string" && kind.indexOf("matrixcell:") === 0) {
      const parts = kind.slice("matrixcell:".length).split("|");
      const dim = parts[0], rowval = parts[1] || "", sv = parts[2] || "";
      list = LEADS.filter(function (l) {
        const rk = (dim === "agent") ? (l.assignedTo || "(unassigned)")
          : (dim === "branch") ? (l.branchSuggested || l.branchChosen || l.branchCode || "(no branch)")
          : (l.source || "(no source)");
        const ss = l.subStatus || "(none)";
        return rk === rowval && ss === sv;
      });
      const rowLabel = (dim === "agent") ? (friendlyAgentName(rowval) || rowval) : rowval;
      title = rowLabel + " · " + sv;
      const rowsM = list.length ? list.map(function (l) {
        const apptLine = apptStatusPill(l.apptStatus || "Pending") + followUpPill(l) + pipelinePill(l) +
          (l.apptDate ? '<span style="font-size:10.5px;color:#5F6F63;margin-left:6px">📅 ' + escapeHtml(l.apptDate) + (l.apptTime ? " " + escapeHtml(l.apptTime) : "") + "</span>" : "");
        return '<div class="queue-item"><div><div class="qi-name">' + l.name + '</div><div class="qi-sub">' + maskSpan(l.phone) + " | " + l.area + " | " + stageLabel(l.status) + '</div><div class="qi-sub" style="color:#0D2B4E;font-weight:600">👤 ' + (l.assignedToName || "Unassigned") + '</div><div class="qi-tags" style="margin-top:4px">' + apptLine + "</div></div>" +
          '<button class="btn btn-n btn-sm" onclick="closeModal();openLeadFollowup(\'' + l.id + '\')">Open</button></div>';
      }).join("") : '<div style="padding:16px;color:#8C8C8C;text-align:center">No leads in this category.</div>';
      openModal(title + " (" + list.length + ")", rowsM, true);
      return;
    }
    // v-next: drill-down by exact sub-status value, e.g. "substatus:Not Reachable"
    if (typeof kind === "string" && kind.indexOf("substatus:") === 0) {
      const sv = kind.slice("substatus:".length);
      list = LEADS.filter(function (l) { return (l.subStatus || "(none)") === sv; });
      title = "Sub-Status: " + sv;
      const rowsS = list.length ? list.map(function (l) {
        const apptLine = apptStatusPill(l.apptStatus || "Pending") + followUpPill(l) + pipelinePill(l) +
          (l.apptDate ? '<span style="font-size:10.5px;color:#5F6F63;margin-left:6px">📅 ' + escapeHtml(l.apptDate) + (l.apptTime ? " " + escapeHtml(l.apptTime) : "") + "</span>" : "");
        return '<div class="queue-item"><div><div class="qi-name">' + l.name + '</div><div class="qi-sub">' + maskSpan(l.phone) + " | " + l.area + " | " + stageLabel(l.status) + '</div><div class="qi-sub" style="color:#0D2B4E;font-weight:600">👤 ' + (l.assignedToName || "Unassigned") + '</div><div class="qi-tags" style="margin-top:4px">' + apptLine + "</div></div>" +
          '<button class="btn btn-n btn-sm" onclick="closeModal();openLeadFollowup(\'' + l.id + '\')">Open</button></div>';
      }).join("") : '<div style="padding:16px;color:#8C8C8C;text-align:center">No leads in this category.</div>';
      openModal(title + " (" + list.length + ")", rowsS, true);
      return;
    }
    // v-next: created-in-range leads only (drop merged follow-up-due leads) for
    // the created-based tiles; the "followup" tile stays inclusive of all.
    const CL = LEADS.filter(function (l) { return !l.__fuOnly; });
    if (kind === "assigned") { list = CL; title = "All Assigned Leads"; }
    else if (kind === "untouched") { list = CL.filter(function (l) { return l.status === "UNTOUCHED"; }); title = "Untouched Leads"; }
    else if (kind === "followup") { list = LEADS.filter(function (l) { return l.status === "FOLLOW-UP"; }); title = "Follow-Up Due"; }
    else if (kind === "appts") {
      list = APPOINTMENTS.map(function (a) {
        return LEADS.find(function (l) { return l.id === a.leadId; }) ||
          (window.__ccApptLeads && window.__ccApptLeads[a.leadId]);
      }).filter(Boolean);
      title = "Appointments Booked";
    }
    else if (kind === "success") { list = CL.filter(function (l) { return l.status === "SUCCESS"; }); title = "Successful Conversions"; }
    // else if (kind === "converted") {
    //   list = LEADS.filter(function (l) { return l.portalStatus === "Converted" || l.apptStatus === "Visited Booked"; });
    //   title = "Converted (visited & booked)";
    // }
    else if (kind === "converted") {
      list = CL.filter(function (l) { return l.portalStatus === "Converted" || l.apptStatus === "Visited Booked"; });
      title = "Converted (visited & booked)";
    }
    else if (kind === "norespnotreach") {
      list = CL.filter(function (l) { return l.subStatus === "No Response" || l.subStatus === "Not Reachable"; });
      title = "No Response / Not Reachable";
    }
    else if (kind === "invalid") {
      list = CL.filter(function (l) { return l.subStatus === "Invalid Number"; });
      title = "Invalid";
    }
    else if (kind === "nid") {
      list = CL.filter(function (l) { return l.subStatus === "NID"; });
      title = "NID";
    }
    else if (kind === "apptsame") {
      const t = fmtISO(TODAY);
      list = CL.filter(function (l) { return l.apptDate === t && leadCreatedDateISO(l) === t; });
      title = "Appointments — Created & Appt Today";
    }
    else if (kind === "apptdiff") {
      const t = fmtISO(TODAY);
      list = CL.filter(function (l) { return l.apptDate === t && leadCreatedDateISO(l) !== t; });
      title = "Appointments — Older Lead, Appt Today";
    }
    else if (kind === "convsame") {
      const t = fmtISO(TODAY);
      list = CL.filter(function (l) {
        return (l.portalStatus === "Converted" || l.apptStatus === "Visited Booked") && l.apptDate === t && leadCreatedDateISO(l) === t;
      });
      title = "Converted — Created & Appt Today";
    }
    else if (kind === "convdiff") {
      const t = fmtISO(TODAY);
      list = CL.filter(function (l) {
        return (l.portalStatus === "Converted" || l.apptStatus === "Visited Booked") && l.apptDate === t && leadCreatedDateISO(l) !== t;
      });
      title = "Converted — Older Lead, Appt Today";
    }
    const rows = list.length ? list.map(function (l) {
      // v-next: show the lead's live appointment status (custom_appointment_status)
      // on every row, plus appt date/time when present.
      const apptLine = apptStatusPill(l.apptStatus || "Pending") + followUpPill(l) + pipelinePill(l) +
        (l.apptDate ? '<span style="font-size:10.5px;color:#5F6F63;margin-left:6px">📅 ' + escapeHtml(l.apptDate) + (l.apptTime ? " " + escapeHtml(l.apptTime) : "") + "</span>" : "");
      return '<div class="queue-item"><div><div class="qi-name">' + l.name + '</div><div class="qi-sub">' + maskSpan(l.phone) + " | " + l.area + " | " + stageLabel(l.status) + '</div><div class="qi-sub" style="color:#0D2B4E;font-weight:600">👤 ' + (l.assignedToName || "Unassigned") + '</div><div class="qi-tags" style="margin-top:4px">' + apptLine + "</div></div>" +
        '<button class="btn btn-n btn-sm" onclick="closeModal();openLeadFollowup(\'' + l.id + '\')">Open</button></div>';
    }).join("") : '<div style="padding:16px;color:#8C8C8C;text-align:center">No leads in this category.</div>';
    openModal(title + " (" + list.length + ")", rows, true);
  }

  window.__ccWsRows = window.__ccWsRows || [];
  window.__ccWsDirty = window.__ccWsDirty || {};
  const WS_OWNER_COL = { key: "owner", label: "Agent", w: "12%", type: "text" };
  const WS_COLS = [
    { key: "posting_date", label: "Posting Date", w: "12%", type: "date" },
    { key: "client_name", label: "Client Name", w: "18%", type: "text" },
    { key: "mobile", label: "Mobile", w: "13%", type: "text" },
    { key: "area", label: "Area", w: "13%", type: "text" },
    { key: "enquired_for", label: "Enquired For", w: "16%", type: "text" },
    { key: "status", label: "Status", w: "12%", type: "text" },
    { key: "followup_date", label: "Follow-up", w: "11%", type: "date" },
    { key: "notes", label: "Notes", w: "13%", type: "text" }
  ];

  // ── Worksheet date filter (default: This Week, Mon–Sun) ──────────────
  // Which column the range applies to: "posting_date" or "followup_date".
  var WS_FILTER = { field: "posting_date", from: "", to: "", preset: "this_week" };

  // Monday-based start of the ISO week containing date d.
  function wsWeekStart(d) {
    var x = new Date(d);
    var day = x.getDay();               // 0=Sun … 6=Sat
    var diff = (day === 0 ? -6 : 1 - day); // shift back to Monday
    x.setDate(x.getDate() + diff);
    return x;
  }
  function wsWeekEnd(d) {
    var s = wsWeekStart(d);
    var e = new Date(s);
    e.setDate(s.getDate() + 6);
    return e;
  }
  function wsApplyPreset(preset) {
    WS_FILTER.preset = preset;
    if (preset === "this_week") {
      WS_FILTER.from = fmtISO(wsWeekStart(TODAY));
      WS_FILTER.to = fmtISO(wsWeekEnd(TODAY));
    } else if (preset === "last_week") {
      var lw = new Date(TODAY); lw.setDate(lw.getDate() - 7);
      WS_FILTER.from = fmtISO(wsWeekStart(lw));
      WS_FILTER.to = fmtISO(wsWeekEnd(lw));
    } else if (preset === "today") {
      WS_FILTER.from = fmtISO(TODAY);
      WS_FILTER.to = fmtISO(TODAY);
    } else if (preset === "all") {
      WS_FILTER.from = "";
      WS_FILTER.to = "";
    }
  }
  // Seed the default range on first load.
  wsApplyPreset("this_week");

  // A worksheet row passes the filter when its chosen date column falls in range.
  function wsRowInRange(r) {
    if (!WS_FILTER.from && !WS_FILTER.to) return true;   // "All"
    var v = (r[WS_FILTER.field] || "").slice(0, 10);
    if (!v) return false;                                // no date on that column → excluded
    if (WS_FILTER.from && v < WS_FILTER.from) return false;
    if (WS_FILTER.to && v > WS_FILTER.to) return false;
    return true;
  }

  function renderWorksheet() {
    const root = document.getElementById("worksheet-root"); if (!root) return;
    root.innerHTML =
      '<div class="card"><div class="card-hdr">📊 My Worksheet' +
      '<div style="display:flex;gap:8px;align-items:center;margin-left:auto;flex-wrap:wrap">' +
      '<input id="cc-ws-search" placeholder="🔍 Search…" style="height:30px;padding:0 10px;border:1px solid #C9D4E3;border-radius:8px;font-size:12px;width:180px">' +
      '<button class="btn btn-gy btn-sm" id="cc-ws-add">➕ Add Row</button>' +
      '<button class="btn btn-n btn-sm" id="cc-ws-save">💾 Save</button>' +
      '<button class="btn btn-gy btn-sm" id="cc-ws-export">⬇️ Export CSV</button>' +
      "</div></div>" +
      '<div class="card-body">' +
      // ── Date filter bar (defaults to This Week) ──
      '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px;padding:8px 10px;background:#F4F7FB;border:1px solid #E2E8F0;border-radius:8px">' +
        '<span style="font-size:11px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;color:#5B6B84">📅 Filter</span>' +
        '<select id="cc-ws-field" style="height:30px;border:1px solid #C9D4E3;border-radius:8px;font-size:12px;padding:0 8px">' +
          '<option value="posting_date"' + (WS_FILTER.field === "posting_date" ? " selected" : "") + '>Posting Date</option>' +
          '<option value="followup_date"' + (WS_FILTER.field === "followup_date" ? " selected" : "") + '>Follow-up</option>' +
        '</select>' +
        '<input type="date" id="cc-ws-from" value="' + escAttr(WS_FILTER.from) + '" style="height:30px;border:1px solid #C9D4E3;border-radius:8px;font-size:12px;padding:0 8px">' +
        '<span style="font-size:11px;color:#8C8C8C">to</span>' +
        '<input type="date" id="cc-ws-to" value="' + escAttr(WS_FILTER.to) + '" style="height:30px;border:1px solid #C9D4E3;border-radius:8px;font-size:12px;padding:0 8px">' +
        '<button class="btn btn-gy btn-sm" data-ws-preset="this_week">This Week</button>' +
        '<button class="btn btn-gy btn-sm" data-ws-preset="last_week">Last Week</button>' +
        '<button class="btn btn-gy btn-sm" data-ws-preset="today">Today</button>' +
        '<button class="btn btn-gy btn-sm" data-ws-preset="all">All</button>' +
        '<span id="cc-ws-filtnote" style="font-size:11px;color:#5B6B84;margin-left:auto"></span>' +
      '</div>' +
      '<div style="font-size:11.5px;color:#8C8C8C;margin-bottom:8px">Click any cell to edit, then Save. ' +
      '<span id="cc-ws-masknote"></span></div>' +
      '<div id="cc-ws-table"><div style="text-align:center;color:#8C8C8C;padding:24px">Loading…</div></div>' +
      "</div></div>";

    document.getElementById("cc-ws-add").addEventListener("click", wsAddRow);
    document.getElementById("cc-ws-save").addEventListener("click", wsSave);
    document.getElementById("cc-ws-export").addEventListener("click", wsExportCsv);
    const sr = document.getElementById("cc-ws-search");
    if (sr) sr.addEventListener("input", function () { wsRenderTable(); });

    // ── Filter bar wiring ──
    var fField = document.getElementById("cc-ws-field");
    var fFrom = document.getElementById("cc-ws-from");
    var fTo = document.getElementById("cc-ws-to");
    if (fField) fField.addEventListener("change", function () { WS_FILTER.field = fField.value; wsRenderTable(); });
    if (fFrom) fFrom.addEventListener("change", function () { WS_FILTER.from = fFrom.value; WS_FILTER.preset = "custom"; wsRenderTable(); });
    if (fTo) fTo.addEventListener("change", function () { WS_FILTER.to = fTo.value; WS_FILTER.preset = "custom"; wsRenderTable(); });
    Array.prototype.forEach.call(root.querySelectorAll("[data-ws-preset]"), function (b) {
      b.addEventListener("click", function () {
        wsApplyPreset(b.getAttribute("data-ws-preset"));
        if (fFrom) fFrom.value = WS_FILTER.from;
        if (fTo) fTo.value = WS_FILTER.to;
        wsRenderTable();
      });
    });

    wsLoad();
  }

  function wsLoad() {
    frappe.call({ method: "cc_worksheet", args: { action: "list" } }).then(function (r) {
      const m = (r && r.message) || {};
      window.__ccWsRows = m.rows || [];
      window.__ccWsDirty = {};
      window.__ccWsManager = !!m.manager_view;
      window.__ccWsMe = m.me || "";
      const note = document.getElementById("cc-ws-masknote");
      if (note) note.innerHTML = window.__ccWsManager
        ? '👥 Manager view — showing every agent\'s worksheet rows. 🔒 Mobiles masked on screen; hover to reveal.'
        : '🔒 Mobile numbers show masked — hover or tap to reveal.';
      wsRenderTable();
    }, function (e) {
      const t = document.getElementById("cc-ws-table");
      if (t) t.innerHTML = '<div style="color:#A32D2D;padding:16px">Could not load worksheet: ' + escapeHtml((e && e.message) || "") + "<br><span style='font-size:11px'>If this says the doctype is missing, the backend setup script hasn't been run yet.</span></div>";
    });
  }

  function wsAddRow() {
    window.__ccWsRows.push({
      name: "", client_name: "", mobile: "", area: "", enquired_for: "",
      status: "", posting_date: fmtISO(TODAY), followup_date: "", notes: "", row_order: window.__ccWsRows.length
    });
    wsRenderTable();
  }

  function wsRenderTable() {
    const wrap = document.getElementById("cc-ws-table"); if (!wrap) return;
    const q = ((document.getElementById("cc-ws-search") || {}).value || "").trim().toLowerCase();
    let rows = window.__ccWsRows;
    // date-range filter (defaults to This Week on the selected date column)
    rows = rows.filter(wsRowInRange);
    if (q) rows = rows.filter(function (r) {
      return WS_COLS.map(function (c) { return r[c.key] || ""; }).join(" ").toLowerCase().indexOf(q) > -1;
    });
    // reflect the active range next to the filter bar
    var fn = document.getElementById("cc-ws-filtnote");
    if (fn) {
      var fieldLbl = WS_FILTER.field === "followup_date" ? "Follow-up" : "Posting Date";
      fn.textContent = (WS_FILTER.from || WS_FILTER.to)
        ? (fieldLbl + ": " + (WS_FILTER.from || "…") + " → " + (WS_FILTER.to || "…") + " · " + rows.length + " row(s)")
        : ("All dates · " + rows.length + " row(s)");
    }

    if (!rows.length) {
      wrap.innerHTML = '<div style="text-align:center;color:#8C8C8C;padding:24px">' +
        (q ? "No rows match that search." : "No rows yet — click <b>Add Row</b> to start.") + "</div>";
      return;
    }

    const cols = window.__ccWsManager ? [WS_OWNER_COL].concat(WS_COLS) : WS_COLS;
    const head = cols.map(function (c) {
      return '<th style="width:' + c.w + '">' + c.label + (c.key === "mobile" ? " 🔒" : "") + "</th>";
    }).join("") + '<th style="width:40px"></th>';

    const body = rows.map(function (r) {
      const idx = window.__ccWsRows.indexOf(r);
      const cells = cols.map(function (c) {
        if (c.key === "owner") {
          const short = String(r.owner || "").split("@")[0];
          return '<td style="padding:2px 8px;font-size:11px;color:#5F6F63" title="' + escAttr(r.owner || "") + '">' + escapeHtml(short) + "</td>";
        }
        const v = r[c.key] == null ? "" : String(r[c.key]);
        if (c.key === "mobile") {
          const shown = v ? maskPhone(v) : "";
          return '<td style="padding:2px">' +
            '<input class="ws-mobile" data-ws-idx="' + idx + '" data-ws-key="mobile"' +
            ' data-ws-real="' + escAttr(v) + '" title="Hover or tap to reveal"' +
            ' value="' + escAttr(shown) + '" style="width:100%;height:28px;border:1px solid transparent;' +
            'border-radius:4px;padding:0 6px;font-size:12px;background:transparent;' +
            'border-bottom:1px dotted #5F6F63"></td>';
        }
        return '<td style="padding:2px">' +
          '<input data-ws-idx="' + idx + '" data-ws-key="' + c.key + '"' +
          (c.type === "date" ? ' type="date"' : "") +
