    const esc = function (v) { return '"' + String(v == null ? "" : v).replace(/"/g, '""') + '"'; };
    const csvCols = window.__ccWsManager ? [WS_OWNER_COL].concat(WS_COLS) : WS_COLS;
    const lines = [csvCols.map(function (c) { return esc(c.label); }).join(",")];
    rows.forEach(function (r) {
      lines.push(csvCols.map(function (c) { return esc(r[c.key]); }).join(","));
    });
    const blob = new Blob([lines.join("\n")], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = __realdoc.createElement("a");
