  // v-next: today's check-in / check-out for the logged-in user, shown in the
  // header. Path: session.user → Employee (user_id) → Attendance (employee +
  // attendance_date = today). Prefers custom_check_in/out_time, falls back to
  // the standard in_time / out_time.
  function loadMyAttendance() {
    const me = (frappe.session && frappe.session.user) || "";
    if (!me || me === "Guest") return;
    const today = fmtISO(TODAY);
    const setTxt = function (id, v) { const el = R.querySelector("#" + id); if (el) el.textContent = v; };
    portalGetList("Employee", {
      fields: ["name"], filters: [["user_id", "=", me]], limit_page_length: 1
    }).catch(function () { return []; }).then(function (emps) {
      if (!emps || !emps.length) { setTxt("att-in-time", "—"); setTxt("att-out-time", "—"); return; }
      const empId = emps[0].name;
      return portalGetList("Attendance", {
        fields: ["custom_check_in_time", "custom_check_out_time", "in_time", "out_time"],
        filters: [["employee", "=", empId], ["attendance_date", "=", today]],
        order_by: "modified desc", limit_page_length: 1
      }).catch(function () { return []; }).then(function (rows) {
        if (!rows || !rows.length) { setTxt("att-in-time", "—"); setTxt("att-out-time", "—"); return; }
        const a = rows[0];
        const timeOnly = function (dt) { const p = String(dt || "").split(" ")[1] || ""; return p.substring(0, 5); };
        const inDt = a.custom_check_in_time || a.in_time || "";
        const outDt = a.custom_check_out_time || a.out_time || "";
        setTxt("att-in-time", inDt ? timeOnly(inDt) : "—");
        setTxt("att-out-time", outDt ? timeOnly(outDt) : "—");
      });
    });
  }

