  function renderApptReport() {
    const host = document.getElementById("appt-report-root"); if (!host) return;
    const src = [];
    LEADS.forEach(function (l) { if (l.apptDate) src.push(l); });
    Object.keys(window.__ccApptLeads || {}).forEach(function (k) {
      const l = window.__ccApptLeads[k];
      if (l && l.apptDate && !src.some(function (x) { return x.id === l.id; })) src.push(l);
