    const agents = {};
    src.forEach(function (l) {
      const key = l.assignedTo || "(unassigned)";
      if (!agents[key]) agents[key] = { name: friendlyAgentName(key) || key, booked: 0, vb: 0, vnb: 0, nv: 0, cancelled: 0, pending: 0, converted: 0, branches: {} };
      const a = agents[key];
      a.booked++;
      const st = l.apptStatus || "";
      if (st === "Visited Booked") a.vb++;
      else if (st === "Visited Not Booked") a.vnb++;
      else if (st === "Not Visited") a.nv++;
      else if (st === "Cancelled") a.cancelled++;
      else a.pending++;
      if (l.portalStatus === "Converted" || st === "Visited Booked") a.converted++;
      const br = l.apptBranch || l.branchSuggested || "";
      if (br) a.branches[br] = (a.branches[br] || 0) + 1;
