      host.innerHTML =
        '<div class="card"><div class="card-hdr">📅 Appointments Report <span class="badge">' + src.length + ' appts in range</span></div>' +
        '<div class="card-body"><div class="tbl-wrap"><table><thead><tr>' +
        "<th>Agent</th><th>Appointments Booked</th><th>Visited Booked</th><th>Visited Not Booked</th><th>Total Visited</th><th>Not Visited</th><th>Pending</th><th>Converted</th><th>Conversion %</th><th>Billed</th><th>Paid</th><th>Preferred Branch</th>" +
        "</tr></thead><tbody>" +
        (rows.length ? rows.map(function (a) {
          return "<tr><td><strong>" + escapeHtml(a.name) + "</strong></td>" +
            '<td>' + a.booked + "</td>" +
            '<td style="color:#2E7D32;font-weight:700">' + a.vb + "</td>" +
            '<td style="color:#E65100;font-weight:700">' + a.vnb + "</td>" +
            '<td style="color:#1565C0;font-weight:800">' + (a.vb + a.vnb) + "</td>" +
            '<td style="color:#C62828;font-weight:700">' + a.nv + "</td>" +
            '<td style="color:#5F6F63">' + a.pending + "</td>" +
            '<td style="font-weight:800">' + a.converted + "</td>" +
            '<td><span class="pill ' + (a.convRate >= 50 ? "p-green" : a.convRate >= 25 ? "p-gold" : "p-red") + '">' + a.convRate + "%</span></td>" +
            salesCell(a.key) +
            "<td>" + escapeHtml(a.prefBranch) + "</td></tr>";
        }).join("") : '<tr><td colspan="12" style="text-align:center;color:#5F6F63;padding:18px">No appointments in the selected range</td></tr>') +
        (rows.length ? '<tr style="font-weight:800;background:#E8F5E9"><td>TOTAL</td><td>' + tot.booked + "</td><td>" + tot.vb + "</td><td>" + tot.vnb + '</td><td style="color:#1565C0">' + (tot.vb + tot.vnb) + "</td><td>" + tot.nv + "</td><td>" +
          (tot.booked - tot.vb - tot.vnb - tot.nv) + "</td><td>" + tot.converted + '</td><td>' + (tot.booked ? Math.round(tot.converted * 100 / tot.booked) : 0) + "%</td>" +
          (salesReady ? '<td style="color:#0F6E56">' + fmtINR(tBilled) + '</td><td style="color:#5b3fb0">' + fmtINR(tPaid) + "</td>" : '<td>…</td><td>…</td>') +
          "<td>—</td></tr>" : "") +
        "</tbody></table></div>" +
        '<div style="font-size:11px;color:#5F6F63;margin-top:8px">Converted = portal status "Converted" or appointment marked Visited Booked by the branch. Billed / Paid come from the CC Invoice Report, rolled up to each lead\'s agent. Range follows the dashboard date filter.</div>' +
        "</div></div>";
    }

    // store each agent's key for the sales cell lookup
    Object.keys(agents).forEach(function (k) { agents[k].key = k; });

    buildTable(null, false);
    if (typeof loadCcInvoiceRows === "function") {
      loadCcInvoiceRows().then(function (invRows) {
