/* LIFE LEAD ASSIGNMENT CONFIG UI V1 */
(function () {
  "use strict";

  window.__laConfigData = null;
  window.__laPreviewData = null;

  function laEsc(value) {
    return String(value == null ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function laAlert(message, indicator) {
    if (
      window.frappe &&
      frappe.show_alert
    ) {
      frappe.show_alert({
        message: message,
        indicator: indicator || "blue"
      });
    } else {
      alert(message);
    }
  }

  function laTime(value) {
    if (!value) return "—";

    var text = String(value);
    var parts = text.split(" ");
    var time = parts.length > 1
      ? parts[1]
      : parts[0];

    var segments = time.split(":");

    if (segments.length < 2) {
      return text;
    }

    var hour = parseInt(
      segments[0],
      10
    );

    var minute = segments[1];
    var suffix = hour >= 12 ? "pm" : "am";

    hour = hour % 12;

    if (hour === 0) {
      hour = 12;
    }

    return hour + ":" + minute + " " + suffix;
  }

  function laSelectedSources(
    sourceOptions,
    selectedSources
  ) {
    var selected = {};

    (selectedSources || []).forEach(
      function (source) {
        selected[String(source)] = true;
      }
    );

    return (sourceOptions || []).map(
      function (source) {
        return (
          '<option value="' +
          laEsc(source) +
          '"' +
          (
            selected[source]
              ? " selected"
              : ""
          ) +
          ">" +
          laEsc(source) +
          "</option>"
        );
      }
    ).join("");
  }

  function laPerformance(agent) {
    var preview =
      window.__laPreviewData || {};

    var agents = preview.agents || [];

    for (
      var i = 0;
      i < agents.length;
      i++
    ) {
      if (
        agents[i].agent === agent
      ) {
        return agents[i];
      }
    }

    return null;
  }

  function laRender() {
    var area = document.getElementById(
      "lead-assignment-config-area"
    );

    if (!area) return;

    var data =
      window.__laConfigData || {};

    var agents = data.agents || [];
    var settings = data.settings || {};
    var sourceOptions =
      data.source_options || [];

    var enabledCount = agents.filter(
      function (row) {
        return Number(
          row.auto_enabled
        ) === 1;
      }
    ).length;

    var checkedInCount = agents.filter(
      function (row) {
        return !!row.checked_in;
      }
    ).length;

    var stoppedCount = agents.filter(
      function (row) {
        return Number(
          row.temporarily_stopped
        ) === 1;
      }
    ).length;

    var html = "";

    html +=
      '<div class="la-card">' +
        '<div class="la-card-header">' +
          '<div>' +
            '<div class="la-title">⚙️ Automatic Lead Assignment</div>' +
            '<div class="la-subtitle">Configure source, daily limit, conversion weighting and Start/Stop for each agent.</div>' +
          '</div>' +
          '<button class="btn btn-sm btn-primary" onclick="leadAssignLoadConfig()">↻ Refresh</button>' +
        '</div>';

    html +=
      '<div class="la-summary-grid">' +
        '<div class="la-summary la-blue">' +
          '<span>Configured Agents</span>' +
          '<strong>' +
            agents.length +
          '</strong>' +
        '</div>' +
        '<div class="la-summary la-green">' +
          '<span>Checked In Now</span>' +
          '<strong>' +
            checkedInCount +
          '</strong>' +
        '</div>' +
        '<div class="la-summary la-gold">' +
          '<span>Auto Enabled</span>' +
          '<strong>' +
            enabledCount +
          '</strong>' +
        '</div>' +
        '<div class="la-summary la-red">' +
