    function () {
      var area =
        document.getElementById(
          "lead-assignment-config-area"
        );

      if (!area) return;

      area.innerHTML =
        '<div class="la-loading">Loading configuration and performance...</div>';

      Promise.all([
        frappe.call({
          method:
            "lead_assignment_configuration",
          args: {
            action: "get"
          }
        }),
        frappe.call({
          method:
            "lead_assignment_preview",
          args: {
            source: "META CHAT LEAD"
          }
        })
      ]).then(function (responses) {
        window.__laConfigData =
          responses[0].message || {};

        window.__laPreviewData =
          responses[1].message || {};

        laRender();
      }).catch(function (error) {
        console.error(
          "Lead assignment configuration load failed",
          error
        );

        area.innerHTML =
          '<div class="la-error">Unable to load assignment configuration. Check browser console.</div>';
      });
    };

  window.leadAssignSaveAgent =
    function (index) {
      var data =
        window.__laConfigData || {};

      var agents = data.agents || [];
      var row = agents[index];

      if (!row) {
        laAlert(
          "Agent configuration not found",
          "red"
        );
        return;
      }

      var sourceSelect =
        document.getElementById(
          "la-sources-" + index
        );

      var selectedSources = [];

      if (sourceSelect) {
        Array.prototype.forEach.call(
          sourceSelect.options,
          function (option) {
            if (option.selected) {
              selectedSources.push(
                option.value
              );
            }
          }
        );
      }

      var enabled = document.getElementById(
        "la-enabled-" + index
      ).checked ? 1 : 0;

      var stopped = document.getElementById(
        "la-stopped-" + index
      ).checked ? 1 : 0;

      var useConversion =
        document.getElementById(
          "la-conversion-" + index
        ).checked ? 1 : 0;

      var dailyLimit = parseInt(
        document.getElementById(
          "la-limit-" + index
        ).value || "0",
        10
      );

      var weight = parseFloat(
        document.getElementById(
          "la-weight-" + index
        ).value || "1"
      );

      var stopReason =
        document.getElementById(
          "la-reason-" + index
        ).value || "";

      var teamLeader = row.team_leader || "";

      var teamLeaderInput =
        document.getElementById(
          "la-tl-" + index
        );

      if (teamLeaderInput) {
        teamLeader =
          teamLeaderInput.value || "";
      }

      if (
        enabled &&
        !selectedSources.length
      ) {
        laAlert(
          "Select at least one Lead Source",
          "red"
        );
        return;
      }

      if (
        enabled &&
        dailyLimit <= 0
      ) {
        laAlert(
          "Set a daily lead limit",
          "red"
        );
        return;
      }

      var saveButton =
        document.querySelector(
          "#la-row-" +
          index +
          " .la-save-btn"
        );

      if (saveButton) {
        saveButton.disabled = true;
        saveButton.textContent =
          "Saving...";
      }

      frappe.call({
        method:
          "lead_assignment_configuration",
        args: {
          action: "save_agent",
          agent: row.agent,
          team_leader: teamLeader,
          auto_enabled: enabled,
          lead_sources:
            selectedSources.join(", "),
          temporarily_stopped: stopped,
          stop_reason: stopReason,
          share_weight: weight,
          use_conversion: useConversion,
          max_per_day: dailyLimit
        }
      }).then(function (response) {
        var result =
          response.message || {};

        if (!result.saved) {
          throw new Error(
            "Configuration was not saved"
          );
        }

        laAlert(
          row.employee_name +
          " configuration saved",
          "green"
        );

        window.leadAssignLoadConfig();
      }).catch(function (error) {
        console.error(
          "Lead assignment save failed",
          error
        );

        laAlert(
          "Save failed. Check browser console.",
          "red"
        );

        if (saveButton) {
          saveButton.disabled = false;
          saveButton.textContent =
            "💾 Save";
        }
      });
    };
})();



/* LIFE LEAD ASSIGNMENT GREEN UI V2 */
(function () {
  "use strict";

  function esc(value) {
    return String(value == null ? "" : value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function closeAll(except) {
    document
      .querySelectorAll(".la-source-dropdown.open")
      .forEach(function (dropdown) {
        if (dropdown !== except) {
          dropdown.classList.remove("open");
        }
      });
  }

  function selectedOptions(select) {
    return Array.prototype.filter.call(
      select.options,
      function (option) {
        return option.selected;
      }
    );
  }

  function updatePicker(picker, select) {
    var selected = selectedOptions(select);
    var button = picker.querySelector(".la-picker-button");
    var count = picker.querySelector(".la-picker-count");
    var chips = picker.querySelector(".la-picker-chips");

    if (count) {
      count.textContent = String(selected.length);
    }

    if (button) {
      if (!selected.length) {
        button.classList.add("empty");
        button.querySelector(".la-picker-text").textContent =
          "Select lead sources";
      } else if (selected.length === 1) {
        button.classList.remove("empty");
        button.querySelector(".la-picker-text").textContent =
          selected[0].textContent;
      } else {
        button.classList.remove("empty");
        button.querySelector(".la-picker-text").textContent =
          selected.length + " sources selected";
      }
    }

    if (chips) {
      if (!selected.length) {
        chips.innerHTML =
          '<span class="la-no-source">No sources selected</span>';
      } else {
        var visible = selected.slice(0, 3);

        chips.innerHTML = visible.map(function (option) {
          return (
            '<span class="la-source-chip">' +
              esc(option.textContent) +
            "</span>"
          );
        }).join("");

        if (selected.length > 3) {
          chips.innerHTML +=
            '<span class="la-source-more">+' +
              (selected.length - 3) +
              " more</span>";
        }
      }
    }

    picker
      .querySelectorAll(".la-picker-option input")
      .forEach(function (checkbox) {
        var option = Array.prototype.find.call(
          select.options,
          function (item) {
            return item.value === checkbox.value;
          }
        );

        checkbox.checked = !!(
          option && option.selected
        );
      });
  }

  function setAll(picker, select, selected) {
    Array.prototype.forEach.call(
      select.options,
      function (option) {
        option.selected = selected;
      }
    );

    updatePicker(picker, select);
  }

  function filterOptions(picker, searchText) {
    var term = String(searchText || "")
      .trim()
      .toLowerCase();

    picker
      .querySelectorAll(".la-picker-option")
      .forEach(function (label) {
        var text = String(
          label.getAttribute("data-search") || ""
        ).toLowerCase();

        label.style.display =
          !term || text.indexOf(term) !== -1
            ? "flex"
            : "none";
      });
  }

  function enhanceSelect(select) {
    if (
      !select ||
      select.getAttribute("data-green-enhanced") === "1"
    ) {
      return;
    }

    select.setAttribute("data-green-enhanced", "1");

    var picker = document.createElement("div");
    picker.className = "la-source-picker";

    var optionHtml = Array.prototype.map.call(
      select.options,
      function (option) {
        return (
          '<label class="la-picker-option" data-search="' +
            esc(option.textContent) +
          '">' +
            '<input type="checkbox" value="' +
              esc(option.value) +
            '">' +
            '<span class="la-custom-check">✓</span>' +
            '<span class="la-option-name">' +
              esc(option.textContent) +
            "</span>" +
          "</label>"
        );
      }
    ).join("");

    picker.innerHTML =
      '<button type="button" class="la-picker-button">' +
        '<span class="la-picker-icon">⌕</span>' +
        '<span class="la-picker-text">Select lead sources</span>' +
        '<span class="la-picker-count">0</span>' +
        '<span class="la-picker-arrow">⌄</span>' +
      "</button>" +

      '<div class="la-source-dropdown">' +
        '<div class="la-picker-search-wrap">' +
          '<span>⌕</span>' +
          '<input type="text" class="la-picker-search" ' +
            'placeholder="Search lead source...">' +
        "</div>" +

        '<div class="la-picker-actions">' +
          '<button type="button" class="la-picker-all">' +
            "Select all" +
          "</button>" +
          '<button type="button" class="la-picker-clear">' +
            "Clear" +
          "</button>" +
        "</div>" +

        '<div class="la-picker-options">' +
          optionHtml +
        "</div>" +
      "</div>" +

      '<div class="la-picker-chips"></div>';

    select.style.display = "none";
    select.parentNode.insertBefore(
      picker,
      select.nextSibling
    );

    var button =
      picker.querySelector(".la-picker-button");

    var dropdown =
      picker.querySelector(".la-source-dropdown");

    var search =
      picker.querySelector(".la-picker-search");

    button.addEventListener("click", function (event) {
      event.preventDefault();
      event.stopPropagation();

      var willOpen =
        !dropdown.classList.contains("open");

      closeAll(dropdown);

      dropdown.classList.toggle(
        "open",
        willOpen
      );

      if (willOpen) {
        setTimeout(function () {
          search.focus();
        }, 50);
      }
    });

    search.addEventListener("input", function () {
      filterOptions(picker, search.value);
    });

    search.addEventListener("click", function (event) {
      event.stopPropagation();
    });

    picker
      .querySelector(".la-picker-all")
      .addEventListener("click", function (event) {
        event.preventDefault();
        event.stopPropagation();
        setAll(picker, select, true);
      });

    picker
      .querySelector(".la-picker-clear")
      .addEventListener("click", function (event) {
        event.preventDefault();
        event.stopPropagation();
        setAll(picker, select, false);
      });

    picker
      .querySelectorAll(".la-picker-option input")
      .forEach(function (checkbox) {
        checkbox.addEventListener(
          "change",
          function () {
            var option =
              Array.prototype.find.call(
                select.options,
                function (item) {
                  return (
                    item.value === checkbox.value
                  );
                }
              );

            if (option) {
              option.selected = checkbox.checked;
            }

            updatePicker(picker, select);
          }
        );
      });

    updatePicker(picker, select);
  }

  function enhanceAll() {
    document
      .querySelectorAll(
        "#lead-assignment-config-area " +
        "select.la-source-select"
      )
      .forEach(enhanceSelect);
  }

  document.addEventListener("click", function () {
    closeAll(null);
  });

  var observer = new MutationObserver(function () {
    enhanceAll();
  });

  function start() {
    enhanceAll();

    var area = document.getElementById(
      "lead-assignment-config-area"
    );

    if (area) {
      observer.observe(area, {
        childList: true,
        subtree: true
      });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      start
    );
  } else {
    start();
  }
})();



/* LIFE SIMPLE ASSIGNMENT UI V3 */
(function () {
  "use strict";

  function removeDuplicateAreas() {
    var areas = document.querySelectorAll(
      "#lead-assignment-config-area"
    );

    if (areas.length <= 1) return;

    for (var i = 1; i < areas.length; i++) {
      var parent = areas[i].closest(
        ".la-config-area"
      );

      if (parent) {
        parent.remove();
      } else {
        areas[i].remove();
      }
    }
  }

  function updateStopReason(row) {
    if (!row) return;

    var stopSwitch = row.querySelector(
      '[id^="la-stopped-"]'
    );

    var reason = row.querySelector(
      ".la-stop-reason"
    );

    if (!stopSwitch || !reason) return;

    reason.style.display =
      stopSwitch.checked ? "block" : "none";

    if (!stopSwitch.__simpleBound) {
      stopSwitch.__simpleBound = true;

      stopSwitch.addEventListener(
        "change",
        function () {
          reason.style.display =
            stopSwitch.checked
              ? "block"
              : "none";

          if (!stopSwitch.checked) {
            reason.value = "";
          }
        }
      );
    }
  }

  function applySimpleLayout() {
    removeDuplicateAreas();

    document
      .querySelectorAll(
        "#lead-assignment-config-area " +
        ".la-table tbody tr"
      )
      .forEach(function (row) {
        updateStopReason(row);
      });
  }

  var observer = new MutationObserver(function () {
    applySimpleLayout();
  });

  function start() {
    applySimpleLayout();

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      start
    );
  } else {
    start();
  }
})();



/* LIFE ASSIGNMENT RECOVERY JS V5 */
(function () {
  "use strict";

  function recoverAssignmentUI() {
    /* Keep only one assignment section */
    var areas = document.querySelectorAll(
      "#lead-assignment-config-area"
    );

    for (var i = 1; i < areas.length; i++) {
      var duplicate = areas[i].closest(".la-config-area");

      if (duplicate) {
        duplicate.remove();
      } else {
        areas[i].remove();
      }
    }

    var area = document.getElementById(
      "lead-assignment-config-area"
    );

    if (!area) return;

    /*
     * Use the original source selector.
     * It contains the real Lead Source options and selected values.
     */
    area.querySelectorAll(
      "select.la-source-select"
    ).forEach(function (select) {
      select.style.setProperty(
        "display",
        "block",
        "important"
      );

      select.style.setProperty(
        "visibility",
        "visible",
        "important"
      );

      select.style.setProperty(
        "opacity",
        "1",
        "important"
      );

      select.removeAttribute("data-green-enhanced");

      var picker = select.parentNode
        ? select.parentNode.querySelector(
            ".la-source-picker"
          )
        : null;

      if (picker) {
        picker.style.setProperty(
          "display",
          "none",
          "important"
        );
      }
    });

    /* Add labels used by the clean card UI */
    area.querySelectorAll(
      ".la-table tbody tr"
    ).forEach(function (row) {
      row.classList.add("la-recovered-row");

      var cells = row.querySelectorAll("td");

      var labels = [
        "Agent & Attendance",
        "Allowed Lead Sources",
        "Today / Daily Limit",
        "Conversion Performance",
        "Auto Assignment",
        "Temporary Stop",
        "Team Leader",
        "Save Changes"
      ];

      cells.forEach(function (cell, index) {
        if (labels[index]) {
          cell.setAttribute(
            "data-field-label",
            labels[index]
          );
        }
      });

      /* Stop reason is useful only when Stop is enabled */
      var stopSwitch = row.querySelector(
        '[id^="la-stopped-"]'
      );

      var stopReason = row.querySelector(
        ".la-stop-reason"
      );

      if (stopSwitch && stopReason) {
        function showStopReason() {
          stopReason.style.display =
            stopSwitch.checked ? "block" : "none";

          if (!stopSwitch.checked) {
            stopReason.value = "";
          }
        }

        showStopReason();

        if (!stopSwitch.dataset.recoveryBound) {
          stopSwitch.dataset.recoveryBound = "1";

          stopSwitch.addEventListener(
            "change",
            showStopReason
          );
        }
      }
    });
  }

  var scheduled = false;

  function scheduleRecovery() {
    if (scheduled) return;

    scheduled = true;

    window.requestAnimationFrame(function () {
      scheduled = false;
      recoverAssignmentUI();
    });
  }

  function startRecovery() {
    recoverAssignmentUI();

    var observer = new MutationObserver(
      scheduleRecovery
    );

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });

    /* Recover again after asynchronous API rendering */
    setTimeout(recoverAssignmentUI, 500);
    setTimeout(recoverAssignmentUI, 1500);
    setTimeout(recoverAssignmentUI, 3000);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      startRecovery
    );
  } else {
    startRecovery();
  }
})();



