/* ═══════════════════════════════════════════════════════════════════════════
   LIFE CC DASHBOARD · UI ADD-ON v11
   ───────────────────────────────────────────────────────────────────────────
   PASTE THIS AT THE VERY END of the page's Javascript field.
   Everything above it stays byte-for-byte unchanged.

   It only rearranges controls that already exist and adds two more range
   buttons. No API call, no field name, no data path is touched.

     1 · merges the date fields and the quick-range chips into ONE row
     2 · adds "Tomorrow" and "Next Month", puts all six in proper order
     3 · drops the duplicate Apply button and the long hint line
     4 · keeps the KPI tiles to exactly two rows whatever the tile count
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  "use strict";

  var D = document;

  /* ── date helpers ─────────────────────────────────────────────────── */
  function iso(d) {
    return d.getFullYear() + "-" +
           String(d.getMonth() + 1).padStart(2, "0") + "-" +
           String(d.getDate()).padStart(2, "0");
  }

  /* Same billing cycle the page already uses: 6th of a month → 5th of the next.
     off = 0 current cycle, +1 next, -1 previous. */
  function cycle(off) {
    var n = new Date(), y = n.getFullYear(), m = n.getMonth();
    if (n.getDate() < 6) m -= 1;
    m += (off || 0);
    return { from: iso(new Date(y, m, 6)), to: iso(new Date(y, m + 1, 5)) };
  }

  function setDates(f, t) {
    var a = D.getElementById("cc-range-from"),
        b = D.getElementById("cc-range-to");
    if (a) a.value = f;
    if (b) b.value = t;
  }

  /* ── 1–3 · rebuild the range bar as a single responsive row ───────── */
  function buildBar() {
    var bar = D.getElementById("cc-quick-range");
    if (!bar || bar.getAttribute("data-cc-v11")) return !!bar;

    var from = D.getElementById("cc-range-from"),
        to   = D.getElementById("cc-range-to");
    if (!from || !to) return false;

    bar.setAttribute("data-cc-v11", "1");
    bar.classList.add("cc-rangebar");
    bar.removeAttribute("style");

    var toolbar = from.closest(".cc-toolbar");

    /* label · from · to · divider — pulled to the front of the row */
    var lab = D.createElement("span");
    lab.className = "rb-lb";
    lab.textContent = "📆 Date";

    var sep = D.createElement("span");
    sep.className = "rb-sep";
    sep.textContent = "to";

    var div = D.createElement("span");
    div.className = "rb-div";

    bar.insertBefore(lab, bar.firstChild);
    lab.after(from);
    from.after(sep);
    sep.after(to);
    to.after(div);

    function pick(kind) {
      return bar.querySelector('.cc-qr-btn[data-range="' + kind + '"]');
    }

    /* the two new ranges — the existing bar listener handles the highlight,
       this listener only fills the dates, and it runs first */
    function mk(kind, label) {
      var b = D.createElement("button");
      b.type = "button";
      b.className = "cc-qr-btn";
      b.setAttribute("data-range", kind);
      b.textContent = label;
      b.addEventListener("click", function () {
        if (kind === "tomorrow") {
          var d = new Date(Date.now() + 86400000);
          setDates(iso(d), iso(d));
        } else if (kind === "nextmonth") {
          var c = cycle(1);
          setDates(c.from, c.to);
        }
      });
      return b;
    }

    var yest = pick("yesterday"), mon = pick("month");
    if (yest) yest.after(mk("tomorrow", "Tomorrow"));
    if (mon)  mon.after(mk("nextmonth", "Next Month"));

    /* order: Today · Yesterday · Tomorrow · This Month · Next Month ·
              Last Month · filter mode · Apply · Clear */
    var mode  = D.getElementById("cc-date-mode"),
        apply = pick("apply"),
        clear = pick("clear");
    if (mode && apply) bar.insertBefore(mode, apply);
    if (clear) bar.appendChild(clear);
    if (apply && clear) bar.insertBefore(apply, clear);

    /* let the stylesheet own the look */
    bar.querySelectorAll(".cc-qr-btn").forEach(function (b) { b.removeAttribute("style"); });
    if (mode) mode.removeAttribute("style");

    /* the old toolbar now only holds the duplicate Apply and the hint line */
    if (toolbar && toolbar.parentElement) {
      toolbar.parentElement.insertBefore(bar, toolbar);
      toolbar.remove();
    }
    return true;
  }

  /* ── 4 · KPI tiles in exactly two rows ────────────────────────────── */
  function twoRows() {
    D.querySelectorAll(".cc-erp-root .stat-grid").forEach(function (g) {
      var n = g.querySelectorAll(".stat-card").length;
      if (!n) return;
      g.style.setProperty("--cols", Math.min(6, Math.max(2, Math.ceil(n / 2))));
    });
  }

  /* ── boot ─────────────────────────────────────────────────────────── */
  var tries = 0;
  var poll = setInterval(function () {
    if (buildBar() || ++tries > 60) clearInterval(poll);
  }, 250);

  var main = D.getElementById("main-content");
  if (main && window.MutationObserver) {
    var t = null;
    new MutationObserver(function () {
      clearTimeout(t);
      t = setTimeout(twoRows, 120);
    }).observe(main, { childList: true, subtree: true });
  }
  twoRows();
  setTimeout(twoRows, 1200);
})();



/* ==========================================================================
   LIFE STAFF ATTENDANCE PANEL  v5  ·  JAVASCRIPT
   Standalone. No dependency on the COO dashboard code.
   Paste at the end of the Javascript field of ANY Frappe Web Page:
     /app/web-page/branch-command-center
     /app/web-page/cc-new-dash          (CC dashboard)
     /app/web-page/life-coo-dashboard
     ...any other module page

   Opens from:  #life-att-open  ·  [data-att-open]  ·  [data-edge="hr"]  ·  #bcc3-att-edge
   Or from code:  LIFEAttendance.open()
