  });
  return { date, closed, list, feed: punches.length, branches: [...new Set(list.map(r => r.branch))].sort() };
}

/* ---- week-off entitlement: 6 present days = 1 off, runs count once ------ */
function applyWeekOff(kinds) {
  const present = kinds.filter(x => x.k === 'P' || x.k === 'HD').length;
  let budget = Math.floor(present / EARN_DAYS); const earned = budget;
  let run = 0;
  const out = { P: 0, HD: 0, L: 0, WO: 0, A: 0, earned };
  kinds.forEach(x => {
    if (x.k !== 'OFF') { run = 0; out[x.k]++; x.f = x.k; return; }
    run++;
    if (run === 1 && budget > 0) { budget--; out.WO++; x.f = 'WO'; } else { out.A++; x.f = 'A'; }
  });
  out.left = budget;
  return out;
}

/* ---- history scan ------------------------------------------------------- */
async function scan(date, staff) {
  const mStart = date.slice(0, 7) + '-01', back = shift(date, -SCAN_BACK);
  const from = back < mStart ? back : mStart;
  const [att, offs, leaves] = await Promise.all([
    rows('Attendance', ['employee','attendance_date','status','in_time','out_time','custom_check_in_time','custom_check_out_time'],
      [['attendance_date','>=',from],['attendance_date','<=',date],['docstatus','!=',2]], 'attendance_date asc, modified desc, name asc'),
    rows('Shift Assignment', ['employee','start_date','end_date','shift_type'],
      [['start_date','<=',date],['end_date','>=',from],['docstatus','=',1],['shift_type','=','Week Off']], 'start_date asc').catch(() => []),
    rows('Leave Application', ['employee','from_date','to_date','leave_type','status'],
      [['from_date','<=',date],['to_date','>=',from],['docstatus','!=',2]], 'from_date asc').catch(() => [])
  ]);

  const rec = new Map(), seen = new Set();
  att.forEach(r => { const k = r.employee + '|' + r.attendance_date; if (seen.has(k)) return; seen.add(k);
    if (!rec.has(r.employee)) rec.set(r.employee, new Map()); rec.get(r.employee).set(r.attendance_date, r); });
  const woSet = new Map();
  offs.forEach(o => { if (!woSet.has(o.employee)) woSet.set(o.employee, new Set());
    for (let d = o.start_date; d <= (o.end_date || o.start_date) && d <= date; d = shift(d, 1)) woSet.get(o.employee).add(d); });
  const lvMap = new Map();
  leaves.forEach(l => { if (!lvMap.has(l.employee)) lvMap.set(l.employee, []); lvMap.get(l.employee).push(l); });
  const leaveOn = (e, d) => (lvMap.get(e) || []).find(l => l.from_date <= d && (l.to_date || l.from_date) >= d);

  const out = new Map();
  staff.forEach(s => {
    const r = rec.get(s.id) || new Map(), wo = woSet.get(s.id) || new Set(), doj = s.doj || '';
    const kinds = [], hist = [];
    let work = 0, paired = 0, single = 0, outMiss = 0, lastPresent = '', eligible = 0;

    for (let d = from; d <= date; d = shift(d, 1)) {
      if (doj && d < doj) continue;
      const a = r.get(d), st = String(a && a.status || ''), L = leaveOn(s.id, d);
      const P = a ? punchPair(attTimes(a)) : { ev: [], in: null, out: null, grouped: 0 };
      let k;
      if (P.ev.length || /present|work from home/i.test(st)) k = /half/i.test(st) ? 'HD' : 'P';
      else if (L && /approved/i.test(L.status)) k = 'L';
      else if (/leave/i.test(st)) k = 'L';
      else k = 'OFF';
      if (k === 'P' || k === 'HD') { lastPresent = d;
        if (P.in != null && P.out != null) { work += P.out - P.in; paired++; }
        else if (P.in != null) { single++; outMiss++; } }
      hist.push({ date: d, k, roster: wo.has(d), in: P.in, out: P.out, grouped: P.grouped, erp: st, leave: L ? L.status : '' });
      if (d >= mStart) { kinds.push({ date: d, k }); eligible++; }
    }

    const m = applyWeekOff(kinds);
    kinds.forEach(x => { const h = hist.find(y => y.date === x.date); if (h) h.f = x.f; });

    let gap = 0;
    for (let i = hist.length - 1; i >= 0; i--) {
      const h = hist[i];
      if (h.k === 'P' || h.k === 'HD') break;
      if (h.k === 'L') continue;
      gap++;
    }
    const never = !lastPresent;
    out.set(s.id, {
      P: m.P + m.HD, full: m.P, HD: m.HD, A: m.A, WO: m.WO, L: m.L, earned: m.earned, left: m.left,
      payable: m.P + m.HD * 0.5 + m.WO + m.L, eligible,
      work, avg: paired ? hm(work / paired) : '\u2014', avgDec: paired ? Math.round(work / paired / 36000) / 100 : '',
      paired, single, outMiss, lastPresent, gap, never, hist,
      abscond: never || gap >= 30, g5: gap >= 5, g10: gap >= 10, g30: gap >= 30,
      discipline: single >= 5 || (paired + single >= 4 && single / (paired + single) > 0.5)
    });
  });
  return { out, from, mStart, label: '1\u2013' + Number(date.slice(8,10)) + ' ' + new Date(date + 'T00:00:00').toLocaleDateString('en-IN', { month: 'short' }) };
}

/* ---- state -------------------------------------------------------------- */
const S = { date: dayS(new Date()), branch: '', q: '', chip: '', sub: '', data: null, sc: null,
            view: 'day', emp: null, ym: monthKey(new Date()), timer: 0, busy: 0, gen: 0,
            wide: localStorage.getItem('life-att-wide') === '1' };
let el = null;

function build() {
  el = document.createElement('div');
  el.id = 'att4';
  el.classList.add(HOST === 'branch' ? 'h-branch' : 'h-coo');
  if (S.wide) el.classList.add('wide');
  el.innerHTML =
   '<div class="a-scrim" data-a-close></div>' +
   '<section class="a-drawer" role="dialog" aria-modal="true" aria-label="Staff Attendance">' +
     '<header class="a-head">' +
       '<span class="a-mark">LIFE</span>' +
       '<span class="a-title"><b>Staff Attendance</b><small id="a-sub">\u2026</small></span>' +
       '<button data-a-wide title="Expand / narrow">\u2194</button>' +
       '<button data-a-xls title="Download Excel">\u2913</button>' +
       '<button data-a-refresh title="Refresh">\u21BB</button>' +
       '<button data-a-print title="Print">\u2399</button>' +
       '<button data-a-close title="Close">\u00D7</button>' +
     '</header>' +
     '<div class="a-bar">' +
       '<input type="date" id="a-date" aria-label="Date">' +
       (HOST === 'branch' ? '<span class="a-lock" id="a-lock"></span>' : '<select id="a-branch" aria-label="Branch"><option value="">All branches</option></select>') +
       '<input id="a-q" placeholder="Search\u2026" aria-label="Search employee">' +
     '</div>' +
     '<div class="a-chips" id="a-chips"></div>' +
     '<div class="a-subs" id="a-subs" hidden></div>' +
     '<div class="a-body" id="a-body"></div>' +
     '<footer class="a-foot" id="a-foot"></footer>' +
   '</section>';
  document.body.appendChild(el);

  el.addEventListener('click', e => {
    if (e.target.hasAttribute && e.target.hasAttribute('data-a-close')) return close();
    const b = e.target.closest('button'); if (!b || !el.contains(b)) return;
    e.stopPropagation();
    if (b.hasAttribute('data-a-close'))   return close();
    if (b.hasAttribute('data-a-refresh')) return load(true);
    if (b.hasAttribute('data-a-print'))   { document.body.classList.add('a-printing'); window.print(); return; }
    if (b.hasAttribute('data-a-xls'))     return exportXls();
    if (b.hasAttribute('data-a-wide'))    { S.wide = !S.wide; el.classList.toggle('wide', S.wide); localStorage.setItem('life-att-wide', S.wide ? '1' : '0'); return; }
    if (b.hasAttribute('data-a-back'))    { S.view = 'day'; paint(); return; }
    if (b.dataset.aChip !== undefined)    { S.chip = S.chip === b.dataset.aChip ? '' : b.dataset.aChip; S.sub = ''; S.view = 'day'; paint(); return; }
    if (b.dataset.aSub !== undefined)     { S.sub = S.sub === b.dataset.aSub ? '' : b.dataset.aSub; S.view = 'day'; paint(); return; }
    if (b.dataset.aMonth)                 { const d = new Date(+S.ym.slice(0,4), +S.ym.slice(5,7) - 1 + Number(b.dataset.aMonth), 1); S.ym = monthKey(d); return openMonth(S.emp); }
    if (b.dataset.aLeave)                 { const r = S.data.list.find(x => x.id === b.dataset.aLeave); if (r) applyLeave(r); return; }
    if (b.dataset.aEmp)                   return openMonth(b.dataset.aEmp);
  });
  el.addEventListener('input', e => {
    if (e.target.id === 'a-q')      { S.q = e.target.value.trim().toLowerCase(); paint(); }
    if (e.target.id === 'a-branch') { S.branch = e.target.value; paint(); }
  });
  el.addEventListener('change', e => { if (e.target.id === 'a-date') { S.date = e.target.value || dayS(new Date()); load(true); } });
  el.addEventListener('error', e => { if (e.target.tagName === 'IMG') e.target.remove(); }, true);
  window.addEventListener('afterprint', () => document.body.classList.remove('a-printing'));
  document.addEventListener('keydown', e => { if (e.key === 'Escape' && el && el.classList.contains('open')) close(); });
  /* follow the host page's own branch selector, if it has one */
  document.addEventListener('change', e => {
    if (e.target && e.target.matches && e.target.matches(CFG.branchSelect) && el && el.classList.contains('open')) load(true);
  });
}

function open() {
  if (!el) { HOST = branchSel() ? 'branch' : 'coo'; build(); }
  el.classList.add('open');
  document.body.style.overflow = 'hidden';
  el.querySelector('#a-date').value = S.date;
  el.querySelector('[data-a-close]').focus();
  load(true);
  clearInterval(S.timer);
  S.timer = setInterval(() => { if (S.view === 'day' && !S.busy && !document.hidden) load(false); }, POLL_MS);
}
function close() { clearInterval(S.timer); if (el) el.classList.remove('open'); document.body.style.overflow = ''; S.view = 'day'; }

const skeleton = n => '<div class="a-sk">' + Array.from({ length: n }, () => '<i></i>').join('') + '</div>';

async function load(spin) {
  if (!el) return;
  const g = ++S.gen; S.busy = 1;
  if (spin) { el.querySelector('#a-body').innerHTML = skeleton(9); el.querySelector('#a-foot').innerHTML = '<span>Reading punch data\u2026</span>'; }
  try {
    const d = await readDay(S.date);
    if (g !== S.gen) return;
    S.data = d; S.sc = null; S.view = 'day';
    if (HOST === 'branch') {
      S.branch = '';
      const lk = el.querySelector('#a-lock');
      if (lk) lk.textContent = branchVal() || d.branches.join(', ') || 'Branch';
    } else {
      const sel = el.querySelector('#a-branch'), keep = S.branch;
      sel.innerHTML = '<option value="">All branches</option>' + d.branches.map(b => '<option value="' + esc(b) + '">' + esc(b) + '</option>').join('');
      sel.value = d.branches.includes(keep) ? keep : (S.branch = '');
    }
    paint();
    scan(S.date, d.list).then(sc => { if (g !== S.gen) return; S.sc = sc; paint(); }).catch(() => {});
  } catch (err) {
    if (g !== S.gen) return;
    el.querySelector('#a-body').innerHTML = '<div class="a-err">' + esc(err.message) + '<br><button data-a-refresh>\u21BB Retry</button></div>';
  } finally { S.busy = 0; }
}

function visible() {
  if (!S.data) return [];
  const sc = S.sc && S.sc.out;
  return S.data.list.filter(r => {
    if (S.branch && r.branch !== S.branch) return false;
    if (S.q && !(r.name + ' ' + r.desig + ' ' + r.branch + ' ' + r.dept).toLowerCase().includes(S.q)) return false;
    if (!S.chip) return true;
    if (S.chip === 'FLAG') {
      const m = sc && sc.get(r.id);
      if (!(r.grouped > 0 || r.state === 'UNVERIFIED' || (m && (m.abscond || m.g5 || m.discipline)))) return false;
      if (!S.sub || !m) return true;
      if (S.sub === 'ABSCOND') return m.abscond;
      if (S.sub === 'G5')  return m.g5 && !m.g10;
      if (S.sub === 'G10') return m.g10 && !m.g30;
      if (S.sub === 'G30') return m.g30;
      if (S.sub === 'DISC') return m.discipline || r.grouped > 0;
      return true;
    }
    return r.state === S.chip;
  });
}

function row(r) {
  const st = ST[r.state], m = S.sc && S.sc.out.get(r.id);
  const time = r.in == null ? '<span class="a-t"><em>\u2014\u2014</em></span>'
    : '<span class="a-t">' + clock(r.in) + '<i>\u2192</i>' + (r.out == null ? '<em>\u2014\u2014</em>' : clock(r.out)) + '</span>';
  const mtd = m ? '<u>' + esc(S.sc.label) + '</u><i class="p">P ' + m.P + '</i><i class="a">A ' + m.A + '</i><i class="w">WO ' + m.WO + '</i>' +
      (m.L ? '<i class="l">L ' + m.L + '</i>' : '') + '<i class="e" title="Week offs earned, still due">\u2609 ' + m.earned + (m.left ? ' \u00b7 ' + m.left + ' due' : '') + '</i>'
    : '<i class="sk"></i>';
  const warn = m ? (m.abscond ? '\u26A0 ' + (m.never ? 'no attendance in window' : 'absconding \u00b7 ' + m.gap + 'd')
      : m.g5 ? '\u26A0 away ' + m.gap + ' days' : m.discipline ? '\u26A0 single punch ' + m.single + 'd' : '') : '';
  return '<button class="a-row s-' + st.c + '" data-a-emp="' + esc(r.id) + '">' +
    '<span class="a-av' + (r.sex ? ' g-' + r.sex : '') + '" data-ini="' + esc(r.ini) + '">' +
      (r.img ? '<img loading="lazy" decoding="async" src="' + esc(r.img) + '" alt="">' : '') +
      (r.sex ? '<u class="a-sex">' + (r.sex === 'f' ? '\u2640' : '\u2642') + '</u>' : '') + '</span>' +
    '<span class="a-id">' +
      '<b>' + esc(r.name) +
        (r.badge ? '<em class="a-bg b-' + r.badge.c + '" title="' + esc(r.badge.t) + '">' + esc(r.badge.s) + '</em>' : '') +
        (r.phone ? '<em class="a-ph" title="' + esc(r.phoneKind + ' \u00b7 ' + r.phone) + '">\u260E</em>' : '') + '</b>' +
      '<small>' + esc(r.desig) + (S.branch || HOST === 'branch' ? '' : ' \u00b7 ' + esc(r.branch)) + '</small>' +
      '<small class="a-ja">Job Age - ' + esc(r.age || '\u2014') + '</small>' +
      '<span class="a-mtd">' + mtd + '</span></span>' +
    '<span class="a-when">' + time +
      '<span class="a-st">' + esc(st.t) + (r.provisional ? '<u> \u00b7 prov</u>' : '') + '</span>' +
      '<span class="a-hr">HRS ' + esc(r.hours) + (m && m.paired ? ' \u00b7 Avg ' + esc(m.avg) : '') + '</span>' +
      (r.grouped ? '<span class="a-fl">\u26A0 \u2212' + r.grouped + ' repeat</span>' : '') +
      (warn ? '<span class="a-fl">' + esc(warn) + '</span>' : '') +
    '</span>' +
    (r.state === 'CHECKED_OUT' ? '<span class="a-tick">\u2713</span>' : '') + '</button>';
}

function paint() {
  if (!S.data || !el) return;
  const all = S.data.list.filter(r => !S.branch || r.branch === S.branch);
  const list = visible(), n = k => all.filter(r => r.state === k).length;
  const sc = S.sc && S.sc.out;
  const flag = all.filter(r => { const m = sc && sc.get(r.id); return r.grouped > 0 || r.state === 'UNVERIFIED' || (m && (m.abscond || m.g5 || m.discipline)); }).length;
  const present = all.filter(r => r.present).length;
  const scope = HOST === 'branch' ? (branchVal() || 'Branch') : (S.branch || 'All branches');

  el.querySelector('#a-sub').textContent = scope + ' \u00b7 ' + shortDate(S.date) + ' \u00b7 ' + present + ' present / ' + all.length;
  el.querySelector('#a-chips').innerHTML = [
    ['', 'All ' + all.length], ['ON_FLOOR', 'On floor ' + n('ON_FLOOR')], ['CHECKED_OUT', 'Out ' + n('CHECKED_OUT')],
    ['OUT_MISSING', 'OUT mis ' + n('OUT_MISSING')], ['ABSENT', 'Absent ' + n('ABSENT')],
    ['WEEK_OFF', 'W/O ' + n('WEEK_OFF')], ['LEAVE', 'Leave ' + (n('LEAVE') + n('LEAVE_REQ'))], ['FLAG', '\u26A0 Review ' + flag]
  ].map(([k, t]) => '<button class="a-chip' + (S.chip === k ? ' on' : '') + ' c-' + (k || 'all') + '" data-a-chip="' + k + '">' + esc(t) + '</button>').join('');

  const subs = el.querySelector('#a-subs');
  subs.hidden = S.chip !== 'FLAG';
  if (S.chip === 'FLAG') {
    const cnt = k => sc ? all.filter(r => { const m = sc.get(r.id); if (!m) return false;
      return k === 'ABSCOND' ? m.abscond : k === 'G5' ? (m.g5 && !m.g10) : k === 'G10' ? (m.g10 && !m.g30) : k === 'G30' ? m.g30 : (m.discipline || r.grouped > 0); }).length : '\u2026';
    subs.innerHTML = [['ABSCOND','Absconding'],['G5','5+ days'],['G10','10+ days'],['G30','30+ days'],['DISC','Punch discipline']]
      .map(([k, t]) => '<button class="a-sub' + (S.sub === k ? ' on' : '') + '" data-a-sub="' + k + '">' + esc(t) + ' ' + cnt(k) + '</button>').join('');
  }

  if (S.view !== 'day') return;
  el.querySelector('#a-body').innerHTML =
    '<div class="a-pr">' + esc(scope) + ' \u00b7 Staff attendance ' + esc(S.date) + ' \u00b7 ' + present + ' present of ' + all.length + '</div>' +
    (list.length ? list.map(row).join('') : '<div class="a-note">No employees match this filter.</div>');
  el.querySelector('#a-foot').innerHTML =
    '<span>Day 06:00\u201323:00 \u00b7 IN with no OUT after 9h = OUT PUN MIS \u00b7 ' + EARN_DAYS + ' present days earn 1 week off \u00b7 continuous offs count 1 W/O, rest absent</span>' +
    (S.data.feed ? '<span class="a-ok">Punch log live \u00b7 ' + S.data.feed + ' punches</span>'
                 : '<span class="a-warn">\u26A0 Employee Checkin empty \u2014 times read from the Attendance record</span>') +
    (S.sc ? '' : '<span>Month figures loading\u2026</span>');
}

function applyLeave(r) {
  window.open('/app/leave-application/new?employee=' + encodeURIComponent(r.id) +
    '&from_date=' + encodeURIComponent(S.date) + '&to_date=' + encodeURIComponent(S.date), '_blank', 'noopener');
}

/* ---- month view --------------------------------------------------------- */
async function openMonth(empId) {
  const r = S.data && S.data.list.find(x => x.id === empId); if (!r) return;
  S.emp = empId; S.view = 'month';
  const body = el.querySelector('#a-body');
  body.innerHTML = skeleton(5);
  try {
    const ym = S.ym, first = ym + '-01', last = ym + '-' + pad(lastDay(ym)), today = dayS(new Date());
    const [att, offs, leaves] = await Promise.all([
      rows('Attendance', ['attendance_date','status','in_time','out_time','custom_check_in_time','custom_check_out_time'],
        [['employee','=',empId],['attendance_date','>=',first],['attendance_date','<=',last],['docstatus','!=',2]], 'attendance_date asc, modified desc, name asc'),
      rows('Shift Assignment', ['start_date','end_date','shift_type'],
        [['employee','=',empId],['start_date','<=',last],['end_date','>=',first],['docstatus','=',1],['shift_type','=','Week Off']], 'start_date asc').catch(() => []),
      rows('Leave Application', ['from_date','to_date','leave_type','status'],
        [['employee','=',empId],['from_date','<=',last],['to_date','>=',first],['docstatus','!=',2]], 'from_date asc').catch(() => [])
    ]);
    const rec = new Map(); att.forEach(a => { if (!rec.has(a.attendance_date)) rec.set(a.attendance_date, a); });
    const woSet = new Set(); offs.forEach(o => { for (let d = o.start_date; d <= (o.end_date || o.start_date); d = shift(d, 1)) woSet.add(d); });
    const leaveOn = d => leaves.find(l => l.from_date <= d && (l.to_date || l.from_date) >= d);

    const kinds = [], meta = new Map(); let work = 0, paired = 0;
    for (let i = 1; i <= lastDay(ym); i++) {
      const d = ym + '-' + pad(i);
      if (d > today) { meta.set(d, { f: 'F' }); continue; }
      if (r.doj && d < r.doj) { meta.set(d, { f: 'N' }); continue; }
      const a = rec.get(d), st = String(a && a.status || ''), L = leaveOn(d), P = a ? punchPair(attTimes(a)) : { ev: [], in: null, out: null };
      let k;
      if (P.ev.length || /present|work from home/i.test(st)) k = /half/i.test(st) ? 'HD' : 'P';
      else if (L && /approved/i.test(L.status)) k = 'L';
      else if (/leave/i.test(st)) k = 'L';
      else k = 'OFF';
      if (P.in != null && P.out != null) { work += P.out - P.in; paired++; }
      kinds.push({ date: d, k });
      meta.set(d, { in: P.in, out: P.out, roster: woSet.has(d) });
    }
    const m = applyWeekOff(kinds);
    kinds.forEach(x => Object.assign(meta.get(x.date), { f: x.f }));

    const dow = (new Date(+ym.slice(0,4), +ym.slice(5,7) - 1, 1).getDay() + 6) % 7;
    const label = new Date(first + 'T00:00:00').toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });
    const cells = []; for (let i = 1; i <= lastDay(ym); i++) { const d = ym + '-' + pad(i); cells.push({ d: i, date: d, f: (meta.get(d) || {}).f || 'U' }); }

    body.innerHTML =
      '<div class="a-mo">' +
        '<div class="a-moh"><button data-a-back>\u2039 All staff</button>' +
          '<span class="a-av big' + (r.sex ? ' g-' + r.sex : '') + '" data-ini="' + esc(r.ini) + '">' + (r.img ? '<img loading="lazy" src="' + esc(r.img) + '" alt="">' : '') + '</span>' +
          '<b>' + esc(r.name) + (r.badge ? '<em class="a-bg b-' + r.badge.c + '">' + esc(r.badge.s) + '</em>' : '') + '</b>' +
          '<small>' + esc(r.desig) + ' \u00b7 ' + esc(r.branch) + (r.dept ? ' \u00b7 ' + esc(r.dept) : '') + '</small>' +
          '<small class="a-ja">Job Age - ' + esc(r.age) + (r.doj ? ' \u00b7 joined ' + esc(r.doj) : '') + '</small>' +
          (r.phone ? '<small class="a-ph2">\u260E ' + esc(r.phoneKind) + ' ' + esc(r.phone) + (r.office && r.personal ? ' \u00b7 personal ' + esc(r.personal) : '') + '</small>' : '') +
          '<button class="a-leave" data-a-leave="' + esc(r.id) + '">\uD83C\uDF3F Apply leave in ERP \u2197</button></div>' +
        '<div class="a-mnav"><button data-a-month="-1">\u2039</button><span>' + esc(label) + '</span><button data-a-month="1">\u203A</button></div>' +
        '<div class="a-grid">' + ['Mo','Tu','We','Th','Fr','Sa','Su'].map(d => '<i class="a-dow">' + d + '</i>').join('') +
          (dow ? '<i style="grid-column:span ' + dow + '"></i>' : '') +
          cells.map(c => '<i class="a-day k' + c.f + (c.date === today ? ' now' : '') + '" title="' + esc(c.date) + '"><b>' + c.d + '</b><u>' +
            ({ P:'P', HD:'HD', A:'A', WO:'WO', L:'L', U:'\u2014', F:'', N:'' })[c.f] + '</u></i>').join('') + '</div>' +
        '<div class="a-tot"><i class="p">P ' + (m.P + m.HD) + '</i><i class="a">A ' + m.A + '</i><i class="w">WO ' + m.WO + '</i>' +
          '<i class="l">L ' + m.L + '</i><i class="e">Earned ' + m.earned + '</i>' + (m.left ? '<i class="e">Due ' + m.left + '</i>' : '') +
          '<i class="v">Payable ' + (m.P + m.HD * 0.5 + m.WO + m.L) + 'd</i><i class="v">Avg ' + esc(paired ? hm(work / paired) : '\u2014') + '</i></div>' +
        '<div class="a-leg">' + EARN_DAYS + ' present days earn one week off. In a continuous run of offs only the first counts as W/O, the rest are absent. Offs beyond what is earned are absent.</div>' +
        (woSet.size ? '<div class="a-leg">Roster: ' + woSet.size + ' planned week off date(s) from Shift Assignment.</div>' : '<div class="a-warn">\u26A0 No planned week off in the roster this month.</div>') +
        (leaves.length ? '<div class="a-leg">Leave: ' + leaves.map(l => esc(l.leave_type + ' ' + shortDate(l.from_date) + '\u2013' + shortDate(l.to_date) + ' \u00b7 ' + l.status)).join(' \u00b7 ') + '</div>' : '') +
      '</div>';
  } catch (err) {
    body.innerHTML = '<div class="a-err">' + esc(err.message) + '<br><button data-a-back>\u2039 Back</button></div>';
  }
}

/* ---- Excel export ------------------------------------------------------- */
const xE = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function cellX(v, s) { const num = typeof v === 'number';
  return '<Cell' + (s ? ' ss:StyleID="' + s + '"' : '') + '><Data ss:Type="' + (num ? 'Number' : 'String') + '">' + xE(num ? v : (v ?? '')) + '</Data></Cell>'; }
function sheetX(name, cols, head, body) {
  return '<Worksheet ss:Name="' + xE(name) + '"><Table>' + cols.map(w => '<Column ss:Width="' + w + '"/>').join('') +
    '<Row ss:Height="24">' + head.map(h => cellX(h, 'h')).join('') + '</Row>' +
    body.map(r => '<Row>' + r.map(c => cellX(c.v, c.s)).join('') + '</Row>').join('') +
    '</Table><WorksheetOptions xmlns="urn:schemas-microsoft-com:office:excel"><FreezePanes/><SplitHorizontal>1</SplitHorizontal><TopRowBottomPane>1</TopRowBottomPane><ActivePane>2</ActivePane></WorksheetOptions></Worksheet>';
}

function exportXls() {
  if (!S.data) return;
  if (!S.sc) { alert('Month figures are still loading. Try again in a moment.'); return; }
  const scope = S.data.list.filter(r => !S.branch || r.branch === S.branch);
  const days = lastDay(S.date.slice(0, 7));

  const salary = scope.map(r => { const m = S.sc.out.get(r.id) || {};
    return [
      { v: r.branch }, { v: r.id }, { v: r.device }, { v: r.name },
      { v: r.sex === 'f' ? 'Female' : r.sex === 'm' ? 'Male' : '' }, { v: r.badge ? r.badge.t : '' },
      { v: r.desig }, { v: r.grade }, { v: r.dept }, { v: r.etype },
      { v: r.doj, s: 'd' }, { v: r.age }, { v: S.date.slice(0, 7) }, { v: days },
      { v: m.eligible || 0 }, { v: m.full || 0 }, { v: m.HD || 0 }, { v: m.earned || 0 }, { v: m.WO || 0 },
